  `module` VARCHAR(40) NOT NULL,
  `description` TEXT NULL,
  `trigger_kind` VARCHAR(40) NOT NULL,
  `event_type` VARCHAR(80) NULL,
  `cron_expr` VARCHAR(60) NULL,
  `conditions` JSON NULL,
  `actions` JSON NULL,
  `is_system` TINYINT(1) NOT NULL DEFAULT 0,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `preview_until` DATETIME NULL COMMENT 'dry-run window after edits',
  `priority` SMALLINT NOT NULL DEFAULT 100,
  `cooldown_minutes` INT NULL,
  `run_count` BIGINT NOT NULL DEFAULT 0,
  `last_run_at` DATETIME NULL,
  `created_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_automation_rules_school_id` (`school_id`),
  KEY `ix_automation_rules_event_type` (`event_type`),
  KEY `ix_automation_rules_created_by` (`created_by`),
  UNIQUE KEY `uq_automation_rules_school_id_code` (`school_id`, `code`),
  CHECK (`trigger_kind` IN ('event', 'schedule', 'threshold', 'manual'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='WHEN trigger IF conditions (JSONLogic) THEN actions. Seeded system defaults are editable, not deletable.';

CREATE TABLE `automation_runs` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `rule_id` CHAR(26) NOT NULL,
  `trigger_event_uid` VARCHAR(36) NULL,
  `aggregate_type` VARCHAR(60) NULL,
  `aggregate_id` CHAR(26) NULL,
  `started_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `finished_at` DATETIME NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'running',
  `actions_result` JSON NULL,
  `error` TEXT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_automation_runs_school_id` (`school_id`),
  KEY `ix_automation_runs_rule_id` (`rule_id`),
  KEY `ix_automation_runs_rule_id_started_at` (`rule_id`, `started_at`),
  CHECK (`status` IN ('running', 'success', 'failed', 'skipped', 'preview'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='One row per rule execution with result/error.';

CREATE TABLE `scheduled_jobs` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `job_key` VARCHAR(80) NOT NULL,
  `cron_expr` VARCHAR(60) NOT NULL,
  `timezone` VARCHAR(40) NOT NULL DEFAULT 'Asia/Dhaka',
  `payload` JSON NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `next_run_at` DATETIME NULL,
  `last_run_at` DATETIME NULL,
  `last_status` VARCHAR(40) NULL,
  `last_duration_ms` INT NULL,
  `locked_until` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_scheduled_jobs_school_id` (`school_id`),
  KEY `ix_scheduled_jobs_next_run_at` (`next_run_at`),
  UNIQUE KEY `uq_scheduled_jobs_school_id_job_key` (`school_id`, `job_key`),
  CHECK (`last_status` IN ('success', 'failed', 'running'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Cron catalogue. On cPanel runs via one cron line or the request-driven heartbeat (web cron) with a lock.';

CREATE TABLE `background_jobs` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `queue` VARCHAR(40) NOT NULL,
  `job_name` VARCHAR(120) NOT NULL,
  `payload` JSON NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'pending',
  `attempts` SMALLINT NOT NULL DEFAULT 0,
  `max_attempts` SMALLINT NOT NULL DEFAULT 5,
  `scheduled_for` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `started_at` DATETIME NULL,
  `finished_at` DATETIME NULL,
  `progress_pct` DECIMAL(5,2) NOT NULL DEFAULT 0,
  `cursor` JSON NULL COMMENT 'resume point for chunked work (last row id, page, sheet row)',
  `total_items` INT NULL,
  `done_items` INT NOT NULL DEFAULT 0,
  `locked_until` DATETIME NULL,
  `result` JSON NULL,
  `error` TEXT NULL,
  `triggered_by` VARCHAR(80) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_background_jobs_school_id` (`school_id`),
  KEY `ix_background_jobs_school_id_status_scheduled_for` (`school_id`, `status`, `scheduled_for`),
  CHECK (`status` IN ('pending', 'running', 'success', 'failed', 'cancelled', 'paused'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Durable job queue (database driver on shared hosting). Long jobs run in chunks under 30 s each and resume from cursor.';

CREATE TABLE `approval_workflows` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `entity_type` VARCHAR(60) NOT NULL,
  `name` VARCHAR(120) NOT NULL,
  `conditions` JSON NULL,
  `steps` JSON NULL COMMENT '[{order:1, approver:{role:''hod''}}, {order:2, approver:{role:''principal''}}]',
  `auto_approve_after_hours` INT NULL,
  `escalate_after_hours` INT NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_approval_workflows_school_id` (`school_id`),
  UNIQUE KEY `uq_approval_workflows_school_id_entity_type_name` (`school_id`, `entity_type`, `name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Multi-step approvals: which entity, which conditions pick this workflow, ordered approver steps.';

CREATE TABLE `approval_requests` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `workflow_id` CHAR(26) NOT NULL,
  `entity_type` VARCHAR(60) NOT NULL,
  `entity_id` CHAR(26) NOT NULL,
  `requested_by` CHAR(26) NULL,
  `current_step` SMALLINT NOT NULL DEFAULT 1,
  `status` VARCHAR(40) NOT NULL DEFAULT 'pending',
  `summary` JSON NULL,
  `due_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_approval_requests_school_id` (`school_id`),
  KEY `ix_approval_requests_workflow_id` (`workflow_id`),
  KEY `ix_approval_requests_requested_by` (`requested_by`),
  UNIQUE KEY `uq_approval_requests_entity_type_entity_id` (`entity_type`, `entity_id`),
  KEY `ix_approval_requests_school_id_status` (`school_id`, `status`),
  CHECK (`status` IN ('pending', 'approved', 'rejected', 'cancelled', 'escalated'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='A pending/decided approval for one entity.';

CREATE TABLE `approval_actions` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `request_id` CHAR(26) NOT NULL,
  `step` SMALLINT NOT NULL,
  `actor_id` CHAR(26) NULL,
  `decision` VARCHAR(40) NOT NULL,
  `comment` TEXT NULL,
  `acted_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_approval_actions_school_id` (`school_id`),
  KEY `ix_approval_actions_request_id` (`request_id`),
  KEY `ix_approval_actions_actor_id` (`actor_id`),
  CHECK (`decision` IN ('approved', 'rejected', 'delegated', 'auto_approved', 'escalated'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Decision per step.';

CREATE TABLE `tasks` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `title` VARCHAR(200) NOT NULL,
  `description` TEXT NULL,
  `task_type` VARCHAR(40) NULL,
  `assigned_to` CHAR(26) NULL,
  `assigned_role` VARCHAR(60) NULL,
  `entity_type` VARCHAR(60) NULL,
  `entity_id` CHAR(26) NULL,
  `due_at` DATETIME NULL,
  `priority` VARCHAR(40) NOT NULL DEFAULT 'normal',
  `status` VARCHAR(40) NOT NULL DEFAULT 'open',
  `created_by` VARCHAR(80) NOT NULL DEFAULT 'system',
  `completed_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_tasks_school_id` (`school_id`),
  KEY `ix_tasks_assigned_to` (`assigned_to`),
  KEY `ix_tasks_assigned_to_status` (`assigned_to`, `status`),
  CHECK (`priority` IN ('low', 'normal', 'high', 'urgent')),
  CHECK (`status` IN ('open', 'in_progress', 'done', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='To-dos created by rules or people (call guardian, verify document, review lag).';

CREATE TABLE `form_definitions` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(160) NOT NULL,
  `slug` VARCHAR(80) NOT NULL,
  `purpose` VARCHAR(40) NOT NULL DEFAULT 'other',
  `schema_json` JSON NULL,
  `audience` JSON NULL,
  `is_public` TINYINT(1) NOT NULL DEFAULT 0,
  `opens_at` DATETIME NULL,
  `closes_at` DATETIME NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'draft',
  `created_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_form_definitions_school_id` (`school_id`),
  KEY `ix_form_definitions_created_by` (`created_by`),
  UNIQUE KEY `uq_form_definitions_school_id_slug` (`school_id`, `slug`),
  CHECK (`purpose` IN ('survey', 'admission', 'feedback', 'register', 'poll', 'consent', 'other')),
  CHECK (`status` IN ('draft', 'open', 'closed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='No-code form builder (surveys, admission forms, feedback, custom registers).';

CREATE TABLE `form_submissions` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `form_id` CHAR(26) NOT NULL,
  `submitted_by` CHAR(26) NULL,
  `entity_type` VARCHAR(60) NULL,
  `entity_id` CHAR(26) NULL,
  `answers` JSON NULL,
  `ip` VARCHAR(45) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_form_submissions_school_id` (`school_id`),
  KEY `ix_form_submissions_form_id` (`form_id`),
  KEY `ix_form_submissions_submitted_by` (`submitted_by`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Answers to a form.';

CREATE TABLE `workflow_definitions` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(160) NOT NULL,
  `entity_type` VARCHAR(60) NOT NULL,
  `states` JSON NULL,
  `transitions` JSON NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_workflow_definitions_school_id` (`school_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='No-code workflow builder: states and transitions for custom processes.';

CREATE TABLE `webhooks` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `url` VARCHAR(500) NOT NULL,
  `secret` VARCHAR(128) NOT NULL,
  `event_types` JSON NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `failure_count` INT NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_webhooks_school_id` (`school_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Outbound webhooks to school ERPs / Zapier.';

CREATE TABLE `webhook_deliveries` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `webhook_id` CHAR(26) NOT NULL,
  `event_uid` VARCHAR(36) NOT NULL,
  `attempt` SMALLINT NOT NULL DEFAULT 1,
  `response_code` SMALLINT NULL,
  `response_body` TEXT NULL,
  `delivered_at` DATETIME NULL,
  `next_retry_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_webhook_deliveries_school_id` (`school_id`),
  KEY `ix_webhook_deliveries_webhook_id` (`webhook_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Delivery attempts.';

CREATE TABLE `integrations` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `provider` VARCHAR(60) NOT NULL,
  `category` VARCHAR(40) NOT NULL,
  `config` JSON NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'connected',
  `last_sync_at` DATETIME NULL,
  `last_error` TEXT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_integrations_school_id` (`school_id`),
  UNIQUE KEY `uq_integrations_school_id_provider` (`school_id`, `provider`),
  CHECK (`category` IN ('meeting', 'sso', 'device', 'gps', 'payment', 'sms', 'email', 'storage', 'ai', 'accounting', 'other')),
  CHECK (`status` IN ('connected', 'failed', 'disconnected'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Connected providers (Zoom, Google, ZKTeco cloud, GPS vendor, gateways) with encrypted config.';

CREATE TABLE `api_keys` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(120) NOT NULL,
  `key_prefix` VARCHAR(12) NOT NULL,
  `key_hash` VARCHAR(128) NOT NULL,
  `scopes` JSON NULL,
  `rate_limit_per_min` INT NOT NULL DEFAULT 120,
  `expires_at` DATETIME NULL,
  `last_used_at` DATETIME NULL,
  `created_by` CHAR(26) NULL,
  `revoked_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_api_keys_school_id` (`school_id`),
  UNIQUE KEY `uq_api_keys_key_hash` (`key_hash`),
  KEY `ix_api_keys_created_by` (`created_by`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Keys for third-party apps and integrations.';

CREATE TABLE `report_definitions` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(160) NOT NULL,
  `module` VARCHAR(40) NOT NULL,
  `definition` JSON NULL,
  `output_format` VARCHAR(40) NOT NULL DEFAULT 'pdf',
  `cron_expr` VARCHAR(60) NULL,
  `recipients` JSON NULL,
  `is_system` TINYINT(1) NOT NULL DEFAULT 0,
  `created_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_report_definitions_school_id` (`school_id`),
  KEY `ix_report_definitions_created_by` (`created_by`),
  CHECK (`output_format` IN ('pdf', 'xlsx', 'csv', 'html'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Report builder: saved queries/pivots with schedule and recipients.';

CREATE TABLE `report_snapshots` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `definition_id` CHAR(26) NOT NULL,
  `params` JSON NULL,
  `file_id` CHAR(26) NULL,
  `row_count` INT NULL,
  `generated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_report_snapshots_school_id` (`school_id`),
  KEY `ix_report_snapshots_definition_id` (`definition_id`),
  KEY `ix_report_snapshots_file_id` (`file_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Generated report files.';

CREATE TABLE `kpi_daily` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `day` DATE NOT NULL,
  `students_active` INT NULL,
  `attendance_pct` DECIMAL(5,2) NULL,
  `staff_attendance_pct` DECIMAL(5,2) NULL,
  `fees_collected` DECIMAL(14,2) NULL,
  `fees_outstanding` DECIMAL(14,2) NULL,
  `new_enquiries` INT NULL,
  `new_admissions` INT NULL,
  `sms_sent` INT NULL,
  `extra` JSON NULL,
  PRIMARY KEY (`id`),
  KEY `ix_kpi_daily_school_id` (`school_id`),
  UNIQUE KEY `uq_kpi_daily_school_id_day` (`school_id`, `day`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Daily KPI snapshot per school for dashboards and anomaly alerts.';

CREATE TABLE `import_jobs` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `entity_type` VARCHAR(60) NOT NULL,
  `file_id` CHAR(26) NOT NULL,
  `mapping` JSON NULL,
  `total_rows` INT NULL,
  `success_rows` INT NULL,
  `error_rows` INT NULL,
  `errors_file_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'pending',
  `created_by` CHAR(26) NULL,
  `finished_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_import_jobs_school_id` (`school_id`),
  KEY `ix_import_jobs_file_id` (`file_id`),
  KEY `ix_import_jobs_errors_file_id` (`errors_file_id`),
  KEY `ix_import_jobs_created_by` (`created_by`),
  CHECK (`status` IN ('pending', 'validating', 'running', 'success', 'failed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Bulk Excel/CSV imports with mapping, validation and error file.';

CREATE TABLE `backups` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `kind` VARCHAR(40) NOT NULL,
  `target` VARCHAR(40) NOT NULL DEFAULT 'local',
  `file_path` VARCHAR(500) NULL,
  `size_bytes` BIGINT NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'running',
  `started_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `finished_at` DATETIME NULL,
  `error` TEXT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_backups_school_id` (`school_id`),
  CHECK (`kind` IN ('database', 'files', 'full')),
  CHECK (`target` IN ('local', 'gdrive', 'dropbox', 's3')),
  CHECK (`status` IN ('running', 'success', 'failed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Automated backups (DB dump + files) to local, Google Drive, Dropbox or S3.';

CREATE TABLE `notifications_queue_stats` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `hour` DATETIME NOT NULL,
  `channel` VARCHAR(20) NOT NULL,
  `sent` INT NOT NULL DEFAULT 0,
  `delivered` INT NOT NULL DEFAULT 0,
  `failed` INT NOT NULL DEFAULT 0,
  `cost` DECIMAL(14,2) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `ix_notifications_queue_stats_school_id` (`school_id`),
  UNIQUE KEY `uq_notifications_queue_stats_school_id_hour_channel` (`school_id`, `hour`, `channel`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Hourly rollup of notification volume and cost (for the health page).';


-- ============ SaaS billing & partners ============
CREATE TABLE `saas_plans` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `name` VARCHAR(80) NOT NULL,
  `price_monthly` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `price_yearly` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `currency` VARCHAR(3) NOT NULL DEFAULT 'BDT',
  `student_limit` INT NULL,
  `sms_included` INT NOT NULL DEFAULT 0,
  `storage_gb` INT NOT NULL DEFAULT 5,
  `modules` JSON NULL,
  `is_public` TINYINT(1) NOT NULL DEFAULT 1,
  `sort_order` SMALLINT NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_saas_plans_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Pricing plans with limits and enabled modules.';

CREATE TABLE `saas_subscriptions` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `plan_id` CHAR(26) NOT NULL,
  `billing_cycle` VARCHAR(40) NOT NULL DEFAULT 'yearly',
  `starts_at` DATE NOT NULL,
  `ends_at` DATE NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'trial',
  `auto_renew` TINYINT(1) NOT NULL DEFAULT 1,
  `price` DECIMAL(14,2) NOT NULL,
  `discount_pct` DECIMAL(5,2) NOT NULL DEFAULT 0,
  `reseller_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_saas_subscriptions_school_id` (`school_id`),
  KEY `ix_saas_subscriptions_plan_id` (`plan_id`),
  KEY `ix_saas_subscriptions_reseller_id` (`reseller_id`),
  CHECK (`billing_cycle` IN ('monthly', 'yearly')),
  CHECK (`status` IN ('trial', 'active', 'past_due', 'cancelled', 'expired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='A school’s subscription to a plan.';

CREATE TABLE `saas_invoices` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `subscription_id` CHAR(26) NULL,
  `invoice_no` VARCHAR(30) NOT NULL,
  `period_start` DATE NOT NULL,
  `period_end` DATE NOT NULL,
  `amount` DECIMAL(14,2) NOT NULL,
  `tax` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `total` DECIMAL(14,2) NOT NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'issued',
  `due_date` DATE NOT NULL,
  `paid_at` DATETIME NULL,
  `payment_ref` VARCHAR(120) NULL,
  `pdf_file_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_saas_invoices_school_id` (`school_id`),
  KEY `ix_saas_invoices_subscription_id` (`subscription_id`),
  UNIQUE KEY `uq_saas_invoices_invoice_no` (`invoice_no`),
  KEY `ix_saas_invoices_pdf_file_id` (`pdf_file_id`),
  CHECK (`status` IN ('draft', 'issued', 'paid', 'overdue', 'void'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Invoices from the platform to the school.';

CREATE TABLE `saas_usage` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `month` DATE NOT NULL,
  `metric` VARCHAR(40) NOT NULL,
  `quantity` BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `ix_saas_usage_school_id` (`school_id`),
  UNIQUE KEY `uq_saas_usage_school_id_month_metric` (`school_id`, `month`, `metric`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Metered usage per month (students, SMS, storage, API calls).';

CREATE TABLE `saas_partners` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `name` VARCHAR(160) NOT NULL,
  `contact` JSON NULL,
  `commission_pct` DECIMAL(5,2) NOT NULL DEFAULT 0,
  `referral_code` VARCHAR(30) NOT NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_saas_partners_referral_code` (`referral_code`),
  CHECK (`status` IN ('active', 'inactive'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Resellers / referral partners earning commission.';

CREATE TABLE `saas_partner_payouts` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `partner_id` CHAR(26) NOT NULL,
  `period` DATE NOT NULL,
  `amount` DECIMAL(14,2) NOT NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'pending',
  `paid_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_saas_partner_payouts_partner_id` (`partner_id`),
  CHECK (`status` IN ('pending', 'paid'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Commission payouts.';

CREATE TABLE `saas_support_tickets` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `subject` VARCHAR(200) NOT NULL,
  `body` TEXT NULL,
  `priority` VARCHAR(40) NOT NULL DEFAULT 'normal',
  `status` VARCHAR(40) NOT NULL DEFAULT 'open',
  `opened_by` CHAR(26) NULL,
  `assigned_to` VARCHAR(120) NULL,
  `closed_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_saas_support_tickets_school_id` (`school_id`),
  KEY `ix_saas_support_tickets_opened_by` (`opened_by`),
  CHECK (`priority` IN ('low', 'normal', 'high', 'urgent')),
  CHECK (`status` IN ('open', 'answered', 'closed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Schools’ support requests to the platform team.';


-- ============ Website & CMS ============
CREATE TABLE `cms_pages` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `title` VARCHAR(200) NOT NULL,
  `slug` VARCHAR(120) NOT NULL,
  `locale` VARCHAR(10) NOT NULL DEFAULT 'bn',
  `blocks` JSON NULL,
  `seo` JSON NULL,
  `is_home` TINYINT(1) NOT NULL DEFAULT 0,
  `status` VARCHAR(40) NOT NULL DEFAULT 'draft',
  `published_at` DATETIME NULL,
  `author_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` DATETIME NULL COMMENT 'Soft delete',
  PRIMARY KEY (`id`),
  KEY `ix_cms_pages_school_id` (`school_id`),
  KEY `ix_cms_pages_author_id` (`author_id`),
  UNIQUE KEY `uq_cms_pages_school_id_slug_locale` (`school_id`, `slug`, `locale`),
  CHECK (`status` IN ('draft', 'published'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Public pages built from blocks.';

CREATE TABLE `cms_posts` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `title` VARCHAR(200) NOT NULL,
  `slug` VARCHAR(120) NOT NULL,
  `category` VARCHAR(60) NULL,
  `excerpt` TEXT NULL,
  `body` LONGTEXT NULL,
  `cover_file_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'draft',
  `published_at` DATETIME NULL,
  `author_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` DATETIME NULL COMMENT 'Soft delete',
  PRIMARY KEY (`id`),
  KEY `ix_cms_posts_school_id` (`school_id`),
  KEY `ix_cms_posts_cover_file_id` (`cover_file_id`),
  KEY `ix_cms_posts_author_id` (`author_id`),
  UNIQUE KEY `uq_cms_posts_school_id_slug` (`school_id`, `slug`),
  CHECK (`status` IN ('draft', 'published'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='News, blog, achievements.';

CREATE TABLE `cms_menus` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(60) NOT NULL,
  `items` JSON NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_cms_menus_school_id` (`school_id`),
  UNIQUE KEY `uq_cms_menus_school_id_name` (`school_id`, `name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Navigation menus.';

CREATE TABLE `cms_galleries` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `title` VARCHAR(200) NOT NULL,
  `description` TEXT NULL,
  `cover_file_id` CHAR(26) NULL,
  `is_public` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_cms_galleries_school_id` (`school_id`),
  KEY `ix_cms_galleries_cover_file_id` (`cover_file_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Photo/video albums.';

CREATE TABLE `cms_gallery_items` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `gallery_id` CHAR(26) NOT NULL,
  `file_id` CHAR(26) NULL,
  `video_url` VARCHAR(500) NULL,
  `caption` VARCHAR(255) NULL,
  `sort_order` SMALLINT NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `ix_cms_gallery_items_school_id` (`school_id`),
  KEY `ix_cms_gallery_items_gallery_id` (`gallery_id`),
  KEY `ix_cms_gallery_items_file_id` (`file_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Album items.';

CREATE TABLE `cms_themes` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `name` VARCHAR(80) NOT NULL,
  `preview_file_id` CHAR(26) NULL,
  `tokens` JSON NULL,
  `is_default` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cms_themes_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Website themes.';

CREATE TABLE `cms_domains` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `domain` VARCHAR(160) NOT NULL,
  `is_primary` TINYINT(1) NOT NULL DEFAULT 0,
  `ssl_status` VARCHAR(40) NOT NULL DEFAULT 'pending',
  `verified_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_cms_domains_school_id` (`school_id`),
  UNIQUE KEY `uq_cms_domains_domain` (`domain`),
  CHECK (`ssl_status` IN ('pending', 'active', 'failed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Custom domains and SSL status for a school site.';

CREATE TABLE `cms_contact_messages` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(160) NOT NULL,
  `phone` VARCHAR(30) NULL,
  `email` VARCHAR(160) NULL,
  `message` TEXT NOT NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'new',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_cms_contact_messages_school_id` (`school_id`),
  CHECK (`status` IN ('new', 'read', 'replied'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Messages from the website contact form.';


-- ============ Academic structure ============
CREATE TABLE `academic_years` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(20) NOT NULL,
  `start_date` DATE NOT NULL,
  `end_date` DATE NOT NULL,
  `is_current` TINYINT(1) NOT NULL DEFAULT 0,
  `status` VARCHAR(40) NOT NULL DEFAULT 'planned',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_academic_years_school_id` (`school_id`),
  UNIQUE KEY `uq_academic_years_school_id_name` (`school_id`, `name`),
  CHECK (`status` IN ('planned', 'active', 'closed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Session. Only one is current.';

CREATE TABLE `terms` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `academic_year_id` CHAR(26) NOT NULL,
  `name` VARCHAR(60) NOT NULL,
  `sequence` SMALLINT NOT NULL,
  `start_date` DATE NOT NULL,
  `end_date` DATE NOT NULL,
  `kind` VARCHAR(40) NOT NULL DEFAULT 'term',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_terms_school_id` (`school_id`),
  KEY `ix_terms_academic_year_id` (`academic_year_id`),
  UNIQUE KEY `uq_terms_academic_year_id_sequence` (`academic_year_id`, `sequence`),
  CHECK (`kind` IN ('term', 'semester', 'trimester'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Terms (school) or semesters (college) inside a year.';

CREATE TABLE `shifts` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(40) NOT NULL,
  `start_time` TIME NOT NULL,
  `end_time` TIME NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_shifts_school_id` (`school_id`),
  UNIQUE KEY `uq_shifts_school_id_name` (`school_id`, `name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Morning / Day shifts with times.';

CREATE TABLE `programs` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(120) NOT NULL,
  `code` VARCHAR(20) NOT NULL,
  `level` VARCHAR(40) NOT NULL,
  `duration_terms` SMALLINT NULL,
  `total_credits` DECIMAL(5,1) NULL,
  `department_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_programs_school_id` (`school_id`),
  UNIQUE KEY `uq_programs_school_id_code` (`school_id`, `code`),
  CHECK (`level` IN ('secondary', 'higher_secondary', 'bachelor', 'master', 'diploma', 'coaching')),
  CHECK (`status` IN ('active', 'inactive'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='College/university programmes (HSC Science, BBA…) or coaching courses. Schools may ignore.';

CREATE TABLE `classes` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(60) NOT NULL,
  `name_bn` VARCHAR(60) NULL,
  `numeric_level` SMALLINT NOT NULL,
  `stream` VARCHAR(40) NULL COMMENT 'Science | Arts | Commerce | Hifz | Dakhil',
  `program_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_classes_school_id` (`school_id`),
  KEY `ix_classes_program_id` (`program_id`),
  UNIQUE KEY `uq_classes_school_id_name` (`school_id`, `name`),
  CHECK (`status` IN ('active', 'inactive'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Grade level: Play, Nursery, KG, 1–12 (or programme year).';

CREATE TABLE `rooms` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `campus_id` CHAR(26) NOT NULL,
  `name` VARCHAR(60) NOT NULL,
  `building` VARCHAR(60) NULL,
  `floor` VARCHAR(20) NULL,
  `capacity` SMALLINT NULL,
  `room_type` VARCHAR(40) NOT NULL DEFAULT 'classroom',
  `amenities` JSON NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_rooms_school_id` (`school_id`),
  KEY `ix_rooms_campus_id` (`campus_id`),
  UNIQUE KEY `uq_rooms_campus_id_name` (`campus_id`, `name`),
  CHECK (`room_type` IN ('classroom', 'lab', 'hall', 'library', 'office', 'playground', 'other'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Physical rooms; used by timetable, exams, events, bookings.';

CREATE TABLE `sections` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `academic_year_id` CHAR(26) NOT NULL,
  `class_id` CHAR(26) NOT NULL,
  `campus_id` CHAR(26) NULL,
  `shift_id` CHAR(26) NULL,
  `name` VARCHAR(40) NOT NULL,
  `capacity` SMALLINT NOT NULL DEFAULT 40,
  `room_id` CHAR(26) NULL,
  `class_teacher_id` CHAR(26) NULL,
  `gender_policy` VARCHAR(40) NOT NULL DEFAULT 'mixed',
  `medium` VARCHAR(40) NOT NULL DEFAULT 'bangla',
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_sections_school_id` (`school_id`),
  KEY `ix_sections_academic_year_id` (`academic_year_id`),
  KEY `ix_sections_class_id` (`class_id`),
  KEY `ix_sections_campus_id` (`campus_id`),
  KEY `ix_sections_shift_id` (`shift_id`),
  KEY `ix_sections_room_id` (`room_id`),
  UNIQUE KEY `uq_sections_academic_year_id_class_id_name` (`academic_year_id`, `class_id`, `name`),
  CHECK (`gender_policy` IN ('mixed', 'boys', 'girls')),
  CHECK (`medium` IN ('bangla', 'english', 'arabic')),
  CHECK (`status` IN ('active', 'inactive'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Section (school) or batch (coaching) of a class in a year.';

CREATE TABLE `subjects` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(120) NOT NULL,
  `name_bn` VARCHAR(120) NULL,
  `code` VARCHAR(20) NOT NULL,
  `subject_type` VARCHAR(40) NOT NULL DEFAULT 'theory',
  `is_optional` TINYINT(1) NOT NULL DEFAULT 0,
  `department_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_subjects_school_id` (`school_id`),
  UNIQUE KEY `uq_subjects_school_id_code` (`school_id`, `code`),
  CHECK (`subject_type` IN ('theory', 'practical', 'both', 'activity')),
  CHECK (`status` IN ('active', 'inactive'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Subject catalogue with board codes.';

CREATE TABLE `class_subjects` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `academic_year_id` CHAR(26) NOT NULL,
  `class_id` CHAR(26) NOT NULL,
  `subject_id` CHAR(26) NOT NULL,
  `is_compulsory` TINYINT(1) NOT NULL DEFAULT 1,
  `full_marks` DECIMAL(6,2) NOT NULL DEFAULT 100,
  `pass_marks` DECIMAL(6,2) NOT NULL DEFAULT 33,
  `theory_marks` DECIMAL(6,2) NULL,
  `practical_marks` DECIMAL(6,2) NULL,
  `ca_marks` DECIMAL(6,2) NULL,
  `credit` DECIMAL(4,2) NOT NULL DEFAULT 1,
  `weekly_periods` SMALLINT NOT NULL DEFAULT 5,
  `sort_order` SMALLINT NOT NULL DEFAULT 0,
  `assessment_mode` VARCHAR(40) NOT NULL DEFAULT 'marks' COMMENT 'NCTB 2023+ competency-based support',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_class_subjects_school_id` (`school_id`),
  KEY `ix_class_subjects_academic_year_id` (`academic_year_id`),
  KEY `ix_class_subjects_class_id` (`class_id`),
  KEY `ix_class_subjects_subject_id` (`subject_id`),
  UNIQUE KEY `uq_class_subjects_academic_year_id_class_id_subject_id` (`academic_year_id`, `class_id`, `subject_id`),
  CHECK (`assessment_mode` IN ('marks', 'competency', 'both'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Which subjects a class studies in a year and how they are marked (full/pass marks, theory/practical/CA split, credit).';

CREATE TABLE `student_subject_choices` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `class_subject_id` CHAR(26) NOT NULL,
  `is_fourth` TINYINT(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `ix_student_subject_choices_school_id` (`school_id`),
  KEY `ix_student_subject_choices_student_id` (`student_id`),
  KEY `ix_student_subject_choices_class_subject_id` (`class_subject_id`),
  UNIQUE KEY `uq_student_subject_choices_student_id_class_subject_id` (`student_id`, `class_subject_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Optional/4th subject choice per student.';

CREATE TABLE `periods` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `shift_id` CHAR(26) NULL,
  `name` VARCHAR(30) NOT NULL,
  `sequence` SMALLINT NOT NULL,
  `start_time` TIME NOT NULL,
  `end_time` TIME NOT NULL,
  `is_break` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_periods_school_id` (`school_id`),
  KEY `ix_periods_shift_id` (`shift_id`),
  UNIQUE KEY `uq_periods_school_id_shift_id_sequence` (`school_id`, `shift_id`, `sequence`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Period grid per shift.';

CREATE TABLE `houses` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(60) NOT NULL,
  `color` VARCHAR(20) NULL,
  `points` INT NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_houses_school_id` (`school_id`),
  UNIQUE KEY `uq_houses_school_id_name` (`school_id`, `name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Houses for sports/points.';

CREATE TABLE `calendar_events` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `academic_year_id` CHAR(26) NULL,
  `title` VARCHAR(200) NOT NULL,
  `event_type` VARCHAR(40) NOT NULL,
  `start_date` DATE NOT NULL,
  `end_date` DATE NOT NULL,
  `is_holiday` TINYINT(1) NOT NULL DEFAULT 0,
  `applies_to` JSON NULL,
  `description` TEXT NULL,
  `created_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_calendar_events_school_id` (`school_id`),
  KEY `ix_calendar_events_academic_year_id` (`academic_year_id`),
  KEY `ix_calendar_events_created_by` (`created_by`),
  KEY `ix_calendar_events_school_id_start_date_end_date` (`school_id`, `start_date`, `end_date`),
  CHECK (`event_type` IN ('holiday', 'vacation', 'exam', 'event', 'ptm', 'deadline', 'meeting'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Holidays, vacations, exam windows, events. Holidays drive attendance and reminder automation.';

CREATE TABLE `weekly_offs` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `day_of_week` SMALLINT NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_weekly_offs_school_id` (`school_id`),
  UNIQUE KEY `uq_weekly_offs_school_id_day_of_week` (`school_id`, `day_of_week`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Weekend days (BD: Fri, Sat).';

CREATE TABLE `hifz_progress` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `recorded_on` DATE NOT NULL,
  `para` SMALLINT NULL,
  `surah` SMALLINT NULL,
  `ayah_from` SMALLINT NULL,
  `ayah_to` SMALLINT NULL,
  `kind` VARCHAR(40) NOT NULL DEFAULT 'new',
  `quality` VARCHAR(40) NULL,
  `teacher_id` CHAR(26) NULL,
  `remarks` TEXT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_hifz_progress_school_id` (`school_id`),
  KEY `ix_hifz_progress_student_id` (`student_id`),
  CHECK (`kind` IN ('new', 'revision', 'test')),
  CHECK (`quality` IN ('excellent', 'good', 'fair', 'weak'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Madrasa: Quran memorisation tracking per student (para/surah/ayah, revision).';


-- ============ People · students, guardians, staff ============
CREATE TABLE `departments` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(80) NOT NULL,
  `head_staff_id` CHAR(26) NULL,
  `kind` VARCHAR(40) NOT NULL DEFAULT 'academic',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_departments_school_id` (`school_id`),
  UNIQUE KEY `uq_departments_school_id_name` (`school_id`, `name`),
  CHECK (`kind` IN ('academic', 'admin', 'support'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Academic and admin departments.';

CREATE TABLE `designations` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(80) NOT NULL,
  `level` SMALLINT NOT NULL DEFAULT 0,
  `category` VARCHAR(40) NOT NULL DEFAULT 'teaching',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_designations_school_id` (`school_id`),
  UNIQUE KEY `uq_designations_school_id_name` (`school_id`, `name`),
  CHECK (`category` IN ('teaching', 'non_teaching', 'admin', 'support'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Job titles with hierarchy level.';

CREATE TABLE `staff` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `user_id` CHAR(26) NULL,
  `employee_no` VARCHAR(30) NOT NULL,
  `first_name` VARCHAR(80) NOT NULL,
  `last_name` VARCHAR(80) NULL,
  `name_bn` VARCHAR(160) NULL,
  `gender` VARCHAR(40) NULL,
  `date_of_birth` DATE NULL,
  `phone` VARCHAR(20) NULL,
  `email` VARCHAR(160) NULL,
  `nid_no` VARCHAR(30) NULL,
  `photo_file_id` CHAR(26) NULL,
  `campus_id` CHAR(26) NULL,
  `department_id` CHAR(26) NULL,
  `designation_id` CHAR(26) NULL,
  `reports_to_id` CHAR(26) NULL,
  `staff_category` VARCHAR(40) NOT NULL DEFAULT 'teaching',
  `employment_type` VARCHAR(40) NOT NULL DEFAULT 'permanent',
  `mpo_index_no` VARCHAR(30) NULL COMMENT 'MPO listed teacher index',
  `join_date` DATE NOT NULL,
  `probation_end` DATE NULL,
  `leave_date` DATE NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `address` JSON NULL,
  `emergency_contact` JSON NULL,
  `bank_details` JSON NULL,
  `biometric_id` VARCHAR(40) NULL,
  `rfid_tag` VARCHAR(40) NULL,
  `meta` JSON NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` DATETIME NULL COMMENT 'Soft delete',
  PRIMARY KEY (`id`),
  KEY `ix_staff_school_id` (`school_id`),
  UNIQUE KEY `uq_staff_user_id` (`user_id`),
  KEY `ix_staff_photo_file_id` (`photo_file_id`),
  KEY `ix_staff_campus_id` (`campus_id`),
  KEY `ix_staff_department_id` (`department_id`),
  KEY `ix_staff_designation_id` (`designation_id`),
  KEY `ix_staff_reports_to_id` (`reports_to_id`),
  UNIQUE KEY `uq_staff_school_id_employee_no` (`school_id`, `employee_no`),
  CHECK (`gender` IN ('male', 'female', 'other')),
  CHECK (`staff_category` IN ('teaching', 'non_teaching', 'admin', 'support')),
  CHECK (`employment_type` IN ('permanent', 'contract', 'part_time', 'intern', 'volunteer', 'mpo')),
  CHECK (`status` IN ('active', 'probation', 'on_leave', 'resigned', 'terminated', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Employee master.';

CREATE TABLE `staff_qualifications` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `staff_id` CHAR(26) NOT NULL,
  `degree` VARCHAR(120) NOT NULL,
  `institution` VARCHAR(160) NULL,
  `passing_year` SMALLINT NULL,
  `result` VARCHAR(40) NULL,
  `file_id` CHAR(26) NULL,
  PRIMARY KEY (`id`),
  KEY `ix_staff_qualifications_school_id` (`school_id`),
  KEY `ix_staff_qualifications_staff_id` (`staff_id`),
  KEY `ix_staff_qualifications_file_id` (`file_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Degrees.';

CREATE TABLE `staff_subjects` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `staff_id` CHAR(26) NOT NULL,
  `subject_id` CHAR(26) NOT NULL,
  `preference` SMALLINT NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `ix_staff_subjects_school_id` (`school_id`),
  KEY `ix_staff_subjects_staff_id` (`staff_id`),
  KEY `ix_staff_subjects_subject_id` (`subject_id`),
  UNIQUE KEY `uq_staff_subjects_staff_id_subject_id` (`staff_id`, `subject_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Subjects a teacher can teach (timetable + substitution engine).';

CREATE TABLE `staff_documents` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `staff_id` CHAR(26) NOT NULL,
  `doc_type` VARCHAR(60) NOT NULL,
  `file_id` CHAR(26) NOT NULL,
  `expires_at` DATE NULL,
  `verified_by` CHAR(26) NULL,
  `verified_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_staff_documents_school_id` (`school_id`),
  KEY `ix_staff_documents_staff_id` (`staff_id`),
  KEY `ix_staff_documents_file_id` (`file_id`),
  KEY `ix_staff_documents_verified_by` (`verified_by`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='NID, certificates, contracts with expiry reminders.';

CREATE TABLE `students` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `user_id` CHAR(26) NULL,
  `admission_no` VARCHAR(30) NOT NULL,
  `first_name` VARCHAR(80) NOT NULL,
  `last_name` VARCHAR(80) NULL,
  `name_bn` VARCHAR(160) NULL,
  `gender` VARCHAR(40) NOT NULL,
  `date_of_birth` DATE NOT NULL,
  `blood_group` VARCHAR(5) NULL,
  `religion` VARCHAR(30) NULL,
  `nationality` VARCHAR(40) NOT NULL DEFAULT 'Bangladeshi',
  `birth_certificate_no` VARCHAR(30) NULL,
  `nid_no` VARCHAR(30) NULL,
  `photo_file_id` CHAR(26) NULL,
  `admission_date` DATE NOT NULL,
  `admission_class_id` CHAR(26) NULL,
  `current_academic_year_id` CHAR(26) NULL,
  `current_class_id` CHAR(26) NULL,
  `current_section_id` CHAR(26) NULL,
  `current_roll_no` VARCHAR(10) NULL,
  `house_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `status_changed_at` DATETIME NULL,
  `status_reason` VARCHAR(255) NULL,
  `present_address` JSON NULL,
  `permanent_address` JSON NULL,
  `previous_school` JSON NULL,
  `medical_summary` JSON NULL,
  `special_needs` JSON NULL COMMENT 'accommodations, IEP flag',
  `biometric_id` VARCHAR(40) NULL,
  `rfid_tag` VARCHAR(40) NULL,
  `wallet_id` CHAR(26) NULL COMMENT '→ wallets',
  `meta` JSON NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` DATETIME NULL COMMENT 'Soft delete',
  PRIMARY KEY (`id`),
  KEY `ix_students_school_id` (`school_id`),
  UNIQUE KEY `uq_students_user_id` (`user_id`),
  KEY `ix_students_photo_file_id` (`photo_file_id`),
  KEY `ix_students_admission_class_id` (`admission_class_id`),
  KEY `ix_students_current_academic_year_id` (`current_academic_year_id`),
  KEY `ix_students_current_class_id` (`current_class_id`),
  KEY `ix_students_current_section_id` (`current_section_id`),
  KEY `ix_students_house_id` (`house_id`),
  UNIQUE KEY `uq_students_school_id_admission_no` (`school_id`, `admission_no`),
  KEY `ix_students_school_id_current_section_id_status` (`school_id`, `current_section_id`, `status`),
  CHECK (`gender` IN ('male', 'female', 'other')),
  CHECK (`status` IN ('applicant', 'active', 'suspended', 'graduated', 'transferred', 'dropped', 'alumni'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Student master with denormalised current pointers.';

CREATE TABLE `student_enrollments` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `academic_year_id` CHAR(26) NOT NULL,
  `class_id` CHAR(26) NOT NULL,
  `section_id` CHAR(26) NULL,
  `program_id` CHAR(26) NULL,
  `roll_no` VARCHAR(10) NULL,
  `enrolled_on` DATE NOT NULL,
  `left_on` DATE NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `promoted_from_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_student_enrollments_school_id` (`school_id`),
  KEY `ix_student_enrollments_student_id` (`student_id`),
  KEY `ix_student_enrollments_academic_year_id` (`academic_year_id`),
  KEY `ix_student_enrollments_class_id` (`class_id`),
  KEY `ix_student_enrollments_section_id` (`section_id`),
  KEY `ix_student_enrollments_program_id` (`program_id`),
  KEY `ix_student_enrollments_promoted_from_id` (`promoted_from_id`),
  UNIQUE KEY `uq_student_enrollments_student_id_academic_year_id` (`student_id`, `academic_year_id`),
  KEY `ix_student_enrollments_section_id_roll_no` (`section_id`, `roll_no`),
  CHECK (`status` IN ('active', 'promoted', 'retained', 'transferred', 'left', 'graduated'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='One row per student per academic year: class, section, roll. Full history.';

CREATE TABLE `guardians` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `user_id` CHAR(26) NULL,
  `full_name` VARCHAR(160) NOT NULL,
  `phone` VARCHAR(20) NOT NULL,
  `alt_phone` VARCHAR(20) NULL,
  `email` VARCHAR(160) NULL,
  `occupation` VARCHAR(80) NULL,
  `nid_no` VARCHAR(30) NULL,
  `monthly_income` DECIMAL(14,2) NULL,
  `address` JSON NULL,
  `photo_file_id` CHAR(26) NULL,
  `is_staff` TINYINT(1) NOT NULL DEFAULT 0 COMMENT 'staff-child discount rule',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_guardians_school_id` (`school_id`),
  UNIQUE KEY `uq_guardians_user_id` (`user_id`),
  KEY `ix_guardians_photo_file_id` (`photo_file_id`),
  UNIQUE KEY `uq_guardians_school_id_phone` (`school_id`, `phone`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Guardian keyed by phone; same phone = same guardian = siblings.';

CREATE TABLE `student_guardians` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `guardian_id` CHAR(26) NOT NULL,
  `relation` VARCHAR(40) NOT NULL,
  `is_primary` TINYINT(1) NOT NULL DEFAULT 0,
  `is_emergency` TINYINT(1) NOT NULL DEFAULT 0,
  `can_pickup` TINYINT(1) NOT NULL DEFAULT 1,
  `receives_notifications` TINYINT(1) NOT NULL DEFAULT 1,
  `pays_fees` TINYINT(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `ix_student_guardians_school_id` (`school_id`),
  KEY `ix_student_guardians_student_id` (`student_id`),
  KEY `ix_student_guardians_guardian_id` (`guardian_id`),
  UNIQUE KEY `uq_student_guardians_student_id_guardian_id` (`student_id`, `guardian_id`),
  CHECK (`relation` IN ('father', 'mother', 'grandparent', 'sibling', 'uncle', 'aunt', 'legal_guardian', 'other'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Student ↔ guardian with relation and rights.';

CREATE TABLE `pickup_authorisations` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `person_name` VARCHAR(160) NOT NULL,
  `relation` VARCHAR(60) NULL,
  `phone` VARCHAR(20) NULL,
  `photo_file_id` CHAR(26) NULL,
  `id_proof` VARCHAR(60) NULL,
  `valid_from` DATE NULL,
  `valid_to` DATE NULL,
  `is_one_time` TINYINT(1) NOT NULL DEFAULT 0,
  `approved_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_pickup_authorisations_school_id` (`school_id`),
  KEY `ix_pickup_authorisations_student_id` (`student_id`),
  KEY `ix_pickup_authorisations_photo_file_id` (`photo_file_id`),
  KEY `ix_pickup_authorisations_approved_by` (`approved_by`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='KG/primary: who may collect the child; photo + ID; one-time passes.';

CREATE TABLE `student_documents` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `doc_type` VARCHAR(60) NOT NULL,
  `file_id` CHAR(26) NOT NULL,
  `verified_by` CHAR(26) NULL,
  `verified_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_student_documents_school_id` (`school_id`),
  KEY `ix_student_documents_student_id` (`student_id`),
  KEY `ix_student_documents_file_id` (`file_id`),
  KEY `ix_student_documents_verified_by` (`verified_by`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Uploaded student documents with verification.';

CREATE TABLE `student_status_history` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `from_status` VARCHAR(20) NULL,
  `to_status` VARCHAR(20) NOT NULL,
  `reason` VARCHAR(255) NULL,
  `changed_by` CHAR(26) NULL,
  `changed_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_student_status_history_school_id` (`school_id`),
  KEY `ix_student_status_history_student_id` (`student_id`),
  KEY `ix_student_status_history_changed_by` (`changed_by`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Every status change (suspended, transferred…) with reason.';

CREATE TABLE `student_transfers` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `group_id` CHAR(26) NULL,
  `student_id` CHAR(26) NOT NULL COMMENT 'the row in the school they left',
  `to_school_id` CHAR(26) NOT NULL,
  `to_student_id` CHAR(26) NULL COMMENT 'the row created in the school they joined',
  `to_class_id` CHAR(26) NULL,
  `reason` VARCHAR(255) NULL,
  `dues_at_transfer` DECIMAL(14,2) NOT NULL DEFAULT 0 COMMENT 'carried, not hidden: the receiving school must know',
  `status` VARCHAR(40) NOT NULL DEFAULT 'completed',
  `transferred_by` CHAR(26) NULL,
  `transferred_at` DATETIME NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_student_transfers_school_id` (`school_id`),
  KEY `ix_student_transfers_group_id` (`group_id`),
  KEY `ix_student_transfers_student_id` (`student_id`),
  KEY `ix_student_transfers_to_school_id` (`to_school_id`),
  KEY `ix_student_transfers_to_student_id` (`to_student_id`),
  KEY `ix_student_transfers_to_class_id` (`to_class_id`),
  KEY `ix_student_transfers_transferred_by` (`transferred_by`),
  KEY `ix_student_transfers_to_school_id_transferred_at` (`to_school_id`, `transferred_at`),
  CHECK (`status` IN ('completed', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='A child moving between two schools of one group: the row they left, the row they arrived in, and what was outstanding on the day. Tenant is the school they left.';


-- ============ Curriculum & timetable ============
CREATE TABLE `section_subject_teachers` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `section_id` CHAR(26) NOT NULL,
  `class_subject_id` CHAR(26) NOT NULL,
  `teacher_id` CHAR(26) NOT NULL,
  `is_primary` TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `ix_section_subject_teachers_school_id` (`school_id`),
  KEY `ix_section_subject_teachers_section_id` (`section_id`),
  KEY `ix_section_subject_teachers_class_subject_id` (`class_subject_id`),
  KEY `ix_section_subject_teachers_teacher_id` (`teacher_id`),
  UNIQUE KEY `uq_section_subject_teachers_section_id_class_subject_id_teacher_` (`section_id`, `class_subject_id`, `teacher_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Who teaches which subject in which section this year.';

CREATE TABLE `timetable_versions` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `academic_year_id` CHAR(26) NOT NULL,
  `name` VARCHAR(80) NOT NULL,
  `effective_from` DATE NOT NULL,
  `effective_to` DATE NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'draft',
  `generated_by` VARCHAR(40) NOT NULL DEFAULT 'manual',
  `constraints` JSON NULL,
  `score` DECIMAL(6,2) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_timetable_versions_school_id` (`school_id`),
  KEY `ix_timetable_versions_academic_year_id` (`academic_year_id`),
  CHECK (`status` IN ('draft', 'published', 'archived')),
  CHECK (`generated_by` IN ('manual', 'auto'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Published versions of the timetable; auto-generator writes drafts.';

CREATE TABLE `timetable_slots` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `version_id` CHAR(26) NOT NULL,
  `section_id` CHAR(26) NOT NULL,
  `day_of_week` SMALLINT NOT NULL,
  `period_id` CHAR(26) NOT NULL,
  `class_subject_id` CHAR(26) NULL,
  `teacher_id` CHAR(26) NULL,
  `room_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_timetable_slots_school_id` (`school_id`),
  KEY `ix_timetable_slots_version_id` (`version_id`),
  KEY `ix_timetable_slots_section_id` (`section_id`),
  KEY `ix_timetable_slots_period_id` (`period_id`),
  KEY `ix_timetable_slots_class_subject_id` (`class_subject_id`),
  KEY `ix_timetable_slots_teacher_id` (`teacher_id`),
  KEY `ix_timetable_slots_room_id` (`room_id`),
  UNIQUE KEY `uq_timetable_slots_version_id_section_id_day_of_week_period_id` (`version_id`, `section_id`, `day_of_week`, `period_id`),
  UNIQUE KEY `uq_timetable_slots_version_id_teacher_id_day_of_week_period_id` (`version_id`, `teacher_id`, `day_of_week`, `period_id`),
  UNIQUE KEY `uq_timetable_slots_version_id_room_id_day_of_week_period_id` (`version_id`, `room_id`, `day_of_week`, `period_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Section × day × period → subject, teacher, room. App enforces no teacher/room double booking.';

CREATE TABLE `timetable_substitutions` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `slot_id` CHAR(26) NOT NULL,
  `on_date` DATE NOT NULL,
  `original_teacher_id` CHAR(26) NULL,
  `substitute_teacher_id` CHAR(26) NULL,
  `reason` VARCHAR(60) NULL,
  `leave_application_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'suggested',
  `is_auto_suggested` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_timetable_substitutions_school_id` (`school_id`),
  KEY `ix_timetable_substitutions_slot_id` (`slot_id`),
  KEY `ix_timetable_substitutions_original_teacher_id` (`original_teacher_id`),
  KEY `ix_timetable_substitutions_substitute_teacher_id` (`substitute_teacher_id`),
  UNIQUE KEY `uq_timetable_substitutions_slot_id_on_date` (`slot_id`, `on_date`),
  CHECK (`status` IN ('suggested', 'pending', 'approved', 'rejected', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Day-specific override when a teacher is absent; auto-suggested from free, qualified teachers.';

CREATE TABLE `syllabi` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `class_subject_id` CHAR(26) NOT NULL,
  `term_id` CHAR(26) NULL,
  `title` VARCHAR(200) NOT NULL,
  `file_id` CHAR(26) NULL,
  `created_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_syllabi_school_id` (`school_id`),
  KEY `ix_syllabi_class_subject_id` (`class_subject_id`),
  KEY `ix_syllabi_term_id` (`term_id`),
  KEY `ix_syllabi_file_id` (`file_id`),
  KEY `ix_syllabi_created_by` (`created_by`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Syllabus per class-subject and term.';

CREATE TABLE `syllabus_units` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `syllabus_id` CHAR(26) NOT NULL,
  `title` VARCHAR(200) NOT NULL,
  `sequence` SMALLINT NOT NULL,
  `planned_periods` SMALLINT NOT NULL DEFAULT 1,
  `planned_end_date` DATE NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_syllabus_units_school_id` (`school_id`),
  KEY `ix_syllabus_units_syllabus_id` (`syllabus_id`),
  UNIQUE KEY `uq_syllabus_units_syllabus_id_sequence` (`syllabus_id`, `sequence`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Chapters/units with planned end dates (behind-schedule alerts).';

CREATE TABLE `learning_outcomes` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `class_subject_id` CHAR(26) NOT NULL,
  `unit_id` CHAR(26) NULL,
  `code` VARCHAR(30) NOT NULL,
  `statement` TEXT NOT NULL,
  `statement_bn` TEXT NULL,
  `bloom_level` VARCHAR(40) NULL,
  `weight` DECIMAL(4,2) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_learning_outcomes_school_id` (`school_id`),
  KEY `ix_learning_outcomes_class_subject_id` (`class_subject_id`),
  KEY `ix_learning_outcomes_unit_id` (`unit_id`),
  UNIQUE KEY `uq_learning_outcomes_class_subject_id_code` (`class_subject_id`, `code`),
  CHECK (`bloom_level` IN ('remember', 'understand', 'apply', 'analyse', 'evaluate', 'create'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Competencies / performance indicators (NCTB 2023 curriculum) mapped to units and Bloom level.';

CREATE TABLE `lesson_plans` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `teacher_id` CHAR(26) NOT NULL,
  `section_id` CHAR(26) NOT NULL,
  `class_subject_id` CHAR(26) NOT NULL,
  `unit_id` CHAR(26) NULL,
  `plan_date` DATE NOT NULL,
  `topic` VARCHAR(200) NOT NULL,
  `objectives` TEXT NULL,
  `activities` TEXT NULL,
  `outcomes` JSON NULL,
  `resources` JSON NULL,
  `homework` TEXT NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'planned',
  `taught_at` DATETIME NULL,
  `reviewed_by` CHAR(26) NULL,
  `review_note` TEXT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_lesson_plans_school_id` (`school_id`),
  KEY `ix_lesson_plans_teacher_id` (`teacher_id`),
  KEY `ix_lesson_plans_section_id` (`section_id`),
  KEY `ix_lesson_plans_class_subject_id` (`class_subject_id`),
  KEY `ix_lesson_plans_unit_id` (`unit_id`),
  KEY `ix_lesson_plans_reviewed_by` (`reviewed_by`),
  KEY `ix_lesson_plans_teacher_id_plan_date` (`teacher_id`, `plan_date`),
  CHECK (`status` IN ('planned', 'taught', 'skipped'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Teacher lesson plans by date with outcomes, resources, homework and review.';

CREATE TABLE `syllabus_progress` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `syllabus_id` CHAR(26) NOT NULL,
  `section_id` CHAR(26) NOT NULL,
  `total_units` SMALLINT NOT NULL DEFAULT 0,
  `taught_units` SMALLINT NOT NULL DEFAULT 0,
  `pct` DECIMAL(5,2) NOT NULL DEFAULT 0,
  `refreshed_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_syllabus_progress_school_id` (`school_id`),
  KEY `ix_syllabus_progress_syllabus_id` (`syllabus_id`),
  KEY `ix_syllabus_progress_section_id` (`section_id`),
  UNIQUE KEY `uq_syllabus_progress_syllabus_id_section_id` (`syllabus_id`, `section_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Rollup: units taught per section (refreshed by scheduler).';


-- ============ Admissions & enquiry CRM ============
CREATE TABLE `admission_campaigns` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `academic_year_id` CHAR(26) NOT NULL,
  `name` VARCHAR(120) NOT NULL,
  `opens_at` DATETIME NOT NULL,
  `closes_at` DATETIME NOT NULL,
  `form_fee` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `admission_fee_head_id` CHAR(26) NULL,
  `selection_mode` VARCHAR(40) NOT NULL DEFAULT 'test',
  `requires_test` TINYINT(1) NOT NULL DEFAULT 1,
  `auto_merit_list` TINYINT(1) NOT NULL DEFAULT 1,
  `auto_offer` TINYINT(1) NOT NULL DEFAULT 1,
  `offer_validity_days` SMALLINT NOT NULL DEFAULT 7,
  `sibling_priority` TINYINT(1) NOT NULL DEFAULT 1,
  `status` VARCHAR(40) NOT NULL DEFAULT 'draft',
  `public_form_slug` VARCHAR(80) NULL,
  `form_schema` JSON NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_admission_campaigns_school_id` (`school_id`),
  KEY `ix_admission_campaigns_academic_year_id` (`academic_year_id`),
  UNIQUE KEY `uq_admission_campaigns_public_form_slug` (`public_form_slug`),
  CHECK (`selection_mode` IN ('test', 'lottery', 'first_come', 'interview', 'mixed')),
  CHECK (`status` IN ('draft', 'open', 'closed', 'archived'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='A season with seats per class, fees, test settings and selection mode.';

CREATE TABLE `admission_campaign_classes` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `campaign_id` CHAR(26) NOT NULL,
  `class_id` CHAR(26) NOT NULL,
  `seats` SMALLINT NOT NULL,
  `min_age_years` DECIMAL(4,1) NULL,
  `max_age_years` DECIMAL(4,1) NULL,
  `test_id` CHAR(26) NULL,
  PRIMARY KEY (`id`),
  KEY `ix_admission_campaign_classes_school_id` (`school_id`),
  KEY `ix_admission_campaign_classes_campaign_id` (`campaign_id`),
  KEY `ix_admission_campaign_classes_class_id` (`class_id`),
  UNIQUE KEY `uq_admission_campaign_classes_campaign_id_class_id` (`campaign_id`, `class_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Seats and age limits per class.';

CREATE TABLE `admission_enquiries` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `campaign_id` CHAR(26) NULL,
  `student_name` VARCHAR(160) NOT NULL,
  `guardian_name` VARCHAR(160) NOT NULL,
  `phone` VARCHAR(20) NOT NULL,
  `email` VARCHAR(160) NULL,
  `class_id` CHAR(26) NULL,
  `source` VARCHAR(40) NOT NULL DEFAULT 'other',
  `assigned_to` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'new',
  `lost_reason` VARCHAR(120) NULL,
  `next_follow_up_at` DATETIME NULL,
  `notes` TEXT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_admission_enquiries_school_id` (`school_id`),
  KEY `ix_admission_enquiries_campaign_id` (`campaign_id`),
  KEY `ix_admission_enquiries_class_id` (`class_id`),
  KEY `ix_admission_enquiries_assigned_to` (`assigned_to`),
  KEY `ix_admission_enquiries_next_follow_up_at` (`next_follow_up_at`),
  CHECK (`source` IN ('walk_in', 'website', 'facebook', 'referral', 'call', 'whatsapp', 'event', 'other')),
  CHECK (`status` IN ('new', 'contacted', 'visited', 'converted', 'lost'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Lead with source, counsellor (round-robin) and follow-up date.';

CREATE TABLE `enquiry_followups` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `enquiry_id` CHAR(26) NOT NULL,
  `note` TEXT NOT NULL,
  `channel` VARCHAR(40) NULL,
  `by_user_id` CHAR(26) NULL,
  `next_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_enquiry_followups_school_id` (`school_id`),
  KEY `ix_enquiry_followups_enquiry_id` (`enquiry_id`),
  KEY `ix_enquiry_followups_by_user_id` (`by_user_id`),
  CHECK (`channel` IN ('call', 'visit', 'sms', 'email', 'whatsapp'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Interaction log.';

CREATE TABLE `admission_applications` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `campaign_id` CHAR(26) NOT NULL,
  `enquiry_id` CHAR(26) NULL,
  `application_no` VARCHAR(30) NOT NULL,
  `class_id` CHAR(26) NOT NULL,
  `shift_id` CHAR(26) NULL,
  `first_name` VARCHAR(80) NOT NULL,
  `last_name` VARCHAR(80) NULL,
  `gender` VARCHAR(40) NOT NULL,
  `date_of_birth` DATE NOT NULL,
  `photo_file_id` CHAR(26) NULL,
  `guardian_name` VARCHAR(160) NOT NULL,
  `guardian_phone` VARCHAR(20) NOT NULL,
  `guardian_email` VARCHAR(160) NULL,
  `guardian_relation` VARCHAR(30) NULL,
  `address` JSON NULL,
  `previous_school` JSON NULL,
  `extra_fields` JSON NULL,
  `sibling_student_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'draft',
  `form_fee_invoice_id` CHAR(26) NULL,
  `test_score` DECIMAL(6,2) NULL,
  `merit_rank` INT NULL,
  `lottery_no` VARCHAR(20) NULL,
  `waitlist_position` INT NULL,
  `student_id` CHAR(26) NULL,
  `submitted_at` DATETIME NULL,
  `decided_at` DATETIME NULL,
  `decided_by` CHAR(26) NULL,
  `rejection_reason` VARCHAR(255) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_admission_applications_school_id` (`school_id`),
  KEY `ix_admission_applications_campaign_id` (`campaign_id`),
  KEY `ix_admission_applications_enquiry_id` (`enquiry_id`),
  KEY `ix_admission_applications_class_id` (`class_id`),
  KEY `ix_admission_applications_shift_id` (`shift_id`),
  KEY `ix_admission_applications_photo_file_id` (`photo_file_id`),
  KEY `ix_admission_applications_sibling_student_id` (`sibling_student_id`),
  KEY `ix_admission_applications_student_id` (`student_id`),
  KEY `ix_admission_applications_decided_by` (`decided_by`),
  UNIQUE KEY `uq_admission_applications_school_id_application_no` (`school_id`, `application_no`),
  KEY `ix_admission_applications_campaign_id_class_id_status` (`campaign_id`, `class_id`, `status`),
  CHECK (`gender` IN ('male', 'female', 'other')),
  CHECK (`status` IN ('draft', 'submitted', 'screening', 'test_scheduled', 'tested', 'shortlisted', 'waitlisted', 'offered', 'accepted', 'enrolled', 'rejected', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Application with applicant snapshot, pipeline status, score, rank, waitlist.';

CREATE TABLE `application_documents` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `application_id` CHAR(26) NOT NULL,
  `doc_type` VARCHAR(60) NOT NULL,
  `file_id` CHAR(26) NOT NULL,
  `verified_at` DATETIME NULL,
  `verified_by` CHAR(26) NULL,
  PRIMARY KEY (`id`),
  KEY `ix_application_documents_school_id` (`school_id`),
  KEY `ix_application_documents_application_id` (`application_id`),
  KEY `ix_application_documents_file_id` (`file_id`),
  KEY `ix_application_documents_verified_by` (`verified_by`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Uploaded applicant documents.';

CREATE TABLE `admission_tests` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `campaign_id` CHAR(26) NOT NULL,
  `class_id` CHAR(26) NOT NULL,
  `name` VARCHAR(120) NOT NULL,
  `held_at` DATETIME NOT NULL,
  `duration_min` SMALLINT NULL,
  `venue` VARCHAR(120) NULL,
  `total_marks` DECIMAL(6,2) NOT NULL DEFAULT 100,
  `pass_marks` DECIMAL(6,2) NULL,
  `components` JSON NULL,
  `online_exam_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_admission_tests_school_id` (`school_id`),
  KEY `ix_admission_tests_campaign_id` (`campaign_id`),
  KEY `ix_admission_tests_class_id` (`class_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Entrance test/interview with components.';

CREATE TABLE `admission_test_results` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `test_id` CHAR(26) NOT NULL,
  `application_id` CHAR(26) NOT NULL,
  `component_marks` JSON NULL,
  `total_marks` DECIMAL(6,2) NULL,
  `is_absent` TINYINT(1) NOT NULL DEFAULT 0,
  `remarks` VARCHAR(255) NULL,
  `entered_by` CHAR(26) NULL,
  `entered_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_admission_test_results_school_id` (`school_id`),
  KEY `ix_admission_test_results_test_id` (`test_id`),
  KEY `ix_admission_test_results_application_id` (`application_id`),
  KEY `ix_admission_test_results_entered_by` (`entered_by`),
  UNIQUE KEY `uq_admission_test_results_test_id_application_id` (`test_id`, `application_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Score per applicant.';

CREATE TABLE `admission_interviews` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `test_id` CHAR(26) NOT NULL,
  `application_id` CHAR(26) NULL,
  `starts_at` DATETIME NOT NULL,
  `ends_at` DATETIME NOT NULL,
  `venue` VARCHAR(120) NULL,
  `panel` JSON NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'open',
  `notes` VARCHAR(255) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_admission_interviews_school_id` (`school_id`),
  KEY `ix_admission_interviews_test_id` (`test_id`),
  KEY `ix_admission_interviews_application_id` (`application_id`),
  UNIQUE KEY `uq_admission_interviews_application_id` (`application_id`),
  KEY `ix_admission_interviews_test_id_starts_at` (`test_id`, `starts_at`),
  CHECK (`status` IN ('open', 'booked', 'attended', 'no_show', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Interview slots per applicant: when, where, who sits on the panel, and how it went.';

CREATE TABLE `admission_offers` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `application_id` CHAR(26) NOT NULL,
  `offered_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `expires_at` DATETIME NOT NULL,
  `admission_fee_invoice_id` CHAR(26) NULL,
  `offer_letter_file_id` CHAR(26) NULL,
  `accepted_at` DATETIME NULL,
  `declined_at` DATETIME NULL,
  `revoked_at` DATETIME NULL,
  `revoke_reason` VARCHAR(120) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_admission_offers_school_id` (`school_id`),
  UNIQUE KEY `uq_admission_offers_application_id` (`application_id`),
  KEY `ix_admission_offers_offer_letter_file_id` (`offer_letter_file_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Offer with expiry; auto-revoked and waitlist promoted when unpaid.';


-- ============ Attendance & leave ============
CREATE TABLE `attendance_devices` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `campus_id` CHAR(26) NULL,
  `name` VARCHAR(80) NOT NULL,
  `device_type` VARCHAR(40) NOT NULL,
  `vendor` VARCHAR(60) NULL,
  `serial_no` VARCHAR(80) NULL,
  `api_key_hash` VARCHAR(128) NULL,
  `location` VARCHAR(120) NULL,
  `direction` VARCHAR(40) NOT NULL DEFAULT 'both',
  `last_seen_at` DATETIME NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_attendance_devices_school_id` (`school_id`),
  KEY `ix_attendance_devices_campus_id` (`campus_id`),
  UNIQUE KEY `uq_attendance_devices_serial_no` (`serial_no`),
  CHECK (`device_type` IN ('biometric', 'rfid', 'face', 'qr', 'gps_bus', 'mobile_app')),
  CHECK (`direction` IN ('in', 'out', 'both'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Biometric / RFID / face / QR / bus readers.';

CREATE TABLE `device_punch_logs` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `device_id` CHAR(26) NOT NULL,
  `identifier` VARCHAR(80) NOT NULL,
  `punched_at` DATETIME NOT NULL,
  `direction` VARCHAR(10) NULL,
  `raw_payload` JSON NULL,
  `person_type` VARCHAR(40) NULL,
  `person_id` CHAR(26) NULL,
  `processed_at` DATETIME NULL,
  `error` VARCHAR(255) NULL,
  PRIMARY KEY (`id`),
  KEY `ix_device_punch_logs_school_id` (`school_id`),
  KEY `ix_device_punch_logs_device_id` (`device_id`),
  KEY `ix_device_punch_logs_person_id` (`person_id`),
  KEY `ix_device_punch_logs_processed_at` (`processed_at`),
  CHECK (`person_type` IN ('student', 'staff'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Punches exactly as received; resolved to a person later.';

CREATE TABLE `student_attendance` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `section_id` CHAR(26) NULL,
  `on_date` DATE NOT NULL,
  `status` VARCHAR(40) NOT NULL,
  `check_in` DATETIME NULL,
  `check_out` DATETIME NULL,
  `late_minutes` SMALLINT NULL,
  `source` VARCHAR(40) NOT NULL DEFAULT 'manual',
  `marked_by` CHAR(26) NULL,
  `remarks` VARCHAR(255) NULL,
  `guardian_notified_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_student_attendance_school_id` (`school_id`),
  KEY `ix_student_attendance_student_id` (`student_id`),
  KEY `ix_student_attendance_section_id` (`section_id`),
  KEY `ix_student_attendance_marked_by` (`marked_by`),
  UNIQUE KEY `uq_student_attendance_student_id_on_date` (`student_id`, `on_date`),
  KEY `ix_student_attendance_section_id_on_date` (`section_id`, `on_date`),
  CHECK (`status` IN ('present', 'absent', 'late', 'half_day', 'excused', 'holiday')),
  CHECK (`source` IN ('manual', 'device', 'app', 'import', 'system', 'bus'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='One row per student per day.';

CREATE TABLE `student_period_attendance` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `slot_id` CHAR(26) NOT NULL,
  `on_date` DATE NOT NULL,
  `status` VARCHAR(40) NOT NULL,
  `marked_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_student_period_attendance_school_id` (`school_id`),
  KEY `ix_student_period_attendance_student_id` (`student_id`),
  KEY `ix_student_period_attendance_slot_id` (`slot_id`),
  KEY `ix_student_period_attendance_marked_by` (`marked_by`),
  UNIQUE KEY `uq_student_period_attendance_student_id_slot_id_on_date` (`student_id`, `slot_id`, `on_date`),
  CHECK (`status` IN ('present', 'absent', 'late', 'excused'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Period-wise attendance (college / subject-wise).';

CREATE TABLE `staff_attendance` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `staff_id` CHAR(26) NOT NULL,
  `on_date` DATE NOT NULL,
  `status` VARCHAR(40) NOT NULL,
  `check_in` DATETIME NULL,
  `check_out` DATETIME NULL,
  `late_minutes` SMALLINT NULL,
  `early_leave_minutes` SMALLINT NULL,
  `work_minutes` SMALLINT NULL,
  `overtime_minutes` SMALLINT NULL,
  `source` VARCHAR(40) NOT NULL DEFAULT 'manual',
  `marked_by` CHAR(26) NULL,
  `remarks` VARCHAR(255) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_staff_attendance_school_id` (`school_id`),
  KEY `ix_staff_attendance_staff_id` (`staff_id`),
  KEY `ix_staff_attendance_marked_by` (`marked_by`),
  UNIQUE KEY `uq_staff_attendance_staff_id_on_date` (`staff_id`, `on_date`),
  CHECK (`status` IN ('present', 'absent', 'late', 'half_day', 'excused', 'holiday', 'wfh')),
  CHECK (`source` IN ('manual', 'device', 'app', 'import', 'system'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Staff daily attendance with work/overtime minutes feeding payroll.';

CREATE TABLE `attendance_policies` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `audience` VARCHAR(40) NOT NULL,
  `class_id` CHAR(26) NULL,
  `shift_id` CHAR(26) NULL,
  `late_after_minutes` SMALLINT NOT NULL DEFAULT 15,
  `half_day_after_minutes` SMALLINT NOT NULL DEFAULT 120,
  `auto_absent_at` TIME NULL,
  `notify_on_arrival` TINYINT(1) NOT NULL DEFAULT 1,
  `notify_on_absent` TINYINT(1) NOT NULL DEFAULT 1,
  `notify_on_late` TINYINT(1) NOT NULL DEFAULT 1,
  `consecutive_absent_alert` SMALLINT NOT NULL DEFAULT 3,
  `min_attendance_pct` DECIMAL(5,2) NOT NULL DEFAULT 75,
  `block_exam_below_min` TINYINT(1) NOT NULL DEFAULT 0,
  `late_count_to_lop` SMALLINT NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_attendance_policies_school_id` (`school_id`),
  KEY `ix_attendance_policies_class_id` (`class_id`),
  KEY `ix_attendance_policies_shift_id` (`shift_id`),
  CHECK (`audience` IN ('student', 'staff'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Cut-off time, late/half-day thresholds, notification switches, escalation, minimum %.';

CREATE TABLE `leave_types` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(60) NOT NULL,
  `code` VARCHAR(20) NOT NULL,
  `audience` VARCHAR(40) NOT NULL,
  `days_per_year` DECIMAL(5,1) NOT NULL DEFAULT 0,
  `accrual` VARCHAR(40) NOT NULL DEFAULT 'yearly',
  `is_paid` TINYINT(1) NOT NULL DEFAULT 1,
  `carry_forward_max` DECIMAL(5,1) NOT NULL DEFAULT 0,
  `requires_document` TINYINT(1) NOT NULL DEFAULT 0,
  `min_notice_days` SMALLINT NOT NULL DEFAULT 0,
  `encashable` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_leave_types_school_id` (`school_id`),
  UNIQUE KEY `uq_leave_types_school_id_code` (`school_id`, `code`),
  CHECK (`audience` IN ('student', 'staff')),
  CHECK (`accrual` IN ('yearly', 'monthly', 'none'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Casual, sick, earned, maternity, study… with accrual and carry-forward.';

CREATE TABLE `leave_balances` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `staff_id` CHAR(26) NOT NULL,
  `leave_type_id` CHAR(26) NOT NULL,
  `academic_year_id` CHAR(26) NOT NULL,
  `allocated` DECIMAL(5,1) NOT NULL DEFAULT 0,
  `carried_forward` DECIMAL(5,1) NOT NULL DEFAULT 0,
  `used` DECIMAL(5,1) NOT NULL DEFAULT 0,
  `encashed` DECIMAL(5,1) NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_leave_balances_school_id` (`school_id`),
  KEY `ix_leave_balances_staff_id` (`staff_id`),
  KEY `ix_leave_balances_leave_type_id` (`leave_type_id`),
  KEY `ix_leave_balances_academic_year_id` (`academic_year_id`),
  UNIQUE KEY `uq_leave_balances_staff_id_leave_type_id_academic_year_id` (`staff_id`, `leave_type_id`, `academic_year_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Per staff per type per year.';

CREATE TABLE `leave_applications` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `applicant_type` VARCHAR(40) NOT NULL,
  `student_id` CHAR(26) NULL,
  `staff_id` CHAR(26) NULL,
  `leave_type_id` CHAR(26) NOT NULL,
  `from_date` DATE NOT NULL,
  `to_date` DATE NOT NULL,
  `half_day` VARCHAR(40) NULL,
  `days` DECIMAL(5,1) NOT NULL,
  `reason` TEXT NOT NULL,
  `document_file_id` CHAR(26) NULL,
  `applied_by` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'pending',
  `approval_request_id` CHAR(26) NULL,
  `decided_by` CHAR(26) NULL,
  `decided_at` DATETIME NULL,
  `decision_note` VARCHAR(255) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_leave_applications_school_id` (`school_id`),
  KEY `ix_leave_applications_student_id` (`student_id`),
  KEY `ix_leave_applications_staff_id` (`staff_id`),
  KEY `ix_leave_applications_leave_type_id` (`leave_type_id`),
  KEY `ix_leave_applications_document_file_id` (`document_file_id`),
  KEY `ix_leave_applications_applied_by` (`applied_by`),
  KEY `ix_leave_applications_decided_by` (`decided_by`),
  KEY `ix_leave_applications_school_id_status` (`school_id`, `status`),
  CHECK (`applicant_type` IN ('student', 'staff')),
  CHECK (`half_day` IN ('first', 'second')),
  CHECK (`status` IN ('pending', 'approved', 'rejected', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Student or staff leave through the approval workflow.';

CREATE TABLE `attendance_monthly_summary` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `month` DATE NOT NULL,
  `present_days` SMALLINT NOT NULL DEFAULT 0,
  `absent_days` SMALLINT NOT NULL DEFAULT 0,
  `late_days` SMALLINT NOT NULL DEFAULT 0,
  `excused_days` SMALLINT NOT NULL DEFAULT 0,
  `working_days` SMALLINT NOT NULL DEFAULT 0,
  `pct` DECIMAL(5,2) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `ix_attendance_monthly_summary_school_id` (`school_id`),
  KEY `ix_attendance_monthly_summary_student_id` (`student_id`),
  UNIQUE KEY `uq_attendance_monthly_summary_student_id_month` (`student_id`, `month`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Rollup per student per month (refreshed nightly); used by report cards, eligibility, alerts.';


-- ============ Examinations & assessment ============
CREATE TABLE `grading_scales` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(80) NOT NULL,
  `is_default` TINYINT(1) NOT NULL DEFAULT 0,
  `gpa_max` DECIMAL(4,2) NOT NULL DEFAULT 5,
  `fail_gpa_zero` TINYINT(1) NOT NULL DEFAULT 1 COMMENT 'F in any subject → GPA 0 (board rule)',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_grading_scales_school_id` (`school_id`),
  UNIQUE KEY `uq_grading_scales_school_id_name` (`school_id`, `name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Named scales (BD Board GPA 5.0, Cambridge A*–G, IB 1–7).';

CREATE TABLE `grading_bands` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `scale_id` CHAR(26) NOT NULL,
  `grade` VARCHAR(5) NOT NULL,
  `min_percent` DECIMAL(5,2) NOT NULL,
  `max_percent` DECIMAL(5,2) NOT NULL,
  `grade_point` DECIMAL(4,2) NOT NULL,
  `is_fail` TINYINT(1) NOT NULL DEFAULT 0,
  `remarks` VARCHAR(120) NULL,
  PRIMARY KEY (`id`),
  KEY `ix_grading_bands_school_id` (`school_id`),
  KEY `ix_grading_bands_scale_id` (`scale_id`),
  UNIQUE KEY `uq_grading_bands_scale_id_grade` (`scale_id`, `grade`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Grade bands with ranges and points.';

CREATE TABLE `competency_scales` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(80) NOT NULL,
  `levels` JSON NULL COMMENT '[{code:''△'',label:''Needs work'',value:1},…]',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_competency_scales_school_id` (`school_id`),
  UNIQUE KEY `uq_competency_scales_school_id_name` (`school_id`, `name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Rating scales for competency-based assessment (e.g. NCTB triangle/circle/square, 1–4 rubric).';

CREATE TABLE `exam_types` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(60) NOT NULL,
  `weight_pct` DECIMAL(5,2) NOT NULL DEFAULT 100,
  `is_internal` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_exam_types_school_id` (`school_id`),
  UNIQUE KEY `uq_exam_types_school_id_name` (`school_id`, `name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Class test, half-yearly, annual, model test… with weight in the annual aggregate.';

CREATE TABLE `exams` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `academic_year_id` CHAR(26) NOT NULL,
  `term_id` CHAR(26) NULL,
  `exam_type_id` CHAR(26) NOT NULL,
  `grading_scale_id` CHAR(26) NOT NULL,
  `name` VARCHAR(120) NOT NULL,
  `start_date` DATE NOT NULL,
  `end_date` DATE NOT NULL,
  `marks_entry_deadline` DATETIME NULL,
  `publish_at` DATETIME NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'draft',
  `require_fee_clearance` TINYINT(1) NOT NULL DEFAULT 0,
  `min_attendance_pct` DECIMAL(5,2) NULL,
  `rank_scope` VARCHAR(40) NOT NULL DEFAULT 'section',
  `tie_rule` VARCHAR(40) NOT NULL DEFAULT 'share_rank',
  `created_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_exams_school_id` (`school_id`),
  KEY `ix_exams_academic_year_id` (`academic_year_id`),
  KEY `ix_exams_term_id` (`term_id`),
  KEY `ix_exams_exam_type_id` (`exam_type_id`),
  KEY `ix_exams_grading_scale_id` (`grading_scale_id`),
  KEY `ix_exams_created_by` (`created_by`),
  CHECK (`status` IN ('draft', 'scheduled', 'ongoing', 'marks_entry', 'processing', 'published', 'locked')),
  CHECK (`rank_scope` IN ('section', 'class', 'both')),
  CHECK (`tie_rule` IN ('share_rank', 'dense', 'by_total'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='An exam event for a year/term with scale, eligibility rules and publish time.';

CREATE TABLE `exam_schedules` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `exam_id` CHAR(26) NOT NULL,
  `class_subject_id` CHAR(26) NOT NULL,
  `exam_date` DATE NULL,
  `start_time` TIME NULL,
  `end_time` TIME NULL,
  `room_id` CHAR(26) NULL,
  `full_marks` DECIMAL(6,2) NOT NULL,
  `pass_marks` DECIMAL(6,2) NOT NULL,
  `theory_marks` DECIMAL(6,2) NULL,
  `practical_marks` DECIMAL(6,2) NULL,
  `ca_marks` DECIMAL(6,2) NULL,
  `marks_entry_locked` TINYINT(1) NOT NULL DEFAULT 0,
  `question_paper_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_exam_schedules_school_id` (`school_id`),
  KEY `ix_exam_schedules_exam_id` (`exam_id`),
  KEY `ix_exam_schedules_class_subject_id` (`class_subject_id`),
  KEY `ix_exam_schedules_room_id` (`room_id`),
  UNIQUE KEY `uq_exam_schedules_exam_id_class_subject_id` (`exam_id`, `class_subject_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='One paper per class-subject: date, time, room, marks split.';

CREATE TABLE `exam_invigilators` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `schedule_id` CHAR(26) NOT NULL,
  `room_id` CHAR(26) NOT NULL,
  `staff_id` CHAR(26) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_exam_invigilators_school_id` (`school_id`),
  KEY `ix_exam_invigilators_schedule_id` (`schedule_id`),
  KEY `ix_exam_invigilators_room_id` (`room_id`),
  KEY `ix_exam_invigilators_staff_id` (`staff_id`),
  UNIQUE KEY `uq_exam_invigilators_schedule_id_room_id_staff_id` (`schedule_id`, `room_id`, `staff_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Duty roster.';

CREATE TABLE `exam_seat_plans` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `exam_id` CHAR(26) NOT NULL,
  `student_id` CHAR(26) NOT NULL,
  `room_id` CHAR(26) NULL,
  `seat_no` VARCHAR(10) NOT NULL,
  `admit_card_file_id` CHAR(26) NULL,
  `is_eligible` TINYINT(1) NOT NULL DEFAULT 1,
  `ineligible_reason` VARCHAR(60) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_exam_seat_plans_school_id` (`school_id`),
  KEY `ix_exam_seat_plans_exam_id` (`exam_id`),
  KEY `ix_exam_seat_plans_student_id` (`student_id`),
  KEY `ix_exam_seat_plans_room_id` (`room_id`),
  KEY `ix_exam_seat_plans_admit_card_file_id` (`admit_card_file_id`),
  UNIQUE KEY `uq_exam_seat_plans_exam_id_student_id` (`exam_id`, `student_id`),
  UNIQUE KEY `uq_exam_seat_plans_exam_id_room_id_seat_no` (`exam_id`, `room_id`, `seat_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Seat per student per exam; admit-card file; eligibility flag.';

CREATE TABLE `marks` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `schedule_id` CHAR(26) NOT NULL,
  `student_id` CHAR(26) NOT NULL,
  `theory_obtained` DECIMAL(6,2) NULL,
  `practical_obtained` DECIMAL(6,2) NULL,
  `ca_obtained` DECIMAL(6,2) NULL,
  `total_obtained` DECIMAL(6,2) NULL,
  `is_absent` TINYINT(1) NOT NULL DEFAULT 0,
  `grade` VARCHAR(5) NULL,
  `grade_point` DECIMAL(4,2) NULL,
  `is_pass` TINYINT(1) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'draft',
  `entered_by` CHAR(26) NULL,
  `entered_at` DATETIME NULL,
  `verified_by` CHAR(26) NULL,
  `verified_at` DATETIME NULL,
  `remarks` VARCHAR(120) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_marks_school_id` (`school_id`),
  KEY `ix_marks_schedule_id` (`schedule_id`),
  KEY `ix_marks_student_id` (`student_id`),
  KEY `ix_marks_entered_by` (`entered_by`),
  KEY `ix_marks_verified_by` (`verified_by`),
  UNIQUE KEY `uq_marks_schedule_id_student_id` (`schedule_id`, `student_id`),
  CHECK (`status` IN ('draft', 'submitted', 'verified', 'locked'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Marks per student per paper with computed grade and workflow status.';

CREATE TABLE `competency_assessments` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `outcome_id` CHAR(26) NOT NULL,
  `term_id` CHAR(26) NOT NULL,
  `scale_id` CHAR(26) NOT NULL,
  `level_code` VARCHAR(10) NOT NULL,
  `evidence` JSON NULL COMMENT 'file ids / notes',
  `assessed_by` CHAR(26) NULL,
  `assessed_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_competency_assessments_school_id` (`school_id`),
  KEY `ix_competency_assessments_student_id` (`student_id`),
  KEY `ix_competency_assessments_outcome_id` (`outcome_id`),
  KEY `ix_competency_assessments_term_id` (`term_id`),
  KEY `ix_competency_assessments_scale_id` (`scale_id`),
  KEY `ix_competency_assessments_assessed_by` (`assessed_by`),
  UNIQUE KEY `uq_competency_assessments_student_id_outcome_id_term_id` (`student_id`, `outcome_id`, `term_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Competency-based rating per student per learning outcome per term (no marks).';

CREATE TABLE `exam_results` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `exam_id` CHAR(26) NOT NULL,
  `student_id` CHAR(26) NOT NULL,
  `section_id` CHAR(26) NULL,
  `total_full_marks` DECIMAL(8,2) NOT NULL,
  `total_obtained` DECIMAL(8,2) NOT NULL,
  `percentage` DECIMAL(5,2) NOT NULL,
  `gpa` DECIMAL(4,2) NULL,
  `grade` VARCHAR(5) NULL,
  `failed_subjects` SMALLINT NOT NULL DEFAULT 0,
  `is_pass` TINYINT(1) NOT NULL,
  `rank_in_section` INT NULL,
  `rank_in_class` INT NULL,
  `attendance_pct` DECIMAL(5,2) NULL,
  `teacher_remark` VARCHAR(255) NULL,
  `principal_remark` VARCHAR(255) NULL,
  `report_card_file_id` CHAR(26) NULL,
  `published_at` DATETIME NULL,
  `computed_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_exam_results_school_id` (`school_id`),
  KEY `ix_exam_results_exam_id` (`exam_id`),
  KEY `ix_exam_results_student_id` (`student_id`),
  KEY `ix_exam_results_section_id` (`section_id`),
  KEY `ix_exam_results_report_card_file_id` (`report_card_file_id`),
  UNIQUE KEY `uq_exam_results_exam_id_student_id` (`exam_id`, `student_id`),
  KEY `ix_exam_results_exam_id_section_id_rank_in_section` (`exam_id`, `section_id`, `rank_in_section`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Aggregated result per student per exam, frozen on publish.';

CREATE TABLE `annual_results` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `academic_year_id` CHAR(26) NOT NULL,
  `student_id` CHAR(26) NOT NULL,
  `weighted_gpa` DECIMAL(4,2) NULL,
  `weighted_pct` DECIMAL(5,2) NULL,
  `rank_in_class` INT NULL,
  `decision` VARCHAR(40) NOT NULL DEFAULT 'pending',
  `computed_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_annual_results_school_id` (`school_id`),
  KEY `ix_annual_results_academic_year_id` (`academic_year_id`),
  KEY `ix_annual_results_student_id` (`student_id`),
  UNIQUE KEY `uq_annual_results_academic_year_id_student_id` (`academic_year_id`, `student_id`),
  CHECK (`decision` IN ('promoted', 'retained', 'graduated', 'conditional', 'pending'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Weighted aggregate across the year’s exams → promotion input.';

CREATE TABLE `promotion_rules` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `academic_year_id` CHAR(26) NOT NULL,
  `class_id` CHAR(26) NULL,
  `min_gpa` DECIMAL(4,2) NOT NULL DEFAULT 1,
  `max_failed_subjects` SMALLINT NOT NULL DEFAULT 0,
  `min_attendance_pct` DECIMAL(5,2) NOT NULL DEFAULT 0,
  `auto_apply` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_promotion_rules_school_id` (`school_id`),
  KEY `ix_promotion_rules_academic_year_id` (`academic_year_id`),
  KEY `ix_promotion_rules_class_id` (`class_id`),
  UNIQUE KEY `uq_promotion_rules_academic_year_id_class_id` (`academic_year_id`, `class_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Min GPA, max failed subjects, min attendance; auto-apply switch.';

CREATE TABLE `promotions` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `from_enrollment_id` CHAR(26) NOT NULL,
  `to_enrollment_id` CHAR(26) NULL,
  `decision` VARCHAR(40) NOT NULL,
  `annual_gpa` DECIMAL(4,2) NULL,
  `is_auto` TINYINT(1) NOT NULL DEFAULT 0,
  `decided_by` CHAR(26) NULL,
  `note` VARCHAR(255) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_promotions_school_id` (`school_id`),
  KEY `ix_promotions_student_id` (`student_id`),
  UNIQUE KEY `uq_promotions_from_enrollment_id` (`from_enrollment_id`),
  KEY `ix_promotions_to_enrollment_id` (`to_enrollment_id`),
  KEY `ix_promotions_decided_by` (`decided_by`),
  CHECK (`decision` IN ('promoted', 'retained', 'graduated', 'conditional'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Decision per enrollment.';

CREATE TABLE `questions` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `subject_id` CHAR(26) NOT NULL,
  `class_id` CHAR(26) NULL,
  `unit_id` CHAR(26) NULL,
  `outcome_id` CHAR(26) NULL,
  `q_type` VARCHAR(40) NOT NULL,
  `difficulty` VARCHAR(40) NOT NULL DEFAULT 'medium',
  `body` LONGTEXT NOT NULL,
  `body_bn` LONGTEXT NULL,
  `options` JSON NULL,
  `answer` JSON NULL,
  `marks` DECIMAL(5,2) NOT NULL DEFAULT 1,
  `tags` JSON NULL,
  `ai_generated` TINYINT(1) NOT NULL DEFAULT 0,
  `created_by` CHAR(26) NULL,
  `usage_count` INT NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_questions_school_id` (`school_id`),
  KEY `ix_questions_subject_id` (`subject_id`),
  KEY `ix_questions_class_id` (`class_id`),
  KEY `ix_questions_unit_id` (`unit_id`),
  KEY `ix_questions_outcome_id` (`outcome_id`),
  KEY `ix_questions_created_by` (`created_by`),
  KEY `ix_questions_school_id_subject_id_class_id` (`school_id`, `subject_id`, `class_id`),
  CHECK (`q_type` IN ('mcq', 'true_false', 'short', 'long', 'fill_blank', 'match', 'numeric', 'essay')),
  CHECK (`difficulty` IN ('easy', 'medium', 'hard'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Question bank with type, difficulty, outcome mapping and auto-grade answer key.';

CREATE TABLE `question_papers` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `class_subject_id` CHAR(26) NOT NULL,
  `exam_id` CHAR(26) NULL,
  `title` VARCHAR(200) NOT NULL,
  `blueprint` JSON NULL,
  `total_marks` DECIMAL(6,2) NOT NULL,
  `duration_min` SMALLINT NULL,
  `instructions` TEXT NULL,
  `set_label` VARCHAR(5) NULL COMMENT 'A/B sets',
  `pdf_file_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'draft',
  `created_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_question_papers_school_id` (`school_id`),
  KEY `ix_question_papers_class_subject_id` (`class_subject_id`),
  KEY `ix_question_papers_exam_id` (`exam_id`),
  KEY `ix_question_papers_pdf_file_id` (`pdf_file_id`),
  KEY `ix_question_papers_created_by` (`created_by`),
  CHECK (`status` IN ('draft', 'final'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Generated/curated question papers (blueprint: marks by unit × difficulty), PDF output.';

CREATE TABLE `question_paper_items` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `paper_id` CHAR(26) NOT NULL,
  `question_id` CHAR(26) NOT NULL,
  `sequence` SMALLINT NOT NULL,
  `marks` DECIMAL(5,2) NOT NULL,
  `section` VARCHAR(20) NULL,
  PRIMARY KEY (`id`),
  KEY `ix_question_paper_items_school_id` (`school_id`),
  KEY `ix_question_paper_items_paper_id` (`paper_id`),
  KEY `ix_question_paper_items_question_id` (`question_id`),
  UNIQUE KEY `uq_question_paper_items_paper_id_question_id` (`paper_id`, `question_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Questions in a paper.';

CREATE TABLE `online_exams` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `schedule_id` CHAR(26) NULL,
  `section_id` CHAR(26) NOT NULL,
  `class_subject_id` CHAR(26) NOT NULL,
  `paper_id` CHAR(26) NULL,
  `title` VARCHAR(200) NOT NULL,
  `instructions` TEXT NULL,
  `starts_at` DATETIME NOT NULL,
  `ends_at` DATETIME NOT NULL,
  `duration_min` SMALLINT NOT NULL,
  `total_marks` DECIMAL(6,2) NOT NULL,
  `shuffle_questions` TINYINT(1) NOT NULL DEFAULT 1,
  `auto_grade` TINYINT(1) NOT NULL DEFAULT 1,
  `auto_publish` TINYINT(1) NOT NULL DEFAULT 0,
  `proctoring` JSON NULL COMMENT 'webcam snapshots, tab-switch limit',
  `status` VARCHAR(40) NOT NULL DEFAULT 'draft',
  `created_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_online_exams_school_id` (`school_id`),
  KEY `ix_online_exams_schedule_id` (`schedule_id`),
  KEY `ix_online_exams_section_id` (`section_id`),
  KEY `ix_online_exams_class_subject_id` (`class_subject_id`),
  KEY `ix_online_exams_paper_id` (`paper_id`),
  KEY `ix_online_exams_created_by` (`created_by`),
  CHECK (`status` IN ('draft', 'scheduled', 'live', 'closed', 'published'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Timed online exam; MCQ auto-graded; can sync into a formal paper.';

CREATE TABLE `online_exam_attempts` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `online_exam_id` CHAR(26) NOT NULL,
  `student_id` CHAR(26) NOT NULL,
  `started_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `submitted_at` DATETIME NULL,
  `answers` JSON NULL,
  `auto_score` DECIMAL(6,2) NULL,
  `manual_score` DECIMAL(6,2) NULL,
  `final_score` DECIMAL(6,2) NULL,
  `graded_by` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'in_progress',
  `client_meta` JSON NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_online_exam_attempts_school_id` (`school_id`),
  KEY `ix_online_exam_attempts_online_exam_id` (`online_exam_id`),
  KEY `ix_online_exam_attempts_student_id` (`student_id`),
  KEY `ix_online_exam_attempts_graded_by` (`graded_by`),
  UNIQUE KEY `uq_online_exam_attempts_online_exam_id_student_id` (`online_exam_id`, `student_id`),
  CHECK (`status` IN ('in_progress', 'submitted', 'auto_graded', 'graded'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Attempt with answers, auto/manual score, proctoring meta.';

CREATE TABLE `omr_sheets` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `schedule_id` CHAR(26) NULL,
  `online_exam_id` CHAR(26) NULL,
  `student_id` CHAR(26) NULL,
  `file_id` CHAR(26) NOT NULL,
  `detected_roll` VARCHAR(20) NULL,
  `answers` JSON NULL,
  `score` DECIMAL(6,2) NULL,
  `confidence` DECIMAL(5,2) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'uploaded',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_omr_sheets_school_id` (`school_id`),
  KEY `ix_omr_sheets_schedule_id` (`schedule_id`),
  KEY `ix_omr_sheets_online_exam_id` (`online_exam_id`),
  KEY `ix_omr_sheets_student_id` (`student_id`),
  KEY `ix_omr_sheets_file_id` (`file_id`),
  CHECK (`status` IN ('uploaded', 'processed', 'needs_review', 'applied', 'rejected'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Scanned OMR answer sheets processed by the OMR engine.';

CREATE TABLE `board_registrations` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `academic_year_id` CHAR(26) NOT NULL,
  `board` VARCHAR(40) NOT NULL,
  `exam_name` VARCHAR(40) NOT NULL COMMENT 'SSC 2027',
  `registration_no` VARCHAR(30) NULL,
  `roll_no` VARCHAR(30) NULL,
  `centre` VARCHAR(120) NULL,
  `group_name` VARCHAR(30) NULL,
  `subjects` JSON NULL,
  `fee_invoice_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'draft',
  `board_result` JSON NULL COMMENT 'imported GPA/grades',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_board_registrations_school_id` (`school_id`),
  KEY `ix_board_registrations_student_id` (`student_id`),
  KEY `ix_board_registrations_academic_year_id` (`academic_year_id`),
  UNIQUE KEY `uq_board_registrations_student_id_exam_name` (`student_id`, `exam_name`),
  CHECK (`status` IN ('draft', 'submitted', 'confirmed', 'admitted', 'result_received'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Board exam (SSC/HSC/JSC/Dakhil) registration and form fill-up per student with fees and export.';


-- ============ LMS · courses, lessons, live classes ============
CREATE TABLE `courses` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `class_subject_id` CHAR(26) NULL,
  `title` VARCHAR(200) NOT NULL,
  `slug` VARCHAR(120) NOT NULL,
  `description` LONGTEXT NULL,
  `cover_file_id` CHAR(26) NULL,
  `teacher_id` CHAR(26) NULL,
  `is_paid` TINYINT(1) NOT NULL DEFAULT 0,
  `price` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `fee_head_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'draft',
  `published_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` DATETIME NULL COMMENT 'Soft delete',
  PRIMARY KEY (`id`),
  KEY `ix_courses_school_id` (`school_id`),
  KEY `ix_courses_class_subject_id` (`class_subject_id`),
  KEY `ix_courses_cover_file_id` (`cover_file_id`),
  KEY `ix_courses_teacher_id` (`teacher_id`),
  UNIQUE KEY `uq_courses_school_id_slug` (`school_id`, `slug`),
  CHECK (`status` IN ('draft', 'published', 'archived'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='A course: tied to a class-subject or sold standalone (coaching, skills).';

CREATE TABLE `course_modules` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `course_id` CHAR(26) NOT NULL,
  `title` VARCHAR(200) NOT NULL,
  `sequence` SMALLINT NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_course_modules_school_id` (`school_id`),
  KEY `ix_course_modules_course_id` (`course_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Sections inside a course.';

CREATE TABLE `lessons` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `module_id` CHAR(26) NOT NULL,
  `title` VARCHAR(200) NOT NULL,
  `sequence` SMALLINT NOT NULL,
  `lesson_type` VARCHAR(40) NOT NULL,
  `body` LONGTEXT NULL,
  `file_id` CHAR(26) NULL,
  `video_url` VARCHAR(500) NULL,
  `duration_min` SMALLINT NULL,
  `is_free_preview` TINYINT(1) NOT NULL DEFAULT 0,
  `unit_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_lessons_school_id` (`school_id`),
  KEY `ix_lessons_module_id` (`module_id`),
  KEY `ix_lessons_file_id` (`file_id`),
  KEY `ix_lessons_unit_id` (`unit_id`),
  CHECK (`lesson_type` IN ('video', 'note', 'link', 'file', 'quiz', 'assignment', 'live'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Lesson content: video, notes, link, SCORM/H5P, quiz.';

CREATE TABLE `course_enrollments` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `course_id` CHAR(26) NOT NULL,
  `student_id` CHAR(26) NOT NULL,
  `enrolled_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `progress_pct` DECIMAL(5,2) NOT NULL DEFAULT 0,
  `completed_at` DATETIME NULL,
  `certificate_doc_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_course_enrollments_school_id` (`school_id`),
  KEY `ix_course_enrollments_course_id` (`course_id`),
  KEY `ix_course_enrollments_student_id` (`student_id`),
  UNIQUE KEY `uq_course_enrollments_course_id_student_id` (`course_id`, `student_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Student enrolled in a course (auto for class-subject courses).';

CREATE TABLE `lesson_progress` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `lesson_id` CHAR(26) NOT NULL,
  `student_id` CHAR(26) NOT NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'not_started',
  `seconds_watched` INT NOT NULL DEFAULT 0,
  `last_position` INT NOT NULL DEFAULT 0,
  `completed_at` DATETIME NULL,
  PRIMARY KEY (`id`),
  KEY `ix_lesson_progress_school_id` (`school_id`),
  KEY `ix_lesson_progress_lesson_id` (`lesson_id`),
  KEY `ix_lesson_progress_student_id` (`student_id`),
  UNIQUE KEY `uq_lesson_progress_lesson_id_student_id` (`lesson_id`, `student_id`),
  CHECK (`status` IN ('not_started', 'in_progress', 'completed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Per student per lesson.';

CREATE TABLE `lesson_quiz_attempts` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `lesson_id` CHAR(26) NOT NULL,
  `student_id` CHAR(26) NOT NULL,
  `attempt_no` SMALLINT NOT NULL DEFAULT 1,
  `answers` JSON NULL,
  `score` DECIMAL(6,2) NOT NULL DEFAULT 0,
  `max_score` DECIMAL(6,2) NOT NULL DEFAULT 0,
  `passed` TINYINT(1) NOT NULL DEFAULT 0,
  `submitted_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_lesson_quiz_attempts_school_id` (`school_id`),
  KEY `ix_lesson_quiz_attempts_lesson_id` (`lesson_id`),
  KEY `ix_lesson_quiz_attempts_student_id` (`student_id`),
  KEY `ix_lesson_quiz_attempts_lesson_id_student_id` (`lesson_id`, `student_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='A go at the quiz inside a lesson: answers, score, and whether it passed.';

CREATE TABLE `assignments` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `section_id` CHAR(26) NOT NULL,
  `class_subject_id` CHAR(26) NOT NULL,
  `teacher_id` CHAR(26) NOT NULL,
  `lesson_id` CHAR(26) NULL,
  `title` VARCHAR(200) NOT NULL,
  `description` LONGTEXT NULL,
  `attachments` JSON NULL,
  `assigned_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `due_at` DATETIME NOT NULL,
  `max_marks` DECIMAL(6,2) NULL,
  `allow_late` TINYINT(1) NOT NULL DEFAULT 1,
  `late_penalty_pct` DECIMAL(5,2) NOT NULL DEFAULT 0,
  `submission_type` VARCHAR(40) NOT NULL DEFAULT 'file',
  `status` VARCHAR(40) NOT NULL DEFAULT 'published',
  `reminder_sent_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_assignments_school_id` (`school_id`),
  KEY `ix_assignments_section_id` (`section_id`),
  KEY `ix_assignments_class_subject_id` (`class_subject_id`),
  KEY `ix_assignments_teacher_id` (`teacher_id`),
  KEY `ix_assignments_lesson_id` (`lesson_id`),
  KEY `ix_assignments_school_id_due_at` (`school_id`, `due_at`),
  CHECK (`submission_type` IN ('file', 'text', 'both', 'offline', 'photo')),
  CHECK (`status` IN ('draft', 'published', 'closed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Homework/assignment with due date, penalty and submission type.';

CREATE TABLE `assignment_submissions` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `assignment_id` CHAR(26) NOT NULL,
  `student_id` CHAR(26) NOT NULL,
  `submitted_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `is_late` TINYINT(1) NOT NULL DEFAULT 0,
  `text_answer` LONGTEXT NULL,
  `attachments` JSON NULL,
  `marks` DECIMAL(6,2) NULL,
  `feedback` TEXT NULL,
  `similarity_pct` DECIMAL(5,2) NULL,
  `graded_by` CHAR(26) NULL,
  `graded_at` DATETIME NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'submitted',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_assignment_submissions_school_id` (`school_id`),
  KEY `ix_assignment_submissions_assignment_id` (`assignment_id`),
  KEY `ix_assignment_submissions_student_id` (`student_id`),
  KEY `ix_assignment_submissions_graded_by` (`graded_by`),
  UNIQUE KEY `uq_assignment_submissions_assignment_id_student_id` (`assignment_id`, `student_id`),
  CHECK (`status` IN ('submitted', 'graded', 'returned', 'resubmit'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Submission with grading and feedback; plagiarism score optional.';

CREATE TABLE `study_materials` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `class_subject_id` CHAR(26) NULL,
  `section_id` CHAR(26) NULL,
  `unit_id` CHAR(26) NULL,
  `title` VARCHAR(200) NOT NULL,
  `material_type` VARCHAR(40) NOT NULL,
  `file_id` CHAR(26) NULL,
  `external_url` VARCHAR(500) NULL,
  `uploaded_by` CHAR(26) NULL,
  `published_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `view_count` INT NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_study_materials_school_id` (`school_id`),
  KEY `ix_study_materials_class_subject_id` (`class_subject_id`),
  KEY `ix_study_materials_section_id` (`section_id`),
  KEY `ix_study_materials_unit_id` (`unit_id`),
  KEY `ix_study_materials_file_id` (`file_id`),
  KEY `ix_study_materials_uploaded_by` (`uploaded_by`),
  CHECK (`material_type` IN ('note', 'slide', 'video', 'link', 'book', 'audio'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Notes, slides, videos, links by unit.';

CREATE TABLE `online_classes` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `section_id` CHAR(26) NOT NULL,
  `class_subject_id` CHAR(26) NULL,
  `teacher_id` CHAR(26) NOT NULL,
  `slot_id` CHAR(26) NULL,
  `title` VARCHAR(200) NOT NULL,
  `platform` VARCHAR(40) NOT NULL,
  `meeting_id` VARCHAR(120) NULL,
  `join_url` VARCHAR(500) NULL,
  `host_url` VARCHAR(500) NULL,
  `starts_at` DATETIME NOT NULL,
  `duration_min` SMALLINT NOT NULL DEFAULT 40,
  `recording_url` VARCHAR(500) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'scheduled',
  `reminder_sent_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_online_classes_school_id` (`school_id`),
  KEY `ix_online_classes_section_id` (`section_id`),
  KEY `ix_online_classes_class_subject_id` (`class_subject_id`),
  KEY `ix_online_classes_teacher_id` (`teacher_id`),
  KEY `ix_online_classes_slot_id` (`slot_id`),
  KEY `ix_online_classes_school_id_starts_at` (`school_id`, `starts_at`),
  CHECK (`platform` IN ('zoom', 'google_meet', 'jitsi', 'bbb', 'youtube_live')),
  CHECK (`status` IN ('scheduled', 'live', 'ended', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Live class (Zoom/Meet/Jitsi) auto-created from timetable on remote days.';

CREATE TABLE `online_class_attendance` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `online_class_id` CHAR(26) NOT NULL,
  `student_id` CHAR(26) NOT NULL,
  `joined_at` DATETIME NULL,
  `left_at` DATETIME NULL,
  `minutes` SMALLINT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_online_class_attendance_school_id` (`school_id`),
  KEY `ix_online_class_attendance_online_class_id` (`online_class_id`),
  KEY `ix_online_class_attendance_student_id` (`student_id`),
  UNIQUE KEY `uq_online_class_attendance_online_class_id_student_id` (`online_class_id`, `student_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='From platform webhooks.';

CREATE TABLE `discussions` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `course_id` CHAR(26) NULL,
  `lesson_id` CHAR(26) NULL,
  `author_id` CHAR(26) NULL,
  `parent_id` CHAR(26) NULL,
  `body` TEXT NOT NULL,
  `is_answer` TINYINT(1) NOT NULL DEFAULT 0,
  `upvotes` INT NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_discussions_school_id` (`school_id`),
  KEY `ix_discussions_course_id` (`course_id`),
  KEY `ix_discussions_lesson_id` (`lesson_id`),
  KEY `ix_discussions_author_id` (`author_id`),
  KEY `ix_discussions_parent_id` (`parent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Q&A threads under lessons/courses.';


-- ============ Daily diary & early years ============
CREATE TABLE `diary_entries` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `section_id` CHAR(26) NOT NULL,
  `on_date` DATE NOT NULL,
  `teacher_id` CHAR(26) NULL,
  `class_subject_id` CHAR(26) NULL,
  `entry_type` VARCHAR(40) NOT NULL DEFAULT 'homework',
  `body` TEXT NOT NULL,
  `attachments` JSON NULL,
  `due_date` DATE NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_diary_entries_school_id` (`school_id`),
  KEY `ix_diary_entries_section_id` (`section_id`),
  KEY `ix_diary_entries_teacher_id` (`teacher_id`),
  KEY `ix_diary_entries_class_subject_id` (`class_subject_id`),
  KEY `ix_diary_entries_section_id_on_date` (`section_id`, `on_date`),
  CHECK (`entry_type` IN ('homework', 'note', 'reminder', 'announcement'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Per section per day: homework, notes, announcements — replaces the paper diary.';

CREATE TABLE `diary_acknowledgements` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `entry_id` CHAR(26) NOT NULL,
  `student_id` CHAR(26) NOT NULL,
  `guardian_id` CHAR(26) NULL,
  `acked_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_diary_acknowledgements_school_id` (`school_id`),
  KEY `ix_diary_acknowledgements_entry_id` (`entry_id`),
  KEY `ix_diary_acknowledgements_student_id` (`student_id`),
  KEY `ix_diary_acknowledgements_guardian_id` (`guardian_id`),
  UNIQUE KEY `uq_diary_acknowledgements_entry_id_student_id` (`entry_id`, `student_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Guardian saw/acknowledged.';

CREATE TABLE `daily_reports` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `on_date` DATE NOT NULL,
  `meals` JSON NULL,
  `nap_minutes` SMALLINT NULL,
  `mood` VARCHAR(40) NULL,
  `activities` JSON NULL,
  `toilet` JSON NULL,
  `notes` TEXT NULL,
  `photos` JSON NULL,
  `teacher_id` CHAR(26) NULL,
  `sent_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_daily_reports_school_id` (`school_id`),
  KEY `ix_daily_reports_student_id` (`student_id`),
  KEY `ix_daily_reports_teacher_id` (`teacher_id`),
  UNIQUE KEY `uq_daily_reports_student_id_on_date` (`student_id`, `on_date`),
  CHECK (`mood` IN ('happy', 'calm', 'tired', 'upset', 'sick'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Early-years daily report per child (meals, nap, mood, activities, photos).';

CREATE TABLE `student_remarks` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `teacher_id` CHAR(26) NOT NULL,
  `on_date` DATE NOT NULL,
  `remark` TEXT NOT NULL,
  `polarity` VARCHAR(40) NOT NULL DEFAULT 'neutral',
  `visible_to_guardian` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_student_remarks_school_id` (`school_id`),
  KEY `ix_student_remarks_student_id` (`student_id`),
  KEY `ix_student_remarks_teacher_id` (`teacher_id`),
  CHECK (`polarity` IN ('positive', 'neutral', 'concern'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Teacher remarks/observations on a student (positive or concern) visible to guardians.';


-- ============ Co-curricular · clubs, sports, achievements, portfolio ============
CREATE TABLE `clubs` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(120) NOT NULL,
  `category` VARCHAR(40) NOT NULL DEFAULT 'other',
  `advisor_id` CHAR(26) NULL,
  `description` TEXT NULL,
  `meeting_schedule` VARCHAR(120) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_clubs_school_id` (`school_id`),
  KEY `ix_clubs_advisor_id` (`advisor_id`),
  CHECK (`category` IN ('academic', 'sports', 'arts', 'social', 'tech', 'religious', 'other')),
  CHECK (`status` IN ('active', 'inactive'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Clubs/societies with advisor.';

CREATE TABLE `club_memberships` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `club_id` CHAR(26) NOT NULL,
  `student_id` CHAR(26) NOT NULL,
  `role` VARCHAR(40) NOT NULL DEFAULT 'member',
  `joined_on` DATE NOT NULL,
  `left_on` DATE NULL,
  PRIMARY KEY (`id`),
  KEY `ix_club_memberships_school_id` (`school_id`),
  KEY `ix_club_memberships_club_id` (`club_id`),
  KEY `ix_club_memberships_student_id` (`student_id`),
  UNIQUE KEY `uq_club_memberships_club_id_student_id` (`club_id`, `student_id`),
  CHECK (`role` IN ('member', 'secretary', 'president', 'captain'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Members and roles.';

CREATE TABLE `competitions` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(200) NOT NULL,
  `kind` VARCHAR(40) NOT NULL,
  `level` VARCHAR(40) NOT NULL DEFAULT 'intra',
  `held_on` DATE NULL,
  `venue` VARCHAR(160) NULL,
  `organiser` VARCHAR(160) NULL,
  `event_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_competitions_school_id` (`school_id`),
  CHECK (`kind` IN ('sports', 'academic', 'cultural', 'science', 'debate', 'olympiad', 'other')),
  CHECK (`level` IN ('intra', 'inter_school', 'district', 'national', 'international'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Internal/external competitions and events with results.';

CREATE TABLE `competition_results` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `competition_id` CHAR(26) NOT NULL,
  `student_id` CHAR(26) NULL,
  `club_id` CHAR(26) NULL,
  `house_id` CHAR(26) NULL,
  `position` SMALLINT NULL,
  `award` VARCHAR(120) NULL,
  `points` INT NOT NULL DEFAULT 0,
  `certificate_doc_id` CHAR(26) NULL,
  PRIMARY KEY (`id`),
  KEY `ix_competition_results_school_id` (`school_id`),
  KEY `ix_competition_results_competition_id` (`competition_id`),
  KEY `ix_competition_results_student_id` (`student_id`),
  KEY `ix_competition_results_club_id` (`club_id`),
  KEY `ix_competition_results_house_id` (`house_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Placement per participant/team.';

CREATE TABLE `house_points` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `house_id` CHAR(26) NOT NULL,
  `student_id` CHAR(26) NULL,
  `points` INT NOT NULL,
  `reason` VARCHAR(160) NOT NULL,
  `source_type` VARCHAR(40) NULL,
  `source_id` CHAR(26) NULL,
  `awarded_by` CHAR(26) NULL,
  `awarded_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_house_points_school_id` (`school_id`),
  KEY `ix_house_points_house_id` (`house_id`),
  KEY `ix_house_points_student_id` (`student_id`),
  KEY `ix_house_points_awarded_by` (`awarded_by`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Points ledger per house (behaviour, sports, competitions).';

CREATE TABLE `achievements` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `title` VARCHAR(200) NOT NULL,
  `category` VARCHAR(60) NULL,
  `achieved_on` DATE NULL,
  `description` TEXT NULL,
  `file_id` CHAR(26) NULL,
  `verified_by` CHAR(26) NULL,
  `is_public` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_achievements_school_id` (`school_id`),
  KEY `ix_achievements_student_id` (`student_id`),
  KEY `ix_achievements_file_id` (`file_id`),
  KEY `ix_achievements_verified_by` (`verified_by`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Student achievements and awards (portfolio).';

CREATE TABLE `skill_badges` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(80) NOT NULL,
  `icon_file_id` CHAR(26) NULL,
  `criteria` TEXT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_skill_badges_school_id` (`school_id`),
  KEY `ix_skill_badges_icon_file_id` (`icon_file_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Badge catalogue (e.g. Reading star, Coder L1).';

CREATE TABLE `student_badges` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `badge_id` CHAR(26) NOT NULL,
  `student_id` CHAR(26) NOT NULL,
  `awarded_by` CHAR(26) NULL,
  `awarded_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_student_badges_school_id` (`school_id`),
  KEY `ix_student_badges_badge_id` (`badge_id`),
  KEY `ix_student_badges_student_id` (`student_id`),
  KEY `ix_student_badges_awarded_by` (`awarded_by`),
  UNIQUE KEY `uq_student_badges_badge_id_student_id` (`badge_id`, `student_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Badges earned.';


-- ============ Library & e-library ============
CREATE TABLE `library_categories` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(80) NOT NULL,
  `parent_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_library_categories_school_id` (`school_id`),
  KEY `ix_library_categories_parent_id` (`parent_id`),
  UNIQUE KEY `uq_library_categories_school_id_name` (`school_id`, `name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Category tree.';

CREATE TABLE `library_books` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `isbn` VARCHAR(20) NULL,
  `title` VARCHAR(255) NOT NULL,
  `subtitle` VARCHAR(255) NULL,
  `authors` JSON NULL,
  `publisher` VARCHAR(160) NULL,
  `edition` VARCHAR(40) NULL,
  `published_year` SMALLINT NULL,
  `language` VARCHAR(10) NOT NULL DEFAULT 'bn',
  `category_id` CHAR(26) NULL,
  `subject_id` CHAR(26) NULL,
  `class_id` CHAR(26) NULL,
  `pages` SMALLINT NULL,
  `price` DECIMAL(14,2) NULL,
  `cover_file_id` CHAR(26) NULL,
  `ebook_file_id` CHAR(26) NULL,
  `description` TEXT NULL,
  `total_copies` INT NOT NULL DEFAULT 0,
  `available_copies` INT NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_library_books_school_id` (`school_id`),
  KEY `ix_library_books_category_id` (`category_id`),
  KEY `ix_library_books_subject_id` (`subject_id`),
  KEY `ix_library_books_class_id` (`class_id`),
  KEY `ix_library_books_cover_file_id` (`cover_file_id`),
  KEY `ix_library_books_ebook_file_id` (`ebook_file_id`),
  KEY `ix_library_books_school_id_title` (`school_id`, `title`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Title-level record.';

CREATE TABLE `library_book_copies` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `book_id` CHAR(26) NOT NULL,
  `accession_no` VARCHAR(30) NOT NULL,
  `barcode` VARCHAR(40) NULL,
  `rack` VARCHAR(20) NULL,
  `shelf` VARCHAR(20) NULL,
  `condition_note` VARCHAR(40) NOT NULL DEFAULT 'good',
  `status` VARCHAR(40) NOT NULL DEFAULT 'available',
  `acquired_on` DATE NULL,
  `source` VARCHAR(40) NOT NULL DEFAULT 'purchase',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_library_book_copies_school_id` (`school_id`),
  KEY `ix_library_book_copies_book_id` (`book_id`),
  UNIQUE KEY `uq_library_book_copies_school_id_accession_no` (`school_id`, `accession_no`),
  CHECK (`condition_note` IN ('new', 'good', 'fair', 'poor')),
  CHECK (`status` IN ('available', 'issued', 'reserved', 'lost', 'damaged', 'withdrawn')),
  CHECK (`source` IN ('purchase', 'donation'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Physical copy with accession no and status.';

CREATE TABLE `library_members` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `member_type` VARCHAR(40) NOT NULL,
  `student_id` CHAR(26) NULL,
  `staff_id` CHAR(26) NULL,
  `card_no` VARCHAR(30) NOT NULL,
  `max_books` SMALLINT NOT NULL DEFAULT 2,
  `loan_days` SMALLINT NOT NULL DEFAULT 14,
  `fine_per_day` DECIMAL(14,2) NOT NULL DEFAULT 5,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `blocked_reason` VARCHAR(120) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_library_members_school_id` (`school_id`),
  KEY `ix_library_members_student_id` (`student_id`),
  KEY `ix_library_members_staff_id` (`staff_id`),
  UNIQUE KEY `uq_library_members_school_id_card_no` (`school_id`, `card_no`),
  CHECK (`member_type` IN ('student', 'staff', 'guardian')),
  CHECK (`status` IN ('active', 'blocked', 'inactive'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Student or staff member with limits.';

CREATE TABLE `library_issues` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `copy_id` CHAR(26) NOT NULL,
  `member_id` CHAR(26) NOT NULL,
  `issued_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `due_at` DATE NOT NULL,
  `returned_at` DATETIME NULL,
  `renew_count` SMALLINT NOT NULL DEFAULT 0,
  `issued_by` CHAR(26) NULL,
  `returned_to` CHAR(26) NULL,
  `fine_amount` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `fine_invoice_item_id` CHAR(26) NULL,
  `fine_waived_by` CHAR(26) NULL,
  `reminder_stage` VARCHAR(20) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'issued',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_library_issues_school_id` (`school_id`),
  KEY `ix_library_issues_copy_id` (`copy_id`),
  KEY `ix_library_issues_member_id` (`member_id`),
  KEY `ix_library_issues_issued_by` (`issued_by`),
  KEY `ix_library_issues_returned_to` (`returned_to`),
  KEY `ix_library_issues_fine_waived_by` (`fine_waived_by`),
  KEY `ix_library_issues_school_id_due_at` (`school_id`, `due_at`),
  CHECK (`status` IN ('issued', 'returned', 'lost', 'overdue'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Issue/return with fine accrual and reminder stage.';

CREATE TABLE `library_reservations` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `book_id` CHAR(26) NOT NULL,
  `member_id` CHAR(26) NOT NULL,
  `reserved_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `notified_at` DATETIME NULL,
  `expires_at` DATETIME NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'waiting',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_library_reservations_school_id` (`school_id`),
  KEY `ix_library_reservations_book_id` (`book_id`),
  KEY `ix_library_reservations_member_id` (`member_id`),
  CHECK (`status` IN ('waiting', 'ready', 'fulfilled', 'expired', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Hold queue.';

CREATE TABLE `reading_logs` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `book_id` CHAR(26) NOT NULL,
  `pages_read` INT NOT NULL DEFAULT 0,
  `finished` TINYINT(1) NOT NULL DEFAULT 0,
  `review` TEXT NULL,
  `rating` SMALLINT NULL,
  `logged_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_reading_logs_school_id` (`school_id`),
  KEY `ix_reading_logs_student_id` (`student_id`),
  KEY `ix_reading_logs_book_id` (`book_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Reading programme: pages read, reviews (reading badges).';


-- ============ Fees & billing ============
CREATE TABLE `fee_heads` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(80) NOT NULL,
  `code` VARCHAR(20) NOT NULL,
  `head_kind` VARCHAR(40) NOT NULL DEFAULT 'academic',
  `gl_account_id` CHAR(26) NULL,
  `is_refundable` TINYINT(1) NOT NULL DEFAULT 0,
  `tax_pct` DECIMAL(5,2) NOT NULL DEFAULT 0,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_fee_heads_school_id` (`school_id`),
  UNIQUE KEY `uq_fee_heads_school_id_code` (`school_id`, `code`),
  CHECK (`head_kind` IN ('academic', 'transport', 'hostel', 'fine', 'misc', 'course', 'shop', 'canteen')),
  CHECK (`status` IN ('active', 'inactive'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tuition, admission, exam, transport, hostel, fine, canteen…';

CREATE TABLE `late_fine_rules` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(80) NOT NULL,
  `grace_days` SMALLINT NOT NULL DEFAULT 0,
  `fine_type` VARCHAR(40) NOT NULL,
  `value` DECIMAL(14,2) NOT NULL,
  `max_amount` DECIMAL(14,2) NULL,
  `fine_head_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_late_fine_rules_school_id` (`school_id`),
  KEY `ix_late_fine_rules_fine_head_id` (`fine_head_id`),
  UNIQUE KEY `uq_late_fine_rules_school_id_name` (`school_id`, `name`),
  CHECK (`fine_type` IN ('flat', 'percent', 'per_day', 'per_week'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Grace days, flat/percent/per-day, cap.';

CREATE TABLE `fee_structures` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `academic_year_id` CHAR(26) NOT NULL,
  `class_id` CHAR(26) NOT NULL,
  `campus_id` CHAR(26) NULL,
  `shift_id` CHAR(26) NULL,
  `program_id` CHAR(26) NULL,
  `name` VARCHAR(120) NOT NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_fee_structures_school_id` (`school_id`),
  KEY `ix_fee_structures_academic_year_id` (`academic_year_id`),
  KEY `ix_fee_structures_class_id` (`class_id`),
  KEY `ix_fee_structures_campus_id` (`campus_id`),
  KEY `ix_fee_structures_shift_id` (`shift_id`),
  KEY `ix_fee_structures_program_id` (`program_id`),
  UNIQUE KEY `uq_fee_structures_academic_year_id_class_id_campus_id_shift_id_p` (`academic_year_id`, `class_id`, `campus_id`, `shift_id`, `program_id`),
  CHECK (`status` IN ('active', 'inactive'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Fee plan for a class (optionally campus/shift/programme) per year.';

CREATE TABLE `fee_structure_items` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `fee_structure_id` CHAR(26) NOT NULL,
  `fee_head_id` CHAR(26) NOT NULL,
  `amount` DECIMAL(14,2) NOT NULL,
  `frequency` VARCHAR(40) NOT NULL DEFAULT 'monthly',
  `due_day` SMALLINT NOT NULL DEFAULT 10,
  `applicable_months` JSON NULL,
  `late_fine_rule_id` CHAR(26) NULL,
  PRIMARY KEY (`id`),
  KEY `ix_fee_structure_items_school_id` (`school_id`),
  KEY `ix_fee_structure_items_fee_structure_id` (`fee_structure_id`),
  KEY `ix_fee_structure_items_fee_head_id` (`fee_head_id`),
  KEY `ix_fee_structure_items_late_fine_rule_id` (`late_fine_rule_id`),
  UNIQUE KEY `uq_fee_structure_items_fee_structure_id_fee_head_id` (`fee_structure_id`, `fee_head_id`),
  CHECK (`frequency` IN ('one_time', 'monthly', 'quarterly', 'half_yearly', 'yearly', 'per_term'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Head × amount × frequency × due day × months.';

CREATE TABLE `student_fee_overrides` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `academic_year_id` CHAR(26) NOT NULL,
  `fee_head_id` CHAR(26) NOT NULL,
  `amount` DECIMAL(14,2) NULL,
  `reason` VARCHAR(160) NULL,
  `approved_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_student_fee_overrides_school_id` (`school_id`),
  KEY `ix_student_fee_overrides_student_id` (`student_id`),
  KEY `ix_student_fee_overrides_academic_year_id` (`academic_year_id`),
  KEY `ix_student_fee_overrides_fee_head_id` (`fee_head_id`),
  KEY `ix_student_fee_overrides_approved_by` (`approved_by`),
  UNIQUE KEY `uq_student_fee_overrides_student_id_academic_year_id_fee_head_id` (`student_id`, `academic_year_id`, `fee_head_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Per-student amount or waiver for a head.';

CREATE TABLE `discount_schemes` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(120) NOT NULL,
  `discount_kind` VARCHAR(40) NOT NULL,
  `value_type` VARCHAR(40) NOT NULL,
  `value` DECIMAL(14,2) NOT NULL,
  `applies_to_heads` JSON NULL,
  `auto_rule` JSON NULL,
  `requires_approval` TINYINT(1) NOT NULL DEFAULT 1,
  `budget_cap` DECIMAL(14,2) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_discount_schemes_school_id` (`school_id`),
  UNIQUE KEY `uq_discount_schemes_school_id_name` (`school_id`, `name`),
  CHECK (`discount_kind` IN ('sibling', 'merit', 'staff_child', 'need_based', 'early_payment', 'scholarship', 'custom')),
  CHECK (`value_type` IN ('percent', 'flat')),
  CHECK (`status` IN ('active', 'inactive'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Sibling / merit / staff child / need-based / early payment with auto rule.';

CREATE TABLE `student_discounts` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `discount_scheme_id` CHAR(26) NOT NULL,
  `academic_year_id` CHAR(26) NOT NULL,
  `value_override` DECIMAL(14,2) NULL,
  `valid_from` DATE NULL,
  `valid_to` DATE NULL,
  `is_auto` TINYINT(1) NOT NULL DEFAULT 0,
  `status` VARCHAR(40) NOT NULL DEFAULT 'pending',
  `approved_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_student_discounts_school_id` (`school_id`),
  KEY `ix_student_discounts_student_id` (`student_id`),
  KEY `ix_student_discounts_discount_scheme_id` (`discount_scheme_id`),
  KEY `ix_student_discounts_academic_year_id` (`academic_year_id`),
  KEY `ix_student_discounts_approved_by` (`approved_by`),
  UNIQUE KEY `uq_student_discounts_student_id_discount_scheme_id_academic_year` (`student_id`, `discount_scheme_id`, `academic_year_id`),
  CHECK (`status` IN ('pending', 'approved', 'rejected', 'expired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Discount granted (or auto-proposed) to a student for a year.';

CREATE TABLE `instalment_plans` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `fee_head_id` CHAR(26) NOT NULL,
  `total_amount` DECIMAL(14,2) NOT NULL,
  `instalments` JSON NULL COMMENT '[{due:''2026-10-10'',amount:5000},…]',
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `approved_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_instalment_plans_school_id` (`school_id`),
  KEY `ix_instalment_plans_student_id` (`student_id`),
  KEY `ix_instalment_plans_fee_head_id` (`fee_head_id`),
  KEY `ix_instalment_plans_approved_by` (`approved_by`),
  CHECK (`status` IN ('active', 'completed', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Split a large fee (admission, yearly) into instalments per student.';

CREATE TABLE `invoice_batches` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `academic_year_id` CHAR(26) NOT NULL,
  `billing_period` DATE NOT NULL,
  `scope` JSON NULL,
  `generated_by` CHAR(26) NULL,
  `invoice_count` INT NOT NULL DEFAULT 0,
  `total_amount` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `status` VARCHAR(40) NOT NULL DEFAULT 'pending',
  `started_at` DATETIME NULL,
  `finished_at` DATETIME NULL,
  `error` TEXT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_invoice_batches_school_id` (`school_id`),
  KEY `ix_invoice_batches_academic_year_id` (`academic_year_id`),
  KEY `ix_invoice_batches_generated_by` (`generated_by`),
  CHECK (`status` IN ('pending', 'running', 'success', 'failed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='One generation run (e.g. October tuition for all classes).';

CREATE TABLE `invoices` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `invoice_no` VARCHAR(30) NOT NULL,
  `student_id` CHAR(26) NULL,
  `application_id` CHAR(26) NULL,
  `academic_year_id` CHAR(26) NULL,
  `batch_id` CHAR(26) NULL,
  `billing_period` DATE NULL,
  `issue_date` DATE NOT NULL,
  `due_date` DATE NOT NULL,
  `subtotal` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `discount_total` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `fine_total` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `tax_total` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `total` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `paid_total` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `balance` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `status` VARCHAR(40) NOT NULL DEFAULT 'issued',
  `is_auto` TINYINT(1) NOT NULL DEFAULT 1,
  `notes` VARCHAR(255) NULL,
  `pdf_file_id` CHAR(26) NULL,
  `last_reminder_stage` VARCHAR(20) NULL,
  `last_reminder_at` DATETIME NULL,
  `fine_applied_at` DATETIME NULL,
  `cancelled_at` DATETIME NULL,
  `cancel_reason` VARCHAR(160) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_invoices_school_id` (`school_id`),
  KEY `ix_invoices_student_id` (`student_id`),
  KEY `ix_invoices_application_id` (`application_id`),
  KEY `ix_invoices_academic_year_id` (`academic_year_id`),
  KEY `ix_invoices_batch_id` (`batch_id`),
  KEY `ix_invoices_pdf_file_id` (`pdf_file_id`),
  UNIQUE KEY `uq_invoices_school_id_invoice_no` (`school_id`, `invoice_no`),
  KEY `ix_invoices_student_id_status` (`student_id`, `status`),
  KEY `ix_invoices_school_id_due_date_status` (`school_id`, `due_date`, `status`),
  CHECK (`status` IN ('draft', 'issued', 'partially_paid', 'paid', 'overdue', 'cancelled', 'written_off'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Student (or applicant) invoice with totals, status and reminder stamps.';

CREATE TABLE `invoice_items` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `invoice_id` CHAR(26) NOT NULL,
  `fee_head_id` CHAR(26) NULL,
  `description` VARCHAR(200) NOT NULL,
  `quantity` DECIMAL(8,2) NOT NULL DEFAULT 1,
  `unit_amount` DECIMAL(14,2) NOT NULL,
  `discount_amount` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `discount_id` CHAR(26) NULL,
  `tax_amount` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `amount` DECIMAL(14,2) NOT NULL,
  `item_kind` VARCHAR(40) NOT NULL DEFAULT 'fee',
  `source_type` VARCHAR(40) NULL,
  `source_id` CHAR(26) NULL,
  PRIMARY KEY (`id`),
  KEY `ix_invoice_items_school_id` (`school_id`),
  KEY `ix_invoice_items_invoice_id` (`invoice_id`),
  KEY `ix_invoice_items_fee_head_id` (`fee_head_id`),
  KEY `ix_invoice_items_discount_id` (`discount_id`),
  CHECK (`item_kind` IN ('fee', 'fine', 'adjustment', 'previous_due', 'course', 'shop'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Lines: fee, fine, adjustment, previous due; source pointer (library issue, transport…).';

CREATE TABLE `payment_gateways` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `provider` VARCHAR(40) NOT NULL,
  `display_name` VARCHAR(80) NOT NULL,
  `credentials` JSON NULL,
  `is_sandbox` TINYINT(1) NOT NULL DEFAULT 1,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `settle_to_bank_account_id` CHAR(26) NULL,
  `fee_pct` DECIMAL(5,2) NOT NULL DEFAULT 0,
  `fee_fixed` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `sort_order` SMALLINT NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_payment_gateways_school_id` (`school_id`),
  UNIQUE KEY `uq_payment_gateways_school_id_provider` (`school_id`, `provider`),
  CHECK (`provider` IN ('sslcommerz', 'bkash', 'nagad', 'rocket', 'upay', 'aamarpay', 'shurjopay', 'stripe', 'paypal', 'razorpay'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Configured gateways with encrypted credentials and settlement account.';

CREATE TABLE `payments` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `payment_no` VARCHAR(30) NOT NULL,
  `student_id` CHAR(26) NULL,
  `application_id` CHAR(26) NULL,
  `payer_user_id` CHAR(26) NULL,
  `amount` DECIMAL(14,2) NOT NULL,
  `method` VARCHAR(40) NOT NULL,
  `gateway_id` CHAR(26) NULL,
  `gateway_txn_id` VARCHAR(120) NULL,
  `gateway_payload` JSON NULL,
  `bank_account_id` CHAR(26) NULL,
  `reference` VARCHAR(120) NULL,
  `paid_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `received_by` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'success',
  `receipt_file_id` CHAR(26) NULL,
  `journal_entry_id` CHAR(26) NULL,
  `cash_session_id` CHAR(26) NULL,
  `notes` VARCHAR(255) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_payments_school_id` (`school_id`),
  KEY `ix_payments_student_id` (`student_id`),
  KEY `ix_payments_application_id` (`application_id`),
  KEY `ix_payments_payer_user_id` (`payer_user_id`),
  KEY `ix_payments_gateway_id` (`gateway_id`),
  KEY `ix_payments_received_by` (`received_by`),
  KEY `ix_payments_receipt_file_id` (`receipt_file_id`),
  UNIQUE KEY `uq_payments_school_id_payment_no` (`school_id`, `payment_no`),
  UNIQUE KEY `uq_payments_gateway_id_gateway_txn_id` (`gateway_id`, `gateway_txn_id`),
  KEY `ix_payments_student_id_paid_at` (`student_id`, `paid_at`),
  CHECK (`method` IN ('cash', 'bank_transfer', 'cheque', 'card', 'bkash', 'nagad', 'rocket', 'upay', 'sslcommerz', 'stripe', 'wallet', 'adjustment', 'other')),
  CHECK (`status` IN ('pending', 'success', 'failed', 'refunded', 'reversed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Money received; allocated to invoices; journal auto-posted.';

CREATE TABLE `payment_allocations` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `payment_id` CHAR(26) NOT NULL,
  `invoice_id` CHAR(26) NOT NULL,
  `amount` DECIMAL(14,2) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_payment_allocations_school_id` (`school_id`),
  KEY `ix_payment_allocations_payment_id` (`payment_id`),
  KEY `ix_payment_allocations_invoice_id` (`invoice_id`),
  UNIQUE KEY `uq_payment_allocations_payment_id_invoice_id` (`payment_id`, `invoice_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Payment → invoice amounts; unallocated remainder = advance credit.';

CREATE TABLE `refunds` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `payment_id` CHAR(26) NOT NULL,
  `amount` DECIMAL(14,2) NOT NULL,
  `reason` VARCHAR(255) NOT NULL,
  `requested_by` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'pending',
  `approved_by` CHAR(26) NULL,
  `refunded_at` DATETIME NULL,
  `gateway_refund_id` VARCHAR(120) NULL,
  `journal_entry_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_refunds_school_id` (`school_id`),
  KEY `ix_refunds_payment_id` (`payment_id`),
  KEY `ix_refunds_requested_by` (`requested_by`),
  KEY `ix_refunds_approved_by` (`approved_by`),
  CHECK (`status` IN ('pending', 'approved', 'rejected', 'refunded'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Refund with approval, gateway refund id and reversal journal.';

CREATE TABLE `student_ledger_entries` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `entry_type` VARCHAR(40) NOT NULL,
  `ref_type` VARCHAR(40) NOT NULL,
  `ref_id` CHAR(26) NOT NULL,
  `debit` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `credit` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `balance_after` DECIMAL(14,2) NOT NULL,
  `description` VARCHAR(200) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_student_ledger_entries_school_id` (`school_id`),
  KEY `ix_student_ledger_entries_student_id` (`student_id`),
  KEY `ix_student_ledger_entries_student_id_created_at` (`student_id`, `created_at`),
  CHECK (`entry_type` IN ('invoice', 'payment', 'refund', 'adjustment', 'fine', 'write_off', 'advance'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Append-only running ledger per student.';

CREATE TABLE `fee_reminders` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `invoice_id` CHAR(26) NOT NULL,
  `stage` VARCHAR(20) NOT NULL,
  `channel` VARCHAR(40) NOT NULL,
  `notification_id` CHAR(26) NULL,
  `sent_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_fee_reminders_school_id` (`school_id`),
  KEY `ix_fee_reminders_invoice_id` (`invoice_id`),
  UNIQUE KEY `uq_fee_reminders_invoice_id_stage_channel` (`invoice_id`, `stage`, `channel`),
  CHECK (`channel` IN ('sms', 'push', 'email', 'whatsapp', 'call_task'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Reminder sent per invoice per stage per channel.';

CREATE TABLE `cash_sessions` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `cashier_id` CHAR(26) NOT NULL,
  `opened_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `closed_at` DATETIME NULL,
  `opening_cash` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `expected_cash` DECIMAL(14,2) NULL,
  `counted_cash` DECIMAL(14,2) NULL,
  `variance` DECIMAL(14,2) NULL,
  `deposited_to` CHAR(26) NULL,
  `note` VARCHAR(255) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_cash_sessions_school_id` (`school_id`),
  KEY `ix_cash_sessions_cashier_id` (`cashier_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Counter session with opening/closing count and variance.';

CREATE TABLE `fee_collection_daily` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `on_date` DATE NOT NULL,
  `method` VARCHAR(20) NOT NULL,
  `count` INT NOT NULL DEFAULT 0,
  `amount` DECIMAL(14,2) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `ix_fee_collection_daily_school_id` (`school_id`),
  UNIQUE KEY `uq_fee_collection_daily_school_id_on_date_method` (`school_id`, `on_date`, `method`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Rollup per day per method for dashboards.';


-- ============ Accounting · GL, AP/AR, assets, statements ============
CREATE TABLE `fiscal_years` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(20) NOT NULL,
  `start_date` DATE NOT NULL,
  `end_date` DATE NOT NULL,
  `is_closed` TINYINT(1) NOT NULL DEFAULT 0,
  `closed_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_fiscal_years_school_id` (`school_id`),
  UNIQUE KEY `uq_fiscal_years_school_id_name` (`school_id`, `name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Financial year (BD: July–June).';

CREATE TABLE `gl_accounts` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `code` VARCHAR(20) NOT NULL,
  `name` VARCHAR(120) NOT NULL,
  `account_type` VARCHAR(40) NOT NULL,
  `parent_id` CHAR(26) NULL,
  `is_group` TINYINT(1) NOT NULL DEFAULT 0,
  `is_system` TINYINT(1) NOT NULL DEFAULT 0,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_gl_accounts_school_id` (`school_id`),
  KEY `ix_gl_accounts_parent_id` (`parent_id`),
  UNIQUE KEY `uq_gl_accounts_school_id_code` (`school_id`, `code`),
  CHECK (`account_type` IN ('asset', 'liability', 'equity', 'income', 'expense')),
  CHECK (`status` IN ('active', 'inactive'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Chart of accounts tree.';

CREATE TABLE `cost_centers` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(80) NOT NULL,
  `campus_id` CHAR(26) NULL,
  `department_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_cost_centers_school_id` (`school_id`),
  KEY `ix_cost_centers_campus_id` (`campus_id`),
  KEY `ix_cost_centers_department_id` (`department_id`),
  UNIQUE KEY `uq_cost_centers_school_id_name` (`school_id`, `name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Campus / department / project for reporting.';

CREATE TABLE `bank_accounts` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `gl_account_id` CHAR(26) NOT NULL,
  `bank_name` VARCHAR(120) NOT NULL,
  `branch` VARCHAR(120) NULL,
  `account_name` VARCHAR(160) NOT NULL,
  `account_no` VARCHAR(60) NOT NULL,
  `routing_no` VARCHAR(30) NULL,
  `account_kind` VARCHAR(40) NOT NULL DEFAULT 'bank',
  `is_default_collection` TINYINT(1) NOT NULL DEFAULT 0,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_bank_accounts_school_id` (`school_id`),
  KEY `ix_bank_accounts_gl_account_id` (`gl_account_id`),
  CHECK (`account_kind` IN ('bank', 'mfs', 'cash_box', 'card')),
  CHECK (`status` IN ('active', 'inactive'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Bank, MFS merchant and cash boxes.';

CREATE TABLE `journal_entries` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `fiscal_year_id` CHAR(26) NULL,
  `entry_no` VARCHAR(30) NOT NULL,
  `entry_date` DATE NOT NULL,
  `memo` VARCHAR(255) NULL,
  `source_type` VARCHAR(40) NULL,
  `source_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'posted',
  `reversal_of_id` CHAR(26) NULL,
  `posted_by` CHAR(26) NULL,
  `is_auto` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_journal_entries_school_id` (`school_id`),
  KEY `ix_journal_entries_fiscal_year_id` (`fiscal_year_id`),
  KEY `ix_journal_entries_reversal_of_id` (`reversal_of_id`),
  KEY `ix_journal_entries_posted_by` (`posted_by`),
  UNIQUE KEY `uq_journal_entries_school_id_entry_no` (`school_id`, `entry_no`),
  KEY `ix_journal_entries_source_type_source_id` (`source_type`, `source_id`),
  KEY `ix_journal_entries_school_id_entry_date` (`school_id`, `entry_date`),
  CHECK (`status` IN ('draft', 'posted', 'reversed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Balanced entries; app refuses unbalanced.';

CREATE TABLE `journal_lines` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `entry_id` CHAR(26) NOT NULL,
  `account_id` CHAR(26) NOT NULL,
  `cost_center_id` CHAR(26) NULL,
  `debit` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `credit` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `description` VARCHAR(200) NULL,
  PRIMARY KEY (`id`),
  KEY `ix_journal_lines_school_id` (`school_id`),
  KEY `ix_journal_lines_entry_id` (`entry_id`),
  KEY `ix_journal_lines_account_id` (`account_id`),
  KEY `ix_journal_lines_cost_center_id` (`cost_center_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Debit/credit lines.';

CREATE TABLE `expense_categories` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(80) NOT NULL,
  `gl_account_id` CHAR(26) NULL,
  `requires_approval_above` DECIMAL(14,2) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_expense_categories_school_id` (`school_id`),
  KEY `ix_expense_categories_gl_account_id` (`gl_account_id`),
  UNIQUE KEY `uq_expense_categories_school_id_name` (`school_id`, `name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Expense categories with GL account and approval threshold.';

CREATE TABLE `vendors` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(160) NOT NULL,
  `phone` VARCHAR(30) NULL,
  `email` VARCHAR(160) NULL,
  `address` JSON NULL,
  `tax_id` VARCHAR(40) NULL,
  `bank_details` JSON NULL,
  `payable_gl_account_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_vendors_school_id` (`school_id`),
  KEY `ix_vendors_payable_gl_account_id` (`payable_gl_account_id`),
  CHECK (`status` IN ('active', 'inactive'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Suppliers/contractors.';

CREATE TABLE `expenses` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `expense_no` VARCHAR(30) NOT NULL,
  `category_id` CHAR(26) NOT NULL,
  `vendor_id` CHAR(26) NULL,
  `cost_center_id` CHAR(26) NULL,
  `expense_date` DATE NOT NULL,
  `amount` DECIMAL(14,2) NOT NULL,
  `tax_amount` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `paid_from_id` CHAR(26) NULL,
  `payment_method` VARCHAR(20) NULL,
  `reference` VARCHAR(120) NULL,
  `description` VARCHAR(255) NULL,
  `bill_file_id` CHAR(26) NULL,
  `requested_by` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'pending',
  `approval_request_id` CHAR(26) NULL,
  `approved_by` CHAR(26) NULL,
  `paid_at` DATETIME NULL,
  `journal_entry_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_expenses_school_id` (`school_id`),
  KEY `ix_expenses_category_id` (`category_id`),
  KEY `ix_expenses_vendor_id` (`vendor_id`),
  KEY `ix_expenses_cost_center_id` (`cost_center_id`),
  KEY `ix_expenses_paid_from_id` (`paid_from_id`),
  KEY `ix_expenses_bill_file_id` (`bill_file_id`),
  KEY `ix_expenses_requested_by` (`requested_by`),
  KEY `ix_expenses_approved_by` (`approved_by`),
  KEY `ix_expenses_journal_entry_id` (`journal_entry_id`),
  UNIQUE KEY `uq_expenses_school_id_expense_no` (`school_id`, `expense_no`),
  CHECK (`status` IN ('pending', 'approved', 'rejected', 'paid'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Expense claim/voucher with approval and payment.';

CREATE TABLE `vendor_bills` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `vendor_id` CHAR(26) NOT NULL,
  `bill_no` VARCHAR(60) NOT NULL,
  `bill_date` DATE NOT NULL,
  `due_date` DATE NULL,
  `subtotal` DECIMAL(14,2) NOT NULL,
  `tax` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `total` DECIMAL(14,2) NOT NULL,
  `paid_total` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `status` VARCHAR(40) NOT NULL DEFAULT 'open',
  `po_id` CHAR(26) NULL,
  `file_id` CHAR(26) NULL,
  `journal_entry_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_vendor_bills_school_id` (`school_id`),
  KEY `ix_vendor_bills_vendor_id` (`vendor_id`),
  KEY `ix_vendor_bills_file_id` (`file_id`),
  KEY `ix_vendor_bills_journal_entry_id` (`journal_entry_id`),
  CHECK (`status` IN ('open', 'partially_paid', 'paid', 'void'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Accounts payable: bills from vendors (from POs) with due dates and payments.';

CREATE TABLE `vendor_payments` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `vendor_id` CHAR(26) NOT NULL,
  `bill_id` CHAR(26) NULL,
  `amount` DECIMAL(14,2) NOT NULL,
  `paid_from_id` CHAR(26) NULL,
  `method` VARCHAR(20) NULL,
  `reference` VARCHAR(120) NULL,
  `paid_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `journal_entry_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_vendor_payments_school_id` (`school_id`),
  KEY `ix_vendor_payments_vendor_id` (`vendor_id`),
  KEY `ix_vendor_payments_bill_id` (`bill_id`),
  KEY `ix_vendor_payments_paid_from_id` (`paid_from_id`),
  KEY `ix_vendor_payments_journal_entry_id` (`journal_entry_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Payments to vendors.';

CREATE TABLE `other_incomes` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `gl_account_id` CHAR(26) NOT NULL,
  `received_in_id` CHAR(26) NULL,
  `income_date` DATE NOT NULL,
  `amount` DECIMAL(14,2) NOT NULL,
  `payer` VARCHAR(160) NULL,
  `description` VARCHAR(255) NULL,
  `journal_entry_id` CHAR(26) NULL,
  `created_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_other_incomes_school_id` (`school_id`),
  KEY `ix_other_incomes_gl_account_id` (`gl_account_id`),
  KEY `ix_other_incomes_received_in_id` (`received_in_id`),
  KEY `ix_other_incomes_journal_entry_id` (`journal_entry_id`),
  KEY `ix_other_incomes_created_by` (`created_by`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Non-fee income (rent, donations receipts, interest).';

CREATE TABLE `budgets` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `fiscal_year_id` CHAR(26) NOT NULL,
  `gl_account_id` CHAR(26) NOT NULL,
  `cost_center_id` CHAR(26) NULL,
  `amount` DECIMAL(14,2) NOT NULL,
  `alert_at_pct` DECIMAL(5,2) NOT NULL DEFAULT 90,
  `alerted_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_budgets_school_id` (`school_id`),
  KEY `ix_budgets_fiscal_year_id` (`fiscal_year_id`),
  KEY `ix_budgets_gl_account_id` (`gl_account_id`),
  KEY `ix_budgets_cost_center_id` (`cost_center_id`),
  UNIQUE KEY `uq_budgets_fiscal_year_id_gl_account_id_cost_center_id` (`fiscal_year_id`, `gl_account_id`, `cost_center_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Budget per account/cost centre with alert threshold.';

CREATE TABLE `bank_statement_lines` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `bank_account_id` CHAR(26) NOT NULL,
  `txn_date` DATE NOT NULL,
  `description` VARCHAR(255) NULL,
  `reference` VARCHAR(120) NULL,
  `debit` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `credit` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `balance` DECIMAL(14,2) NULL,
  `matched_type` VARCHAR(20) NULL,
  `matched_id` CHAR(26) NULL,
  `matched_at` DATETIME NULL,
  `import_batch` VARCHAR(40) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_bank_statement_lines_school_id` (`school_id`),
  KEY `ix_bank_statement_lines_bank_account_id` (`bank_account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Imported statement lines with auto-match.';

CREATE TABLE `fixed_assets_ledger` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `asset_id` CHAR(26) NOT NULL,
  `fiscal_year_id` CHAR(26) NOT NULL,
  `method` VARCHAR(40) NOT NULL DEFAULT 'straight_line',
  `rate_pct` DECIMAL(5,2) NOT NULL,
  `opening_value` DECIMAL(14,2) NOT NULL,
  `depreciation` DECIMAL(14,2) NOT NULL,
  `closing_value` DECIMAL(14,2) NOT NULL,
  `journal_entry_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_fixed_assets_ledger_school_id` (`school_id`),
  KEY `ix_fixed_assets_ledger_fiscal_year_id` (`fiscal_year_id`),
  KEY `ix_fixed_assets_ledger_journal_entry_id` (`journal_entry_id`),
  UNIQUE KEY `uq_fixed_assets_ledger_asset_id_fiscal_year_id` (`asset_id`, `fiscal_year_id`),
  CHECK (`method` IN ('straight_line', 'reducing'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Depreciation schedule per asset (straight-line / reducing).';

CREATE TABLE `tax_rates` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(60) NOT NULL,
  `rate_pct` DECIMAL(5,2) NOT NULL,
  `kind` VARCHAR(40) NOT NULL DEFAULT 'vat',
  `gl_account_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_tax_rates_school_id` (`school_id`),
  KEY `ix_tax_rates_gl_account_id` (`gl_account_id`),
  CHECK (`kind` IN ('vat', 'ait', 'other'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='VAT/AIT rates.';

CREATE TABLE `financial_statements` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `fiscal_year_id` CHAR(26) NOT NULL,
  `kind` VARCHAR(40) NOT NULL,
  `period_start` DATE NOT NULL,
  `period_end` DATE NOT NULL,
  `data` JSON NULL,
  `file_id` CHAR(26) NULL,
  `generated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_financial_statements_school_id` (`school_id`),
  KEY `ix_financial_statements_fiscal_year_id` (`fiscal_year_id`),
  KEY `ix_financial_statements_file_id` (`file_id`),
  CHECK (`kind` IN ('income_statement', 'balance_sheet', 'cash_flow', 'trial_balance', 'receivables_ageing'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Generated statements (income statement, balance sheet, cash flow) per period.';


-- ============ Student wallet & POS · canteen, shop ============
CREATE TABLE `wallets` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NULL,
  `staff_id` CHAR(26) NULL,
  `balance` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `daily_limit` DECIMAL(14,2) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_wallets_school_id` (`school_id`),
  UNIQUE KEY `uq_wallets_student_id` (`student_id`),
  UNIQUE KEY `uq_wallets_staff_id` (`staff_id`),
  CHECK (`status` IN ('active', 'frozen', 'closed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='One wallet per student (or staff).';

CREATE TABLE `wallet_transactions` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `wallet_id` CHAR(26) NOT NULL,
  `kind` VARCHAR(40) NOT NULL,
  `amount` DECIMAL(14,2) NOT NULL,
  `balance_after` DECIMAL(14,2) NOT NULL,
  `source_type` VARCHAR(40) NULL,
  `source_id` CHAR(26) NULL,
  `payment_id` CHAR(26) NULL,
  `description` VARCHAR(200) NULL,
  `created_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_wallet_transactions_school_id` (`school_id`),
  KEY `ix_wallet_transactions_wallet_id` (`wallet_id`),
  KEY `ix_wallet_transactions_payment_id` (`payment_id`),
  KEY `ix_wallet_transactions_created_by` (`created_by`),
  KEY `ix_wallet_transactions_wallet_id_created_at` (`wallet_id`, `created_at`),
  CHECK (`kind` IN ('topup', 'spend', 'refund', 'adjustment', 'transfer'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Top-ups, spends, refunds; append-only.';

CREATE TABLE `pos_outlets` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(80) NOT NULL,
  `kind` VARCHAR(40) NOT NULL,
  `campus_id` CHAR(26) NULL,
  `income_gl_account_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_pos_outlets_school_id` (`school_id`),
  KEY `ix_pos_outlets_campus_id` (`campus_id`),
  KEY `ix_pos_outlets_income_gl_account_id` (`income_gl_account_id`),
  CHECK (`kind` IN ('canteen', 'bookshop', 'uniform', 'stationery', 'other')),
  CHECK (`status` IN ('active', 'inactive'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Canteen, bookshop, uniform shop.';

CREATE TABLE `pos_products` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `outlet_id` CHAR(26) NOT NULL,
  `name` VARCHAR(160) NOT NULL,
  `sku` VARCHAR(40) NULL,
  `price` DECIMAL(14,2) NOT NULL,
  `tax_rate_id` CHAR(26) NULL,
  `inventory_item_id` CHAR(26) NULL,
  `image_file_id` CHAR(26) NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `category` VARCHAR(60) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_pos_products_school_id` (`school_id`),
  KEY `ix_pos_products_outlet_id` (`outlet_id`),
  KEY `ix_pos_products_tax_rate_id` (`tax_rate_id`),
  KEY `ix_pos_products_image_file_id` (`image_file_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Sellable products with price and stock link.';

CREATE TABLE `pos_sales` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `outlet_id` CHAR(26) NOT NULL,
  `sale_no` VARCHAR(30) NOT NULL,
  `student_id` CHAR(26) NULL,
  `wallet_id` CHAR(26) NULL,
  `cashier_id` CHAR(26) NULL,
  `subtotal` DECIMAL(14,2) NOT NULL,
  `tax` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `total` DECIMAL(14,2) NOT NULL,
  `paid_by` VARCHAR(40) NOT NULL,
  `payment_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'completed',
  `journal_entry_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_pos_sales_school_id` (`school_id`),
  KEY `ix_pos_sales_outlet_id` (`outlet_id`),
  KEY `ix_pos_sales_student_id` (`student_id`),
  KEY `ix_pos_sales_wallet_id` (`wallet_id`),
  KEY `ix_pos_sales_cashier_id` (`cashier_id`),
  KEY `ix_pos_sales_payment_id` (`payment_id`),
  KEY `ix_pos_sales_journal_entry_id` (`journal_entry_id`),
  UNIQUE KEY `uq_pos_sales_school_id_sale_no` (`school_id`, `sale_no`),
  CHECK (`paid_by` IN ('wallet', 'cash', 'bkash', 'card', 'invoice')),
  CHECK (`status` IN ('completed', 'refunded', 'void'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='A sale (wallet, cash or gateway).';

CREATE TABLE `pos_sale_items` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `sale_id` CHAR(26) NOT NULL,
  `product_id` CHAR(26) NOT NULL,
  `quantity` DECIMAL(8,2) NOT NULL DEFAULT 1,
  `unit_price` DECIMAL(14,2) NOT NULL,
  `amount` DECIMAL(14,2) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_pos_sale_items_school_id` (`school_id`),
  KEY `ix_pos_sale_items_sale_id` (`sale_id`),
  KEY `ix_pos_sale_items_product_id` (`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Lines.';

CREATE TABLE `shop_orders` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `order_no` VARCHAR(30) NOT NULL,
  `student_id` CHAR(26) NOT NULL,
  `outlet_id` CHAR(26) NOT NULL,
  `items` JSON NULL,
  `total` DECIMAL(14,2) NOT NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'placed',
  `invoice_id` CHAR(26) NULL,
  `notes` VARCHAR(255) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_shop_orders_school_id` (`school_id`),
  KEY `ix_shop_orders_student_id` (`student_id`),
  KEY `ix_shop_orders_outlet_id` (`outlet_id`),
  KEY `ix_shop_orders_invoice_id` (`invoice_id`),
  UNIQUE KEY `uq_shop_orders_school_id_order_no` (`school_id`, `order_no`),
  CHECK (`status` IN ('placed', 'paid', 'ready', 'delivered', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Guardian orders (uniform, books) from the app with delivery/pickup.';


-- ============ HR & payroll ============
CREATE TABLE `job_postings` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `title` VARCHAR(160) NOT NULL,
  `department_id` CHAR(26) NULL,
  `designation_id` CHAR(26) NULL,
  `description` LONGTEXT NULL,
  `vacancies` SMALLINT NOT NULL DEFAULT 1,
  `salary_range` VARCHAR(80) NULL,
  `closes_at` DATE NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'draft',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_job_postings_school_id` (`school_id`),
  KEY `ix_job_postings_department_id` (`department_id`),
  KEY `ix_job_postings_designation_id` (`designation_id`),
  CHECK (`status` IN ('draft', 'open', 'closed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Vacancies published on the website.';

CREATE TABLE `job_applicants` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `posting_id` CHAR(26) NOT NULL,
  `full_name` VARCHAR(160) NOT NULL,
  `phone` VARCHAR(20) NOT NULL,
  `email` VARCHAR(160) NULL,
  `cv_file_id` CHAR(26) NULL,
  `score` DECIMAL(5,2) NULL,
  `stage` VARCHAR(40) NOT NULL DEFAULT 'applied',
  `interview_at` DATETIME NULL,
  `notes` TEXT NULL,
  `staff_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_job_applicants_school_id` (`school_id`),
  KEY `ix_job_applicants_posting_id` (`posting_id`),
  KEY `ix_job_applicants_cv_file_id` (`cv_file_id`),
  KEY `ix_job_applicants_staff_id` (`staff_id`),
  CHECK (`stage` IN ('applied', 'shortlisted', 'interview', 'offered', 'hired', 'rejected'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Applicants with CV and interview pipeline.';

CREATE TABLE `onboarding_checklists` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `staff_id` CHAR(26) NOT NULL,
  `items` JSON NULL,
  `completed_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_onboarding_checklists_school_id` (`school_id`),
  KEY `ix_onboarding_checklists_staff_id` (`staff_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Per new staff: tasks like ID card, biometric enrol, bank details.';

CREATE TABLE `staff_contracts` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `staff_id` CHAR(26) NOT NULL,
  `contract_type` VARCHAR(40) NOT NULL,
  `start_date` DATE NOT NULL,
  `end_date` DATE NULL,
  `file_id` CHAR(26) NULL,
  `notes` TEXT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_staff_contracts_school_id` (`school_id`),
  KEY `ix_staff_contracts_staff_id` (`staff_id`),
  KEY `ix_staff_contracts_file_id` (`file_id`),
  CHECK (`contract_type` IN ('permanent', 'contract', 'part_time', 'intern', 'volunteer', 'mpo'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Contract periods with expiry alerts.';

CREATE TABLE `work_shifts` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(60) NOT NULL,
  `start_time` TIME NOT NULL,
  `end_time` TIME NOT NULL,
  `days` JSON NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_work_shifts_school_id` (`school_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Staff work shifts / rosters.';

CREATE TABLE `staff_shift_assignments` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `staff_id` CHAR(26) NOT NULL,
  `shift_id` CHAR(26) NOT NULL,
  `from_date` DATE NOT NULL,
  `to_date` DATE NULL,
  PRIMARY KEY (`id`),
  KEY `ix_staff_shift_assignments_school_id` (`school_id`),
  KEY `ix_staff_shift_assignments_staff_id` (`staff_id`),
  KEY `ix_staff_shift_assignments_shift_id` (`shift_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Who is on which shift when.';

CREATE TABLE `salary_components` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(80) NOT NULL,
  `code` VARCHAR(20) NOT NULL,
  `component_type` VARCHAR(40) NOT NULL,
  `calc_type` VARCHAR(40) NOT NULL DEFAULT 'fixed',
  `default_value` DECIMAL(14,2) NULL,
  `formula` VARCHAR(255) NULL,
  `is_taxable` TINYINT(1) NOT NULL DEFAULT 1,
  `is_statutory` TINYINT(1) NOT NULL DEFAULT 0,
  `gl_account_id` CHAR(26) NULL,
  `sort_order` SMALLINT NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_salary_components_school_id` (`school_id`),
  KEY `ix_salary_components_gl_account_id` (`gl_account_id`),
  UNIQUE KEY `uq_salary_components_school_id_code` (`school_id`, `code`),
  CHECK (`component_type` IN ('earning', 'deduction', 'employer_contribution')),
  CHECK (`calc_type` IN ('fixed', 'percent_of_basic', 'percent_of_gross', 'formula', 'attendance_based', 'slab'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Earning/deduction/employer components with calculation type and formula.';

CREATE TABLE `salary_structures` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `staff_id` CHAR(26) NOT NULL,
  `effective_from` DATE NOT NULL,
  `effective_to` DATE NULL,
  `basic` DECIMAL(14,2) NOT NULL,
  `pay_frequency` VARCHAR(40) NOT NULL DEFAULT 'monthly',
  `mpo_portion` DECIMAL(14,2) NOT NULL DEFAULT 0 COMMENT 'part paid by government (MPO)',
  `bank_account` JSON NULL,
  `approved_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_salary_structures_school_id` (`school_id`),
  KEY `ix_salary_structures_staff_id` (`staff_id`),
  KEY `ix_salary_structures_approved_by` (`approved_by`),
  KEY `ix_salary_structures_staff_id_effective_from` (`staff_id`, `effective_from`),
  CHECK (`pay_frequency` IN ('monthly', 'weekly'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Per staff with effective range (no overlap, app-enforced).';

CREATE TABLE `salary_structure_items` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `structure_id` CHAR(26) NOT NULL,
  `component_id` CHAR(26) NOT NULL,
  `value` DECIMAL(14,2) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_salary_structure_items_school_id` (`school_id`),
  KEY `ix_salary_structure_items_structure_id` (`structure_id`),
  KEY `ix_salary_structure_items_component_id` (`component_id`),
  UNIQUE KEY `uq_salary_structure_items_structure_id_component_id` (`structure_id`, `component_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Component values.';

CREATE TABLE `tax_slabs` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `fiscal_year_id` CHAR(26) NOT NULL,
  `category` VARCHAR(40) NOT NULL DEFAULT 'general',
  `slabs` JSON NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_tax_slabs_school_id` (`school_id`),
  KEY `ix_tax_slabs_fiscal_year_id` (`fiscal_year_id`),
  CHECK (`category` IN ('general', 'female_senior', 'disabled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Income tax slabs (NBR) per fiscal year and taxpayer category.';

CREATE TABLE `staff_loans` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `staff_id` CHAR(26) NOT NULL,
  `loan_type` VARCHAR(40) NOT NULL,
  `principal` DECIMAL(14,2) NOT NULL,
  `monthly_deduction` DECIMAL(14,2) NOT NULL,
  `balance` DECIMAL(14,2) NOT NULL,
  `starts_from` DATE NOT NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'pending',
  `approved_by` CHAR(26) NULL,
  `journal_entry_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_staff_loans_school_id` (`school_id`),
  KEY `ix_staff_loans_staff_id` (`staff_id`),
  KEY `ix_staff_loans_approved_by` (`approved_by`),
  KEY `ix_staff_loans_journal_entry_id` (`journal_entry_id`),
  CHECK (`loan_type` IN ('advance', 'loan', 'pf_loan')),
  CHECK (`status` IN ('pending', 'approved', 'rejected', 'active', 'closed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Loans/advances with monthly deduction.';

CREATE TABLE `provident_fund_accounts` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `staff_id` CHAR(26) NOT NULL,
  `employee_total` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `employer_total` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `interest_total` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `withdrawn_total` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_provident_fund_accounts_school_id` (`school_id`),
  UNIQUE KEY `uq_provident_fund_accounts_staff_id` (`staff_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PF balance per staff (employee + employer + interest).';

CREATE TABLE `payroll_runs` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `period_month` DATE NOT NULL,
  `campus_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'draft',
  `staff_count` INT NOT NULL DEFAULT 0,
  `total_gross` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `total_deductions` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `total_net` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `total_mpo` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `calculated_at` DATETIME NULL,
  `approved_by` CHAR(26) NULL,
  `approved_at` DATETIME NULL,
  `paid_from_id` CHAR(26) NULL,
  `paid_at` DATETIME NULL,
  `bank_file_id` CHAR(26) NULL,
  `journal_entry_id` CHAR(26) NULL,
  `created_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_payroll_runs_school_id` (`school_id`),
  KEY `ix_payroll_runs_campus_id` (`campus_id`),
  KEY `ix_payroll_runs_approved_by` (`approved_by`),
  KEY `ix_payroll_runs_paid_from_id` (`paid_from_id`),
  KEY `ix_payroll_runs_bank_file_id` (`bank_file_id`),
  KEY `ix_payroll_runs_journal_entry_id` (`journal_entry_id`),
  KEY `ix_payroll_runs_created_by` (`created_by`),
  UNIQUE KEY `uq_payroll_runs_school_id_period_month_campus_id` (`school_id`, `period_month`, `campus_id`),
  CHECK (`status` IN ('draft', 'calculated', 'approved', 'paid', 'locked'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Monthly run with totals and approval.';

CREATE TABLE `payslips` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `payroll_run_id` CHAR(26) NOT NULL,
  `staff_id` CHAR(26) NOT NULL,
  `structure_id` CHAR(26) NULL,
  `working_days` DECIMAL(4,1) NOT NULL,
  `present_days` DECIMAL(4,1) NOT NULL,
  `paid_leave_days` DECIMAL(4,1) NOT NULL DEFAULT 0,
  `lop_days` DECIMAL(4,1) NOT NULL DEFAULT 0,
  `late_count` SMALLINT NOT NULL DEFAULT 0,
  `overtime_hours` DECIMAL(5,1) NOT NULL DEFAULT 0,
  `gross` DECIMAL(14,2) NOT NULL,
  `total_deductions` DECIMAL(14,2) NOT NULL,
  `tax` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `net_pay` DECIMAL(14,2) NOT NULL,
  `breakdown` JSON NULL,
  `payslip_file_id` CHAR(26) NULL,
  `paid_at` DATETIME NULL,
  `payment_ref` VARCHAR(120) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'draft',
  `hold_reason` VARCHAR(160) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_payslips_school_id` (`school_id`),
  KEY `ix_payslips_payroll_run_id` (`payroll_run_id`),
  KEY `ix_payslips_staff_id` (`staff_id`),
  KEY `ix_payslips_structure_id` (`structure_id`),
  KEY `ix_payslips_payslip_file_id` (`payslip_file_id`),
  UNIQUE KEY `uq_payslips_payroll_run_id_staff_id` (`payroll_run_id`, `staff_id`),
  CHECK (`status` IN ('draft', 'approved', 'paid', 'held'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Frozen payslip per staff per run.';

CREATE TABLE `appraisal_cycles` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `academic_year_id` CHAR(26) NOT NULL,
  `name` VARCHAR(120) NOT NULL,
  `criteria` JSON NULL,
  `opens_at` DATE NOT NULL,
  `closes_at` DATE NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_appraisal_cycles_school_id` (`school_id`),
  KEY `ix_appraisal_cycles_academic_year_id` (`academic_year_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Cycle with weighted criteria.';

CREATE TABLE `staff_appraisals` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `cycle_id` CHAR(26) NOT NULL,
  `staff_id` CHAR(26) NOT NULL,
  `reviewer_id` CHAR(26) NOT NULL,
  `self_scores` JSON NULL,
  `reviewer_scores` JSON NULL,
  `auto_metrics` JSON NULL,
  `overall_score` DECIMAL(5,2) NULL,
  `comments` TEXT NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'pending',
  `finalised_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_staff_appraisals_school_id` (`school_id`),
  KEY `ix_staff_appraisals_cycle_id` (`cycle_id`),
  KEY `ix_staff_appraisals_staff_id` (`staff_id`),
  KEY `ix_staff_appraisals_reviewer_id` (`reviewer_id`),
  UNIQUE KEY `uq_staff_appraisals_cycle_id_staff_id` (`cycle_id`, `staff_id`),
  CHECK (`status` IN ('pending', 'self_done', 'reviewed', 'finalised'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Self + reviewer scores, auto metrics.';

CREATE TABLE `staff_trainings` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `staff_id` CHAR(26) NOT NULL,
  `title` VARCHAR(160) NOT NULL,
  `provider` VARCHAR(160) NULL,
  `start_date` DATE NULL,
  `end_date` DATE NULL,
  `hours` DECIMAL(5,1) NULL,
  `certificate_file_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_staff_trainings_school_id` (`school_id`),
  KEY `ix_staff_trainings_staff_id` (`staff_id`),
  KEY `ix_staff_trainings_certificate_file_id` (`certificate_file_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Training records and certificates.';

CREATE TABLE `staff_exits` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `staff_id` CHAR(26) NOT NULL,
  `exit_type` VARCHAR(40) NOT NULL,
  `notice_date` DATE NULL,
  `last_working_day` DATE NOT NULL,
  `clearance` JSON NULL,
  `settlement` JSON NULL,
  `settlement_journal_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'initiated',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_staff_exits_school_id` (`school_id`),
  UNIQUE KEY `uq_staff_exits_staff_id` (`staff_id`),
  KEY `ix_staff_exits_settlement_journal_id` (`settlement_journal_id`),
  CHECK (`exit_type` IN ('resignation', 'termination', 'retirement', 'end_of_contract', 'death')),
  CHECK (`status` IN ('initiated', 'cleared', 'settled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Resignation/termination with clearance and final settlement.';


-- ============ Scholarships, donations & fundraising ============
CREATE TABLE `scholarship_funds` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(160) NOT NULL,
  `kind` VARCHAR(40) NOT NULL,
  `balance` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `gl_account_id` CHAR(26) NULL,
  `rules` JSON NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_scholarship_funds_school_id` (`school_id`),
  KEY `ix_scholarship_funds_gl_account_id` (`gl_account_id`),
  CHECK (`kind` IN ('internal', 'government_stipend', 'donor', 'zakat', 'alumni')),
  CHECK (`status` IN ('active', 'closed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='A fund with balance and rules.';

CREATE TABLE `scholarship_awards` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `fund_id` CHAR(26) NOT NULL,
  `student_id` CHAR(26) NOT NULL,
  `academic_year_id` CHAR(26) NOT NULL,
  `amount` DECIMAL(14,2) NOT NULL,
  `frequency` VARCHAR(40) NOT NULL DEFAULT 'yearly',
  `discount_id` CHAR(26) NULL,
  `sponsor_donor_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'proposed',
  `approved_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_scholarship_awards_school_id` (`school_id`),
  KEY `ix_scholarship_awards_fund_id` (`fund_id`),
  KEY `ix_scholarship_awards_student_id` (`student_id`),
  KEY `ix_scholarship_awards_academic_year_id` (`academic_year_id`),
  KEY `ix_scholarship_awards_discount_id` (`discount_id`),
  KEY `ix_scholarship_awards_approved_by` (`approved_by`),
  CHECK (`frequency` IN ('monthly', 'yearly', 'one_time')),
  CHECK (`status` IN ('proposed', 'approved', 'active', 'ended'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Award to a student for a period; links to a discount.';

CREATE TABLE `donors` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(160) NOT NULL,
  `kind` VARCHAR(40) NOT NULL DEFAULT 'individual',
  `phone` VARCHAR(30) NULL,
  `email` VARCHAR(160) NULL,
  `address` JSON NULL,
  `alumni_id` CHAR(26) NULL,
  `total_donated` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `is_anonymous` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_donors_school_id` (`school_id`),
  CHECK (`kind` IN ('individual', 'organisation', 'alumni'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Individuals/organisations who give.';

CREATE TABLE `fundraising_campaigns` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `title` VARCHAR(200) NOT NULL,
  `slug` VARCHAR(120) NOT NULL,
  `goal_amount` DECIMAL(14,2) NOT NULL,
  `raised_amount` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `starts_at` DATE NULL,
  `ends_at` DATE NULL,
  `description` LONGTEXT NULL,
  `cover_file_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'draft',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_fundraising_campaigns_school_id` (`school_id`),
  KEY `ix_fundraising_campaigns_cover_file_id` (`cover_file_id`),
  UNIQUE KEY `uq_fundraising_campaigns_school_id_slug` (`school_id`, `slug`),
  CHECK (`status` IN ('draft', 'live', 'closed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Campaign with goal and public page.';

CREATE TABLE `donations` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `donor_id` CHAR(26) NOT NULL,
  `campaign_id` CHAR(26) NULL,
  `fund_id` CHAR(26) NULL,
  `amount` DECIMAL(14,2) NOT NULL,
  `kind` VARCHAR(40) NOT NULL DEFAULT 'received',
  `method` VARCHAR(20) NULL,
  `reference` VARCHAR(120) NULL,
  `received_at` DATETIME NULL,
  `receipt_doc_id` CHAR(26) NULL,
  `journal_entry_id` CHAR(26) NULL,
  `message` TEXT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_donations_school_id` (`school_id`),
  KEY `ix_donations_donor_id` (`donor_id`),
  KEY `ix_donations_campaign_id` (`campaign_id`),
  KEY `ix_donations_fund_id` (`fund_id`),
  KEY `ix_donations_journal_entry_id` (`journal_entry_id`),
  CHECK (`kind` IN ('pledge', 'received'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Donation/pledge with receipt and journal.';


-- ============ Transport & GPS ============
CREATE TABLE `vehicles` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `campus_id` CHAR(26) NULL,
  `registration_no` VARCHAR(30) NOT NULL,
  `vehicle_type` VARCHAR(40) NOT NULL DEFAULT 'bus',
  `make_model` VARCHAR(80) NULL,
  `capacity` SMALLINT NOT NULL,
  `driver_id` CHAR(26) NULL,
  `helper_id` CHAR(26) NULL,
  `gps_device_id` VARCHAR(60) NULL,
  `insurance_expiry` DATE NULL,
  `fitness_expiry` DATE NULL,
  `tax_token_expiry` DATE NULL,
  `route_permit_expiry` DATE NULL,
  `odometer_km` INT NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_vehicles_school_id` (`school_id`),
  KEY `ix_vehicles_campus_id` (`campus_id`),
  KEY `ix_vehicles_driver_id` (`driver_id`),
  KEY `ix_vehicles_helper_id` (`helper_id`),
  UNIQUE KEY `uq_vehicles_school_id_registration_no` (`school_id`, `registration_no`),
  CHECK (`vehicle_type` IN ('bus', 'microbus', 'van', 'car')),
  CHECK (`status` IN ('active', 'maintenance', 'inactive'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Fleet with compliance dates.';

CREATE TABLE `transport_routes` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(120) NOT NULL,
  `vehicle_id` CHAR(26) NULL,
  `start_point` VARCHAR(120) NULL,
  `end_point` VARCHAR(120) NULL,
  `distance_km` DECIMAL(6,2) NULL,
  `monthly_fee` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `fee_head_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_transport_routes_school_id` (`school_id`),
  KEY `ix_transport_routes_vehicle_id` (`vehicle_id`),
  KEY `ix_transport_routes_fee_head_id` (`fee_head_id`),
  UNIQUE KEY `uq_transport_routes_school_id_name` (`school_id`, `name`),
  CHECK (`status` IN ('active', 'inactive'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Route with default fee.';

CREATE TABLE `route_stops` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `route_id` CHAR(26) NOT NULL,
  `name` VARCHAR(120) NOT NULL,
  `sequence` SMALLINT NOT NULL,
  `latitude` DECIMAL(9,6) NULL,
  `longitude` DECIMAL(9,6) NULL,
  `geofence_m` SMALLINT NOT NULL DEFAULT 300,
  `pickup_time` TIME NULL,
  `drop_time` TIME NULL,
  `fee_override` DECIMAL(14,2) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_route_stops_school_id` (`school_id`),
  KEY `ix_route_stops_route_id` (`route_id`),
  UNIQUE KEY `uq_route_stops_route_id_sequence` (`route_id`, `sequence`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Ordered stops with geofence and times.';

CREATE TABLE `student_transport` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `academic_year_id` CHAR(26) NOT NULL,
  `route_id` CHAR(26) NOT NULL,
  `stop_id` CHAR(26) NOT NULL,
  `trip_type` VARCHAR(40) NOT NULL DEFAULT 'both',
  `start_date` DATE NOT NULL,
  `end_date` DATE NULL,
  `monthly_fee` DECIMAL(14,2) NOT NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_student_transport_school_id` (`school_id`),
  KEY `ix_student_transport_student_id` (`student_id`),
  KEY `ix_student_transport_academic_year_id` (`academic_year_id`),
  KEY `ix_student_transport_route_id` (`route_id`),
  KEY `ix_student_transport_stop_id` (`stop_id`),
  UNIQUE KEY `uq_student_transport_student_id_academic_year_id` (`student_id`, `academic_year_id`),
  CHECK (`trip_type` IN ('pickup', 'drop', 'both')),
  CHECK (`status` IN ('active', 'inactive'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Student assignment to route/stop with fee snapshot.';

CREATE TABLE `vehicle_trips` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `vehicle_id` CHAR(26) NOT NULL,
  `route_id` CHAR(26) NOT NULL,
  `trip_date` DATE NOT NULL,
  `trip_type` VARCHAR(40) NOT NULL,
  `driver_id` CHAR(26) NULL,
  `helper_id` CHAR(26) NULL,
  `scheduled_start` TIME NULL,
  `started_at` DATETIME NULL,
  `ended_at` DATETIME NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'scheduled',
  `delay_alert_sent_at` DATETIME NULL,
  `checklist` JSON NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_vehicle_trips_school_id` (`school_id`),
  KEY `ix_vehicle_trips_vehicle_id` (`vehicle_id`),
  KEY `ix_vehicle_trips_route_id` (`route_id`),
  KEY `ix_vehicle_trips_driver_id` (`driver_id`),
  KEY `ix_vehicle_trips_helper_id` (`helper_id`),
  UNIQUE KEY `uq_vehicle_trips_vehicle_id_trip_date_trip_type` (`vehicle_id`, `trip_date`, `trip_type`),
  CHECK (`trip_type` IN ('pickup', 'drop')),
  CHECK (`status` IN ('scheduled', 'running', 'completed', 'cancelled', 'delayed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Daily trip instance with status and delay stamp.';

CREATE TABLE `vehicle_gps_logs` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `vehicle_id` CHAR(26) NOT NULL,
  `trip_id` CHAR(26) NULL,
  `latitude` DECIMAL(9,6) NOT NULL,
  `longitude` DECIMAL(9,6) NOT NULL,
  `speed_kmh` DECIMAL(5,1) NULL,
  `heading` SMALLINT NULL,
  `recorded_at` DATETIME NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_vehicle_gps_logs_school_id` (`school_id`),
  KEY `ix_vehicle_gps_logs_vehicle_id` (`vehicle_id`),
  KEY `ix_vehicle_gps_logs_trip_id` (`trip_id`),
  KEY `ix_vehicle_gps_logs_vehicle_id_recorded_at` (`vehicle_id`, `recorded_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Telemetry (prune/rotate monthly).';

CREATE TABLE `transport_boardings` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `trip_id` CHAR(26) NOT NULL,
  `student_id` CHAR(26) NOT NULL,
  `stop_id` CHAR(26) NULL,
  `boarded_at` DATETIME NULL,
  `alighted_at` DATETIME NULL,
  `source` VARCHAR(40) NOT NULL DEFAULT 'rfid',
  `guardian_notified_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_transport_boardings_school_id` (`school_id`),
  KEY `ix_transport_boardings_trip_id` (`trip_id`),
  KEY `ix_transport_boardings_student_id` (`student_id`),
  KEY `ix_transport_boardings_stop_id` (`stop_id`),
  UNIQUE KEY `uq_transport_boardings_trip_id_student_id` (`trip_id`, `student_id`),
  CHECK (`source` IN ('rfid', 'helper_app', 'manual'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Boarded/alighted per student per trip.';

CREATE TABLE `stop_alerts` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `trip_id` CHAR(26) NOT NULL,
  `stop_id` CHAR(26) NOT NULL,
  `alert_type` VARCHAR(40) NOT NULL,
  `sent_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_stop_alerts_school_id` (`school_id`),
  KEY `ix_stop_alerts_trip_id` (`trip_id`),
  KEY `ix_stop_alerts_stop_id` (`stop_id`),
  UNIQUE KEY `uq_stop_alerts_trip_id_stop_id_alert_type` (`trip_id`, `stop_id`, `alert_type`),
  CHECK (`alert_type` IN ('approaching', 'arrived', 'departed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Approaching/arrived/departed alerts sent per trip-stop.';

CREATE TABLE `vehicle_maintenance` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `vehicle_id` CHAR(26) NOT NULL,
  `service_type` VARCHAR(60) NOT NULL,
  `service_date` DATE NOT NULL,
  `odometer_km` INT NULL,
  `cost` DECIMAL(14,2) NULL,
  `vendor_id` CHAR(26) NULL,
  `expense_id` CHAR(26) NULL,
  `next_due_date` DATE NULL,
  `next_due_km` INT NULL,
  `notes` TEXT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_vehicle_maintenance_school_id` (`school_id`),
  KEY `ix_vehicle_maintenance_vehicle_id` (`vehicle_id`),
  KEY `ix_vehicle_maintenance_vendor_id` (`vendor_id`),
  KEY `ix_vehicle_maintenance_expense_id` (`expense_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Service history with next due.';

CREATE TABLE `fuel_logs` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `vehicle_id` CHAR(26) NOT NULL,
  `filled_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `litres` DECIMAL(7,2) NOT NULL,
  `cost` DECIMAL(14,2) NOT NULL,
  `odometer_km` INT NULL,
  `expense_id` CHAR(26) NULL,
  PRIMARY KEY (`id`),
  KEY `ix_fuel_logs_school_id` (`school_id`),
  KEY `ix_fuel_logs_vehicle_id` (`vehicle_id`),
  KEY `ix_fuel_logs_expense_id` (`expense_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Fuel fills.';

CREATE TABLE `driver_incidents` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `vehicle_id` CHAR(26) NOT NULL,
  `driver_id` CHAR(26) NULL,
  `kind` VARCHAR(40) NOT NULL,
  `occurred_at` DATETIME NOT NULL,
  `details` TEXT NULL,
  `severity` VARCHAR(40) NOT NULL DEFAULT 'low',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_driver_incidents_school_id` (`school_id`),
  KEY `ix_driver_incidents_vehicle_id` (`vehicle_id`),
  KEY `ix_driver_incidents_driver_id` (`driver_id`),
  CHECK (`kind` IN ('overspeed', 'accident', 'complaint', 'breakdown', 'other')),
  CHECK (`severity` IN ('low', 'medium', 'high'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Accidents, over-speed, complaints per driver.';


-- ============ Hostel ============
CREATE TABLE `hostels` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `campus_id` CHAR(26) NULL,
  `name` VARCHAR(120) NOT NULL,
  `hostel_type` VARCHAR(40) NOT NULL,
  `warden_id` CHAR(26) NULL,
  `address` JSON NULL,
  `curfew_time` TIME NULL,
  `fee_head_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_hostels_school_id` (`school_id`),
  KEY `ix_hostels_campus_id` (`campus_id`),
  KEY `ix_hostels_warden_id` (`warden_id`),
  KEY `ix_hostels_fee_head_id` (`fee_head_id`),
  UNIQUE KEY `uq_hostels_school_id_name` (`school_id`, `name`),
  CHECK (`hostel_type` IN ('boys', 'girls', 'staff')),
  CHECK (`status` IN ('active', 'inactive'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Building with warden, curfew and fee head.';

CREATE TABLE `hostel_rooms` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `hostel_id` CHAR(26) NOT NULL,
  `room_no` VARCHAR(20) NOT NULL,
  `floor` VARCHAR(10) NULL,
  `room_type` VARCHAR(40) NOT NULL DEFAULT 'shared',
  `capacity` SMALLINT NOT NULL,
  `monthly_fee` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `amenities` JSON NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_hostel_rooms_school_id` (`school_id`),
  KEY `ix_hostel_rooms_hostel_id` (`hostel_id`),
  UNIQUE KEY `uq_hostel_rooms_hostel_id_room_no` (`hostel_id`, `room_no`),
  CHECK (`room_type` IN ('single', 'double', 'shared', 'dorm')),
  CHECK (`status` IN ('active', 'maintenance', 'inactive'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Rooms with capacity and fee.';

CREATE TABLE `hostel_beds` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `room_id` CHAR(26) NOT NULL,
  `bed_no` VARCHAR(10) NOT NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'vacant',
  PRIMARY KEY (`id`),
  KEY `ix_hostel_beds_school_id` (`school_id`),
  KEY `ix_hostel_beds_room_id` (`room_id`),
  UNIQUE KEY `uq_hostel_beds_room_id_bed_no` (`room_id`, `bed_no`),
  CHECK (`status` IN ('vacant', 'occupied', 'maintenance'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Individual beds.';

CREATE TABLE `hostel_allocations` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `bed_id` CHAR(26) NOT NULL,
  `academic_year_id` CHAR(26) NOT NULL,
  `from_date` DATE NOT NULL,
  `to_date` DATE NULL,
  `monthly_fee` DECIMAL(14,2) NOT NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_hostel_allocations_school_id` (`school_id`),
  KEY `ix_hostel_allocations_student_id` (`student_id`),
  KEY `ix_hostel_allocations_bed_id` (`bed_id`),
  KEY `ix_hostel_allocations_academic_year_id` (`academic_year_id`),
  KEY `ix_hostel_allocations_bed_id_from_date` (`bed_id`, `from_date`),
  CHECK (`status` IN ('active', 'ended'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Student on a bed for a period (no overlap, app-enforced).';

CREATE TABLE `hostel_outpasses` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `hostel_id` CHAR(26) NOT NULL,
  `leave_from` DATETIME NOT NULL,
  `expected_return` DATETIME NOT NULL,
  `actual_out_at` DATETIME NULL,
  `actual_return_at` DATETIME NULL,
  `reason` VARCHAR(200) NOT NULL,
  `destination` VARCHAR(160) NULL,
  `guardian_consent_at` DATETIME NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'pending',
  `approved_by` CHAR(26) NULL,
  `qr_code` VARCHAR(64) NULL,
  `late_alert_sent_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_hostel_outpasses_school_id` (`school_id`),
  KEY `ix_hostel_outpasses_student_id` (`student_id`),
  KEY `ix_hostel_outpasses_hostel_id` (`hostel_id`),
  KEY `ix_hostel_outpasses_approved_by` (`approved_by`),
  CHECK (`status` IN ('pending', 'approved', 'rejected', 'out', 'returned', 'late'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Leave from hostel with guardian consent, warden approval, QR, late-return alert.';

CREATE TABLE `hostel_visitors` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `hostel_id` CHAR(26) NOT NULL,
  `student_id` CHAR(26) NOT NULL,
  `visitor_name` VARCHAR(160) NOT NULL,
  `relation` VARCHAR(40) NULL,
  `phone` VARCHAR(20) NULL,
  `id_proof` VARCHAR(60) NULL,
  `in_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `out_at` DATETIME NULL,
  `approved_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_hostel_visitors_school_id` (`school_id`),
  KEY `ix_hostel_visitors_hostel_id` (`hostel_id`),
  KEY `ix_hostel_visitors_student_id` (`student_id`),
  KEY `ix_hostel_visitors_approved_by` (`approved_by`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Visitor log per resident.';

CREATE TABLE `hostel_attendance` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `hostel_id` CHAR(26) NOT NULL,
  `student_id` CHAR(26) NOT NULL,
  `on_date` DATE NOT NULL,
  `roll_call` VARCHAR(40) NOT NULL DEFAULT 'night',
  `status` VARCHAR(40) NOT NULL,
  `marked_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_hostel_attendance_school_id` (`school_id`),
  KEY `ix_hostel_attendance_hostel_id` (`hostel_id`),
  KEY `ix_hostel_attendance_student_id` (`student_id`),
  KEY `ix_hostel_attendance_marked_by` (`marked_by`),
  UNIQUE KEY `uq_hostel_attendance_student_id_on_date_roll_call` (`student_id`, `on_date`, `roll_call`),
  CHECK (`roll_call` IN ('morning', 'night')),
  CHECK (`status` IN ('present', 'absent', 'on_outpass', 'sick'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Morning/night roll call.';

CREATE TABLE `mess_menus` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `hostel_id` CHAR(26) NOT NULL,
  `day_of_week` SMALLINT NOT NULL,
  `meal` VARCHAR(40) NOT NULL,
  `items` VARCHAR(255) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_mess_menus_school_id` (`school_id`),
  KEY `ix_mess_menus_hostel_id` (`hostel_id`),
  UNIQUE KEY `uq_mess_menus_hostel_id_day_of_week_meal` (`hostel_id`, `day_of_week`, `meal`),
  CHECK (`meal` IN ('breakfast', 'lunch', 'snack', 'dinner'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Weekly menu.';

CREATE TABLE `meal_records` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `hostel_id` CHAR(26) NOT NULL,
  `student_id` CHAR(26) NOT NULL,
  `on_date` DATE NOT NULL,
  `meal` VARCHAR(40) NOT NULL,
  `taken` TINYINT(1) NOT NULL DEFAULT 1,
  `cost` DECIMAL(14,2) NULL,
  PRIMARY KEY (`id`),
  KEY `ix_meal_records_school_id` (`school_id`),
  KEY `ix_meal_records_hostel_id` (`hostel_id`),
  KEY `ix_meal_records_student_id` (`student_id`),
  UNIQUE KEY `uq_meal_records_student_id_on_date_meal` (`student_id`, `on_date`, `meal`),
  CHECK (`meal` IN ('breakfast', 'lunch', 'snack', 'dinner'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Per-meal attendance/billing (optional per-meal mess billing).';

CREATE TABLE `laundry_records` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `hostel_id` CHAR(26) NOT NULL,
  `student_id` CHAR(26) NOT NULL,
  `dropped_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `items` SMALLINT NOT NULL,
  `returned_at` DATETIME NULL,
  `charge` DECIMAL(14,2) NULL,
  PRIMARY KEY (`id`),
  KEY `ix_laundry_records_school_id` (`school_id`),
  KEY `ix_laundry_records_hostel_id` (`hostel_id`),
  KEY `ix_laundry_records_student_id` (`student_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Laundry drop/return tracking.';

CREATE TABLE `hostel_complaints` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `hostel_id` CHAR(26) NOT NULL,
  `student_id` CHAR(26) NULL,
  `category` VARCHAR(40) NOT NULL,
  `description` TEXT NOT NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'open',
  `resolved_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_hostel_complaints_school_id` (`school_id`),
  KEY `ix_hostel_complaints_hostel_id` (`hostel_id`),
  KEY `ix_hostel_complaints_student_id` (`student_id`),
  CHECK (`category` IN ('maintenance', 'food', 'safety', 'cleanliness', 'other')),
  CHECK (`status` IN ('open', 'in_progress', 'resolved'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Resident complaints.';


-- ============ Procurement, inventory & assets ============
CREATE TABLE `inventory_categories` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(80) NOT NULL,
  `is_asset` TINYINT(1) NOT NULL DEFAULT 0,
  `gl_account_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_inventory_categories_school_id` (`school_id`),
  KEY `ix_inventory_categories_gl_account_id` (`gl_account_id`),
  UNIQUE KEY `uq_inventory_categories_school_id_name` (`school_id`, `name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Categories; asset categories create fixed assets on receipt.';

CREATE TABLE `stores` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(80) NOT NULL,
  `campus_id` CHAR(26) NULL,
  `keeper_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_stores_school_id` (`school_id`),
  KEY `ix_stores_campus_id` (`campus_id`),
  KEY `ix_stores_keeper_id` (`keeper_id`),
  UNIQUE KEY `uq_stores_school_id_name` (`school_id`, `name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Stores/warehouses with keeper.';

CREATE TABLE `inventory_items` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `category_id` CHAR(26) NOT NULL,
  `sku` VARCHAR(40) NOT NULL,
  `name` VARCHAR(160) NOT NULL,
  `unit` VARCHAR(20) NOT NULL DEFAULT 'pcs',
  `reorder_level` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `reorder_qty` DECIMAL(12,2) NULL,
  `preferred_vendor_id` CHAR(26) NULL,
  `last_cost` DECIMAL(14,2) NULL,
  `barcode` VARCHAR(60) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_inventory_items_school_id` (`school_id`),
  KEY `ix_inventory_items_category_id` (`category_id`),
  KEY `ix_inventory_items_preferred_vendor_id` (`preferred_vendor_id`),
  UNIQUE KEY `uq_inventory_items_school_id_sku` (`school_id`, `sku`),
  CHECK (`status` IN ('active', 'inactive'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Item master with reorder rule.';

CREATE TABLE `stock_levels` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `item_id` CHAR(26) NOT NULL,
  `store_id` CHAR(26) NOT NULL,
  `quantity` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_stock_levels_school_id` (`school_id`),
  KEY `ix_stock_levels_item_id` (`item_id`),
  KEY `ix_stock_levels_store_id` (`store_id`),
  UNIQUE KEY `uq_stock_levels_item_id_store_id` (`item_id`, `store_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Current quantity per item per store (maintained by app on each movement).';

CREATE TABLE `requisitions` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `requested_by` CHAR(26) NOT NULL,
  `department_id` CHAR(26) NULL,
  `items` JSON NULL,
  `justification` TEXT NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'pending',
  `approval_request_id` CHAR(26) NULL,
  `approved_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_requisitions_school_id` (`school_id`),
  KEY `ix_requisitions_requested_by` (`requested_by`),
  KEY `ix_requisitions_department_id` (`department_id`),
  KEY `ix_requisitions_approved_by` (`approved_by`),
  CHECK (`status` IN ('pending', 'approved', 'rejected', 'ordered'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Purchase requests from departments.';

CREATE TABLE `quotations` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `requisition_id` CHAR(26) NULL,
  `vendor_id` CHAR(26) NOT NULL,
  `quoted_at` DATE NOT NULL,
  `valid_until` DATE NULL,
  `items` JSON NULL,
  `total` DECIMAL(14,2) NOT NULL,
  `file_id` CHAR(26) NULL,
  `is_selected` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_quotations_school_id` (`school_id`),
  KEY `ix_quotations_requisition_id` (`requisition_id`),
  KEY `ix_quotations_vendor_id` (`vendor_id`),
  KEY `ix_quotations_file_id` (`file_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Vendor quotations / tender bids for a requisition.';

CREATE TABLE `purchase_orders` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `po_no` VARCHAR(30) NOT NULL,
  `vendor_id` CHAR(26) NOT NULL,
  `store_id` CHAR(26) NOT NULL,
  `requisition_id` CHAR(26) NULL,
  `order_date` DATE NOT NULL,
  `expected_date` DATE NULL,
  `subtotal` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `tax_total` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `total` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `status` VARCHAR(40) NOT NULL DEFAULT 'draft',
  `is_auto` TINYINT(1) NOT NULL DEFAULT 0,
  `approval_request_id` CHAR(26) NULL,
  `approved_by` CHAR(26) NULL,
  `bill_id` CHAR(26) NULL,
  `created_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_purchase_orders_school_id` (`school_id`),
  KEY `ix_purchase_orders_vendor_id` (`vendor_id`),
  KEY `ix_purchase_orders_store_id` (`store_id`),
  KEY `ix_purchase_orders_requisition_id` (`requisition_id`),
  KEY `ix_purchase_orders_approved_by` (`approved_by`),
  KEY `ix_purchase_orders_bill_id` (`bill_id`),
  KEY `ix_purchase_orders_created_by` (`created_by`),
  UNIQUE KEY `uq_purchase_orders_school_id_po_no` (`school_id`, `po_no`),
  CHECK (`status` IN ('draft', 'pending_approval', 'approved', 'ordered', 'partially_received', 'received', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PO with approval, receipt and bill link.';

CREATE TABLE `purchase_order_items` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `po_id` CHAR(26) NOT NULL,
  `item_id` CHAR(26) NOT NULL,
  `quantity` DECIMAL(12,2) NOT NULL,
  `received_qty` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `unit_cost` DECIMAL(14,2) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_purchase_order_items_school_id` (`school_id`),
  KEY `ix_purchase_order_items_po_id` (`po_id`),
  KEY `ix_purchase_order_items_item_id` (`item_id`),
  UNIQUE KEY `uq_purchase_order_items_po_id_item_id` (`po_id`, `item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PO lines with received qty.';

CREATE TABLE `goods_receipts` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `po_id` CHAR(26) NOT NULL,
  `received_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `received_by` CHAR(26) NULL,
  `items` JSON NULL,
  `notes` VARCHAR(255) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_goods_receipts_school_id` (`school_id`),
  KEY `ix_goods_receipts_po_id` (`po_id`),
  KEY `ix_goods_receipts_received_by` (`received_by`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='GRN against a PO.';

CREATE TABLE `stock_movements` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `item_id` CHAR(26) NOT NULL,
  `store_id` CHAR(26) NOT NULL,
  `move_type` VARCHAR(40) NOT NULL,
  `quantity` DECIMAL(12,2) NOT NULL,
  `unit_cost` DECIMAL(14,2) NULL,
  `ref_type` VARCHAR(40) NULL,
  `ref_id` CHAR(26) NULL,
  `issued_to_staff_id` CHAR(26) NULL,
  `issued_to_room_id` CHAR(26) NULL,
  `note` VARCHAR(255) NULL,
  `created_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_stock_movements_school_id` (`school_id`),
  KEY `ix_stock_movements_item_id` (`item_id`),
  KEY `ix_stock_movements_store_id` (`store_id`),
  KEY `ix_stock_movements_issued_to_staff_id` (`issued_to_staff_id`),
  KEY `ix_stock_movements_issued_to_room_id` (`issued_to_room_id`),
  KEY `ix_stock_movements_created_by` (`created_by`),
  KEY `ix_stock_movements_item_id_created_at` (`item_id`, `created_at`),
  CHECK (`move_type` IN ('in', 'out', 'adjust', 'transfer', 'return', 'consume'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Append-only ledger: in/out/adjust/transfer/return.';

CREATE TABLE `issue_requests` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `requested_by` CHAR(26) NOT NULL,
  `store_id` CHAR(26) NOT NULL,
  `items` JSON NULL,
  `purpose` VARCHAR(160) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'pending',
  `approved_by` CHAR(26) NULL,
  `issued_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_issue_requests_school_id` (`school_id`),
  KEY `ix_issue_requests_requested_by` (`requested_by`),
  KEY `ix_issue_requests_store_id` (`store_id`),
  KEY `ix_issue_requests_approved_by` (`approved_by`),
  CHECK (`status` IN ('pending', 'approved', 'rejected', 'issued'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Consumable requests → stock-out on approval.';

CREATE TABLE `assets` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `item_id` CHAR(26) NULL,
  `asset_tag` VARCHAR(30) NOT NULL,
  `name` VARCHAR(160) NOT NULL,
  `serial_no` VARCHAR(80) NULL,
  `purchase_date` DATE NULL,
  `purchase_cost` DECIMAL(14,2) NULL,
  `vendor_id` CHAR(26) NULL,
  `po_id` CHAR(26) NULL,
  `warranty_until` DATE NULL,
  `depreciation_pct` DECIMAL(5,2) NULL,
  `current_value` DECIMAL(14,2) NULL,
  `location_room_id` CHAR(26) NULL,
  `custodian_staff_id` CHAR(26) NULL,
  `condition_note` VARCHAR(40) NOT NULL DEFAULT 'good',
  `status` VARCHAR(40) NOT NULL DEFAULT 'in_use',
  `qr_file_id` CHAR(26) NULL,
  `disposed_at` DATE NULL,
  `disposal_note` VARCHAR(255) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_assets_school_id` (`school_id`),
  KEY `ix_assets_item_id` (`item_id`),
  KEY `ix_assets_vendor_id` (`vendor_id`),
  KEY `ix_assets_po_id` (`po_id`),
  KEY `ix_assets_location_room_id` (`location_room_id`),
  KEY `ix_assets_custodian_staff_id` (`custodian_staff_id`),
  KEY `ix_assets_qr_file_id` (`qr_file_id`),
  UNIQUE KEY `uq_assets_school_id_asset_tag` (`school_id`, `asset_tag`),
  CHECK (`condition_note` IN ('new', 'good', 'fair', 'repair', 'damaged')),
  CHECK (`status` IN ('in_use', 'in_store', 'repair', 'disposed', 'lost'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Fixed asset with tag, custodian, warranty and value.';

CREATE TABLE `asset_maintenance` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `asset_id` CHAR(26) NOT NULL,
  `service_date` DATE NOT NULL,
  `service_type` VARCHAR(40) NOT NULL,
  `cost` DECIMAL(14,2) NULL,
  `vendor_id` CHAR(26) NULL,
  `expense_id` CHAR(26) NULL,
  `next_due_date` DATE NULL,
  `notes` TEXT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_asset_maintenance_school_id` (`school_id`),
  KEY `ix_asset_maintenance_asset_id` (`asset_id`),
  KEY `ix_asset_maintenance_vendor_id` (`vendor_id`),
  KEY `ix_asset_maintenance_expense_id` (`expense_id`),
  CHECK (`service_type` IN ('preventive', 'repair', 'calibration', 'inspection'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Service history with next due.';

CREATE TABLE `asset_audits` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(120) NOT NULL,
  `started_at` DATE NOT NULL,
  `finished_at` DATE NULL,
  `results` JSON NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'running',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_asset_audits_school_id` (`school_id`),
  CHECK (`status` IN ('running', 'completed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Periodic physical verification runs.';


-- ============ Facilities & maintenance ============
CREATE TABLE `room_bookings` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `room_id` CHAR(26) NOT NULL,
  `booked_by` CHAR(26) NOT NULL,
  `purpose` VARCHAR(160) NOT NULL,
  `starts_at` DATETIME NOT NULL,
  `ends_at` DATETIME NOT NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'pending',
  `approved_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_room_bookings_school_id` (`school_id`),
  KEY `ix_room_bookings_room_id` (`room_id`),
  KEY `ix_room_bookings_booked_by` (`booked_by`),
  KEY `ix_room_bookings_approved_by` (`approved_by`),
  KEY `ix_room_bookings_room_id_starts_at` (`room_id`, `starts_at`),
  CHECK (`status` IN ('pending', 'approved', 'rejected', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Book a room/hall/ground for an event or class (no overlap, app-enforced).';

CREATE TABLE `work_orders` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `title` VARCHAR(160) NOT NULL,
  `description` TEXT NULL,
  `location_room_id` CHAR(26) NULL,
  `asset_id` CHAR(26) NULL,
  `category` VARCHAR(40) NOT NULL,
  `priority` VARCHAR(40) NOT NULL DEFAULT 'normal',
  `reported_by` CHAR(26) NULL,
  `assigned_to` CHAR(26) NULL,
  `vendor_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'open',
  `due_at` DATETIME NULL,
  `cost` DECIMAL(14,2) NULL,
  `expense_id` CHAR(26) NULL,
  `completed_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_work_orders_school_id` (`school_id`),
  KEY `ix_work_orders_location_room_id` (`location_room_id`),
  KEY `ix_work_orders_asset_id` (`asset_id`),
  KEY `ix_work_orders_reported_by` (`reported_by`),
  KEY `ix_work_orders_assigned_to` (`assigned_to`),
  KEY `ix_work_orders_vendor_id` (`vendor_id`),
  KEY `ix_work_orders_expense_id` (`expense_id`),
  CHECK (`category` IN ('electrical', 'plumbing', 'civil', 'it', 'furniture', 'cleaning', 'other')),
  CHECK (`priority` IN ('low', 'normal', 'high', 'urgent')),
  CHECK (`status` IN ('open', 'assigned', 'in_progress', 'done', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Repair/maintenance requests with SLA.';

CREATE TABLE `cleaning_schedules` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `area` VARCHAR(120) NOT NULL,
  `frequency` VARCHAR(40) NOT NULL,
  `assigned_to` CHAR(26) NULL,
  `checklist` JSON NULL,
  `last_done_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_cleaning_schedules_school_id` (`school_id`),
  KEY `ix_cleaning_schedules_assigned_to` (`assigned_to`),
  CHECK (`frequency` IN ('daily', 'weekly', 'monthly'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Recurring cleaning tasks with checklist.';

CREATE TABLE `utility_readings` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `utility` VARCHAR(40) NOT NULL,
  `campus_id` CHAR(26) NULL,
  `read_at` DATE NOT NULL,
  `reading` DECIMAL(12,2) NOT NULL,
  `cost` DECIMAL(14,2) NULL,
  `expense_id` CHAR(26) NULL,
  PRIMARY KEY (`id`),
  KEY `ix_utility_readings_school_id` (`school_id`),
  KEY `ix_utility_readings_campus_id` (`campus_id`),
  KEY `ix_utility_readings_expense_id` (`expense_id`),
  CHECK (`utility` IN ('electricity', 'water', 'gas', 'internet', 'generator_fuel'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Electricity/water/gas meter readings and bills.';

CREATE TABLE `safety_drills` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `kind` VARCHAR(40) NOT NULL,
  `held_on` DATE NOT NULL,
  `participants` INT NULL,
  `findings` TEXT NULL,
  `file_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_safety_drills_school_id` (`school_id`),
  KEY `ix_safety_drills_file_id` (`file_id`),
  CHECK (`kind` IN ('fire', 'earthquake', 'evacuation', 'first_aid', 'inspection'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Fire/earthquake drills and inspections.';


-- ============ Front office, helpdesk & gate ============
CREATE TABLE `visitor_logs` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `campus_id` CHAR(26) NULL,
  `visitor_name` VARCHAR(160) NOT NULL,
  `phone` VARCHAR(20) NULL,
  `id_proof` VARCHAR(60) NULL,
  `purpose` VARCHAR(40) NOT NULL DEFAULT 'other',
  `to_meet_staff_id` CHAR(26) NULL,
  `student_id` CHAR(26) NULL,
  `badge_no` VARCHAR(20) NULL,
  `photo_file_id` CHAR(26) NULL,
  `in_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `out_at` DATETIME NULL,
  `host_notified_at` DATETIME NULL,
  `logged_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_visitor_logs_school_id` (`school_id`),
  KEY `ix_visitor_logs_campus_id` (`campus_id`),
  KEY `ix_visitor_logs_to_meet_staff_id` (`to_meet_staff_id`),
  KEY `ix_visitor_logs_student_id` (`student_id`),
  KEY `ix_visitor_logs_photo_file_id` (`photo_file_id`),
  KEY `ix_visitor_logs_logged_by` (`logged_by`),
  CHECK (`purpose` IN ('admission', 'meeting', 'delivery', 'pickup', 'interview', 'vendor', 'other'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Check-in/out with purpose, host and badge.';

CREATE TABLE `gate_passes` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `person_type` VARCHAR(40) NOT NULL,
  `student_id` CHAR(26) NULL,
  `staff_id` CHAR(26) NULL,
  `reason` VARCHAR(160) NOT NULL,
  `out_at` DATETIME NOT NULL,
  `expected_in` DATETIME NULL,
  `actual_in` DATETIME NULL,
  `picked_by` VARCHAR(160) NULL,
  `authorisation_id` CHAR(26) NULL,
  `approved_by` CHAR(26) NULL,
  `qr_code` VARCHAR(64) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'pending',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_gate_passes_school_id` (`school_id`),
  KEY `ix_gate_passes_student_id` (`student_id`),
  KEY `ix_gate_passes_staff_id` (`staff_id`),
  KEY `ix_gate_passes_authorisation_id` (`authorisation_id`),
  KEY `ix_gate_passes_approved_by` (`approved_by`),
  CHECK (`person_type` IN ('student', 'staff')),
  CHECK (`status` IN ('pending', 'approved', 'out', 'returned', 'rejected'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Student early leave / staff out pass with QR.';

CREATE TABLE `call_logs` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `direction` VARCHAR(40) NOT NULL,
  `caller_name` VARCHAR(160) NULL,
  `phone` VARCHAR(20) NOT NULL,
  `purpose` VARCHAR(160) NULL,
  `notes` TEXT NULL,
  `related_type` VARCHAR(40) NULL,
  `related_id` CHAR(26) NULL,
  `follow_up_at` DATETIME NULL,
  `logged_by` CHAR(26) NULL,
  `called_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_call_logs_school_id` (`school_id`),
  KEY `ix_call_logs_logged_by` (`logged_by`),
  CHECK (`direction` IN ('inbound', 'outbound'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Inbound/outbound calls with follow-up.';

CREATE TABLE `postal_records` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `direction` VARCHAR(40) NOT NULL,
  `reference_no` VARCHAR(60) NULL,
  `from_party` VARCHAR(160) NULL,
  `to_party` VARCHAR(160) NULL,
  `subject` VARCHAR(200) NULL,
  `record_date` DATE NOT NULL,
  `file_id` CHAR(26) NULL,
  `logged_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_postal_records_school_id` (`school_id`),
  KEY `ix_postal_records_file_id` (`file_id`),
  KEY `ix_postal_records_logged_by` (`logged_by`),
  CHECK (`direction` IN ('dispatch', 'receive'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Dispatch/receive register.';

CREATE TABLE `complaints` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `ticket_no` VARCHAR(30) NOT NULL,
  `complainant_user_id` CHAR(26) NULL,
  `complainant_name` VARCHAR(160) NULL,
  `complainant_phone` VARCHAR(20) NULL,
  `student_id` CHAR(26) NULL,
  `category` VARCHAR(40) NOT NULL,
  `subject` VARCHAR(200) NOT NULL,
  `description` TEXT NOT NULL,
  `priority` VARCHAR(40) NOT NULL DEFAULT 'normal',
  `assigned_to` CHAR(26) NULL,
  `sla_due_at` DATETIME NULL,
  `escalated_at` DATETIME NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'open',
  `resolution` TEXT NULL,
  `resolved_at` DATETIME NULL,
  `satisfaction` SMALLINT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_complaints_school_id` (`school_id`),
  KEY `ix_complaints_complainant_user_id` (`complainant_user_id`),
  KEY `ix_complaints_student_id` (`student_id`),
  KEY `ix_complaints_assigned_to` (`assigned_to`),
  UNIQUE KEY `uq_complaints_school_id_ticket_no` (`school_id`, `ticket_no`),
  CHECK (`category` IN ('academic', 'fees', 'transport', 'hostel', 'staff_behaviour', 'facility', 'safety', 'it', 'other')),
  CHECK (`priority` IN ('low', 'normal', 'high', 'urgent')),
  CHECK (`status` IN ('open', 'in_progress', 'resolved', 'closed', 'reopened'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Helpdesk tickets with category, priority, SLA, escalation and satisfaction.';

CREATE TABLE `complaint_updates` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `complaint_id` CHAR(26) NOT NULL,
  `by_user_id` CHAR(26) NULL,
  `note` TEXT NOT NULL,
  `is_internal` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_complaint_updates_school_id` (`school_id`),
  KEY `ix_complaint_updates_complaint_id` (`complaint_id`),
  KEY `ix_complaint_updates_by_user_id` (`by_user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Thread of updates.';

CREATE TABLE `lost_found_items` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `description` VARCHAR(200) NOT NULL,
  `found_at` DATETIME NULL,
  `location` VARCHAR(120) NULL,
  `photo_file_id` CHAR(26) NULL,
  `claimed_by` VARCHAR(160) NULL,
  `claimed_at` DATETIME NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'found',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_lost_found_items_school_id` (`school_id`),
  KEY `ix_lost_found_items_photo_file_id` (`photo_file_id`),
  CHECK (`status` IN ('found', 'claimed', 'disposed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Lost & found register.';


-- ============ Communication · SMS, push, email, WhatsApp, chat ============
CREATE TABLE `messaging_providers` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `channel` VARCHAR(40) NOT NULL,
  `provider` VARCHAR(60) NOT NULL,
  `credentials` JSON NULL,
  `sender_id` VARCHAR(80) NULL,
  `is_default` TINYINT(1) NOT NULL DEFAULT 0,
  `balance` DECIMAL(14,2) NULL,
  `low_balance_threshold` DECIMAL(14,2) NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `cost_per_unit` DECIMAL(14,2) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_messaging_providers_school_id` (`school_id`),
  CHECK (`channel` IN ('sms', 'email', 'push', 'whatsapp', 'voice'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SMS/email/push/WhatsApp/voice providers.';

CREATE TABLE `notification_templates` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `event_key` VARCHAR(80) NOT NULL,
  `channel` VARCHAR(40) NOT NULL,
  `locale` VARCHAR(10) NOT NULL DEFAULT 'bn',
  `subject` VARCHAR(200) NULL,
  `body` TEXT NOT NULL,
  `variables` JSON NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_notification_templates_school_id` (`school_id`),
  UNIQUE KEY `uq_notification_templates_school_id_event_key_channel_locale` (`school_id`, `event_key`, `channel`, `locale`),
  CHECK (`channel` IN ('sms', 'email', 'push', 'whatsapp', 'in_app', 'voice'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Per event × channel × locale with placeholders.';

CREATE TABLE `notifications` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `recipient_user_id` CHAR(26) NULL,
  `recipient_address` VARCHAR(160) NULL,
  `channel` VARCHAR(40) NOT NULL,
  `event_key` VARCHAR(80) NULL,
  `template_id` CHAR(26) NULL,
  `title` VARCHAR(200) NULL,
  `body` TEXT NOT NULL,
  `data` JSON NULL,
  `entity_type` VARCHAR(60) NULL,
  `entity_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'queued',
  `provider_id` CHAR(26) NULL,
  `provider_msg_id` VARCHAR(120) NULL,
  `cost` DECIMAL(10,4) NULL,
  `attempts` SMALLINT NOT NULL DEFAULT 0,
  `error` VARCHAR(255) NULL,
  `scheduled_for` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `sent_at` DATETIME NULL,
  `delivered_at` DATETIME NULL,
  `read_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_notifications_school_id` (`school_id`),
  KEY `ix_notifications_recipient_user_id` (`recipient_user_id`),
  KEY `ix_notifications_template_id` (`template_id`),
  KEY `ix_notifications_provider_id` (`provider_id`),
  KEY `ix_notifications_status_scheduled_for` (`status`, `scheduled_for`),
  KEY `ix_notifications_recipient_user_id_created_at` (`recipient_user_id`, `created_at`),
  KEY `ix_notifications_entity_type_entity_id` (`entity_type`, `entity_id`),
  CHECK (`channel` IN ('sms', 'email', 'push', 'whatsapp', 'in_app', 'voice')),
  CHECK (`status` IN ('queued', 'sent', 'delivered', 'failed', 'read'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Every message sent with status, provider id, cost, read time.';

CREATE TABLE `notification_preferences` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `user_id` CHAR(26) NOT NULL,
  `event_key` VARCHAR(80) NOT NULL,
  `channel` VARCHAR(40) NOT NULL,
  `enabled` TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `ix_notification_preferences_school_id` (`school_id`),
  KEY `ix_notification_preferences_user_id` (`user_id`),
  UNIQUE KEY `uq_notification_preferences_user_id_event_key_channel` (`user_id`, `event_key`, `channel`),
  CHECK (`channel` IN ('sms', 'email', 'push', 'whatsapp', 'in_app', 'voice'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Per user per event per channel.';

CREATE TABLE `notices` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `title` VARCHAR(200) NOT NULL,
  `body` LONGTEXT NOT NULL,
  `notice_type` VARCHAR(40) NOT NULL DEFAULT 'general',
  `audience` JSON NULL,
  `attachments` JSON NULL,
  `publish_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `expires_at` DATETIME NULL,
  `is_pinned` TINYINT(1) NOT NULL DEFAULT 0,
  `send_push` TINYINT(1) NOT NULL DEFAULT 1,
  `send_sms` TINYINT(1) NOT NULL DEFAULT 0,
  `send_email` TINYINT(1) NOT NULL DEFAULT 0,
  `status` VARCHAR(40) NOT NULL DEFAULT 'published',
  `created_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` DATETIME NULL COMMENT 'Soft delete',
  PRIMARY KEY (`id`),
  KEY `ix_notices_school_id` (`school_id`),
  KEY `ix_notices_created_by` (`created_by`),
  KEY `ix_notices_school_id_publish_at` (`school_id`, `publish_at`),
  CHECK (`notice_type` IN ('general', 'academic', 'exam', 'fee', 'holiday', 'urgent', 'event')),
  CHECK (`status` IN ('draft', 'scheduled', 'published', 'archived'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Notices with audience, schedule, pin, attachments.';

CREATE TABLE `notice_reads` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `notice_id` CHAR(26) NOT NULL,
  `user_id` CHAR(26) NOT NULL,
  `read_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_notice_reads_school_id` (`school_id`),
  KEY `ix_notice_reads_notice_id` (`notice_id`),
  KEY `ix_notice_reads_user_id` (`user_id`),
  UNIQUE KEY `uq_notice_reads_notice_id_user_id` (`notice_id`, `user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Read receipts.';

CREATE TABLE `conversations` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `kind` VARCHAR(40) NOT NULL DEFAULT 'direct',
  `subject` VARCHAR(160) NULL,
  `section_id` CHAR(26) NULL,
  `created_by` CHAR(26) NULL,
  `last_message_at` DATETIME NULL,
  `is_locked` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_conversations_school_id` (`school_id`),
  KEY `ix_conversations_section_id` (`section_id`),
  KEY `ix_conversations_created_by` (`created_by`),
  CHECK (`kind` IN ('direct', 'group', 'section_channel', 'broadcast', 'support'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Direct chats, groups, section channels, broadcast lists.';

CREATE TABLE `conversation_participants` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `conversation_id` CHAR(26) NOT NULL,
  `user_id` CHAR(26) NOT NULL,
  `role` VARCHAR(40) NOT NULL DEFAULT 'member',
  `muted` TINYINT(1) NOT NULL DEFAULT 0,
  `last_read_at` DATETIME NULL,
  PRIMARY KEY (`id`),
  KEY `ix_conversation_participants_school_id` (`school_id`),
  KEY `ix_conversation_participants_conversation_id` (`conversation_id`),
  KEY `ix_conversation_participants_user_id` (`user_id`),
  UNIQUE KEY `uq_conversation_participants_conversation_id_user_id` (`conversation_id`, `user_id`),
  CHECK (`role` IN ('member', 'admin'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Members with role, mute and read pointer.';

CREATE TABLE `messages` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `conversation_id` CHAR(26) NOT NULL,
  `sender_id` CHAR(26) NULL,
  `body` TEXT NULL,
  `attachments` JSON NULL,
  `reply_to_id` CHAR(26) NULL,
  `sent_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `edited_at` DATETIME NULL,
  `deleted_at` DATETIME NULL,
  `flagged` TINYINT(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `ix_messages_school_id` (`school_id`),
  KEY `ix_messages_conversation_id` (`conversation_id`),
  KEY `ix_messages_sender_id` (`sender_id`),
  KEY `ix_messages_reply_to_id` (`reply_to_id`),
  KEY `ix_messages_conversation_id_sent_at` (`conversation_id`, `sent_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Chat messages with attachments; moderated.';

CREATE TABLE `ptm_slots` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `event_id` CHAR(26) NULL,
  `teacher_id` CHAR(26) NOT NULL,
  `starts_at` DATETIME NOT NULL,
  `ends_at` DATETIME NOT NULL,
  `capacity` SMALLINT NOT NULL DEFAULT 1,
  `room_id` CHAR(26) NULL,
  `mode` VARCHAR(40) NOT NULL DEFAULT 'in_person',
  `join_url` VARCHAR(500) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_ptm_slots_school_id` (`school_id`),
  KEY `ix_ptm_slots_teacher_id` (`teacher_id`),
  KEY `ix_ptm_slots_room_id` (`room_id`),
  KEY `ix_ptm_slots_teacher_id_starts_at` (`teacher_id`, `starts_at`),
  CHECK (`mode` IN ('in_person', 'online'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Parent–teacher meeting slots.';

CREATE TABLE `ptm_bookings` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `slot_id` CHAR(26) NOT NULL,
  `student_id` CHAR(26) NOT NULL,
  `guardian_id` CHAR(26) NOT NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'booked',
  `notes` TEXT NULL,
  `reminder_sent_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_ptm_bookings_school_id` (`school_id`),
  KEY `ix_ptm_bookings_slot_id` (`slot_id`),
  KEY `ix_ptm_bookings_student_id` (`student_id`),
  KEY `ix_ptm_bookings_guardian_id` (`guardian_id`),
  UNIQUE KEY `uq_ptm_bookings_slot_id_student_id` (`slot_id`, `student_id`),
  CHECK (`status` IN ('booked', 'attended', 'no_show', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Bookings with reminders and outcome notes.';

CREATE TABLE `surveys` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `form_id` CHAR(26) NOT NULL,
  `title` VARCHAR(200) NOT NULL,
  `audience` JSON NULL,
  `is_anonymous` TINYINT(1) NOT NULL DEFAULT 0,
  `opens_at` DATETIME NULL,
  `closes_at` DATETIME NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'draft',
  `results` JSON NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_surveys_school_id` (`school_id`),
  KEY `ix_surveys_form_id` (`form_id`),
  CHECK (`status` IN ('draft', 'open', 'closed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Surveys/polls to guardians, students, staff (uses form builder).';

CREATE TABLE `newsletters` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `title` VARCHAR(200) NOT NULL,
  `body` LONGTEXT NULL,
  `audience` JSON NULL,
  `channel` VARCHAR(40) NOT NULL DEFAULT 'email',
  `scheduled_for` DATETIME NULL,
  `sent_at` DATETIME NULL,
  `stats` JSON NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'draft',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_newsletters_school_id` (`school_id`),
  CHECK (`channel` IN ('email', 'whatsapp', 'sms')),
  CHECK (`status` IN ('draft', 'scheduled', 'sent'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Email/WhatsApp newsletters and campaigns.';

CREATE TABLE `voice_broadcasts` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `title` VARCHAR(200) NOT NULL,
  `audio_file_id` CHAR(26) NULL,
  `tts_text` TEXT NULL,
  `audience` JSON NULL,
  `scheduled_for` DATETIME NULL,
  `stats` JSON NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'draft',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_voice_broadcasts_school_id` (`school_id`),
  KEY `ix_voice_broadcasts_audio_file_id` (`audio_file_id`),
  CHECK (`status` IN ('draft', 'scheduled', 'running', 'done'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='IVR / recorded voice calls (emergency, fee reminder).';


-- ============ Welfare · behaviour, health, counselling, safeguarding ============
CREATE TABLE `behaviour_categories` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(120) NOT NULL,
  `polarity` VARCHAR(40) NOT NULL,
  `default_points` SMALLINT NOT NULL DEFAULT 1,
  `severity` VARCHAR(40) NOT NULL DEFAULT 'low',
  `notify_guardian` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_behaviour_categories_school_id` (`school_id`),
  UNIQUE KEY `uq_behaviour_categories_school_id_name` (`school_id`, `name`),
  CHECK (`polarity` IN ('positive', 'negative')),
  CHECK (`severity` IN ('low', 'medium', 'high', 'critical'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Positive/negative categories with default points and severity.';

CREATE TABLE `behaviour_incidents` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `category_id` CHAR(26) NOT NULL,
  `incident_date` DATE NOT NULL,
  `points` SMALLINT NOT NULL,
  `description` TEXT NOT NULL,
  `reported_by` CHAR(26) NOT NULL,
  `witnesses` VARCHAR(255) NULL,
  `attachments` JSON NULL,
  `guardian_notified_at` DATETIME NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'open',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_behaviour_incidents_school_id` (`school_id`),
  KEY `ix_behaviour_incidents_student_id` (`student_id`),
  KEY `ix_behaviour_incidents_category_id` (`category_id`),
  KEY `ix_behaviour_incidents_reported_by` (`reported_by`),
  KEY `ix_behaviour_incidents_student_id_incident_date` (`student_id`, `incident_date`),
  CHECK (`status` IN ('open', 'under_review', 'actioned', 'closed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='An incident with points and reporter.';

CREATE TABLE `disciplinary_actions` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `incident_id` CHAR(26) NULL,
  `student_id` CHAR(26) NOT NULL,
  `action_type` VARCHAR(40) NOT NULL,
  `from_date` DATE NULL,
  `to_date` DATE NULL,
  `description` TEXT NULL,
  `is_auto_proposed` TINYINT(1) NOT NULL DEFAULT 0,
  `status` VARCHAR(40) NOT NULL DEFAULT 'pending',
  `approved_by` CHAR(26) NULL,
  `guardian_acknowledged_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_disciplinary_actions_school_id` (`school_id`),
  KEY `ix_disciplinary_actions_incident_id` (`incident_id`),
  KEY `ix_disciplinary_actions_student_id` (`student_id`),
  KEY `ix_disciplinary_actions_approved_by` (`approved_by`),
  CHECK (`action_type` IN ('verbal_warning', 'written_warning', 'detention', 'suspension', 'expulsion', 'counselling', 'community_service')),
  CHECK (`status` IN ('pending', 'approved', 'rejected', 'completed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Warning, detention, suspension… with approval and guardian acknowledgement.';

CREATE TABLE `behaviour_rules` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(120) NOT NULL,
  `window_days` SMALLINT NOT NULL DEFAULT 30,
  `threshold_points` SMALLINT NOT NULL,
  `action_type` VARCHAR(40) NOT NULL,
  `notify_roles` JSON NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_behaviour_rules_school_id` (`school_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Threshold rules → proposed action.';

CREATE TABLE `health_records` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `recorded_on` DATE NOT NULL,
  `height_cm` DECIMAL(5,1) NULL,
  `weight_kg` DECIMAL(5,1) NULL,
  `bmi` DECIMAL(4,1) NULL,
  `vision_left` VARCHAR(10) NULL,
  `vision_right` VARCHAR(10) NULL,
  `hearing` VARCHAR(20) NULL,
  `dental` VARCHAR(40) NULL,
  `blood_pressure` VARCHAR(15) NULL,
  `allergies` JSON NULL,
  `chronic_conditions` JSON NULL,
  `medications` TEXT NULL,
  `doctor_notes` TEXT NULL,
  `recorded_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_health_records_school_id` (`school_id`),
  KEY `ix_health_records_student_id` (`student_id`),
  KEY `ix_health_records_recorded_by` (`recorded_by`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Growth and screening records.';

CREATE TABLE `vaccinations` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `vaccine` VARCHAR(80) NOT NULL,
  `dose_no` SMALLINT NOT NULL DEFAULT 1,
  `given_on` DATE NULL,
  `next_due_on` DATE NULL,
  `certificate_file_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_vaccinations_school_id` (`school_id`),
  KEY `ix_vaccinations_student_id` (`student_id`),
  KEY `ix_vaccinations_certificate_file_id` (`certificate_file_id`),
  UNIQUE KEY `uq_vaccinations_student_id_vaccine_dose_no` (`student_id`, `vaccine`, `dose_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Doses and next due.';

CREATE TABLE `clinic_visits` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `person_type` VARCHAR(40) NOT NULL,
  `student_id` CHAR(26) NULL,
  `staff_id` CHAR(26) NULL,
  `visited_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `complaint` VARCHAR(255) NOT NULL,
  `treatment` TEXT NULL,
  `medicines_given` JSON NULL,
  `referred_to` VARCHAR(160) NULL,
  `sent_home` TINYINT(1) NOT NULL DEFAULT 0,
  `guardian_notified_at` DATETIME NULL,
  `attended_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_clinic_visits_school_id` (`school_id`),
  KEY `ix_clinic_visits_student_id` (`student_id`),
  KEY `ix_clinic_visits_staff_id` (`staff_id`),
  KEY `ix_clinic_visits_attended_by` (`attended_by`),
  CHECK (`person_type` IN ('student', 'staff'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='School clinic visit with treatment, medicines (stock-out) and send-home flag.';

CREATE TABLE `counselling_sessions` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `counsellor_id` CHAR(26) NOT NULL,
  `session_at` DATETIME NOT NULL,
  `referral_source` VARCHAR(40) NOT NULL DEFAULT 'self',
  `notes_encrypted` TEXT NULL,
  `follow_up_at` DATETIME NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'scheduled',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_counselling_sessions_school_id` (`school_id`),
  KEY `ix_counselling_sessions_student_id` (`student_id`),
  KEY `ix_counselling_sessions_counsellor_id` (`counsellor_id`),
  CHECK (`referral_source` IN ('self', 'teacher', 'behaviour_rule', 'result_drop', 'guardian', 'clinic')),
  CHECK (`status` IN ('scheduled', 'done', 'no_show', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Sessions with encrypted notes (counsellor-only).';

CREATE TABLE `insurance_policies` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `person_type` VARCHAR(40) NOT NULL,
  `student_id` CHAR(26) NULL,
  `staff_id` CHAR(26) NULL,
  `provider` VARCHAR(120) NOT NULL,
  `policy_no` VARCHAR(60) NOT NULL,
  `coverage` DECIMAL(14,2) NULL,
  `valid_from` DATE NULL,
  `valid_to` DATE NULL,
  `claims` JSON NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_insurance_policies_school_id` (`school_id`),
  KEY `ix_insurance_policies_student_id` (`student_id`),
  KEY `ix_insurance_policies_staff_id` (`staff_id`),
  CHECK (`person_type` IN ('student', 'staff'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Student/staff insurance and claims.';

CREATE TABLE `safeguarding_cases` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `reported_by` CHAR(26) NULL,
  `category` VARCHAR(40) NOT NULL,
  `details_encrypted` TEXT NULL,
  `risk_level` VARCHAR(40) NOT NULL DEFAULT 'medium',
  `status` VARCHAR(40) NOT NULL DEFAULT 'open',
  `case_owner_id` CHAR(26) NULL,
  `closed_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_safeguarding_cases_school_id` (`school_id`),
  KEY `ix_safeguarding_cases_student_id` (`student_id`),
  KEY `ix_safeguarding_cases_reported_by` (`reported_by`),
  KEY `ix_safeguarding_cases_case_owner_id` (`case_owner_id`),
  CHECK (`category` IN ('abuse', 'neglect', 'bullying', 'online_safety', 'self_harm', 'other')),
  CHECK (`risk_level` IN ('low', 'medium', 'high')),
  CHECK (`status` IN ('open', 'monitoring', 'closed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Confidential child-protection cases with restricted access.';

CREATE TABLE `special_needs_plans` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `diagnosis` VARCHAR(200) NULL,
  `accommodations` JSON NULL,
  `goals` JSON NULL,
  `review_date` DATE NULL,
  `coordinator_id` CHAR(26) NULL,
  `file_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_special_needs_plans_school_id` (`school_id`),
  KEY `ix_special_needs_plans_student_id` (`student_id`),
  KEY `ix_special_needs_plans_coordinator_id` (`coordinator_id`),
  KEY `ix_special_needs_plans_file_id` (`file_id`),
  CHECK (`status` IN ('active', 'closed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='IEP / accommodation plans.';


-- ============ Documents, certificates & ID cards ============
CREATE TABLE `document_templates` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `doc_type` VARCHAR(40) NOT NULL,
  `name` VARCHAR(120) NOT NULL,
  `html_template` LONGTEXT NOT NULL,
  `css` TEXT NULL,
  `page_size` VARCHAR(20) NOT NULL DEFAULT 'A4',
  `orientation` VARCHAR(40) NOT NULL DEFAULT 'portrait',
  `variables` JSON NULL,
  `is_default` TINYINT(1) NOT NULL DEFAULT 0,
  `version` SMALLINT NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_document_templates_school_id` (`school_id`),
  UNIQUE KEY `uq_document_templates_school_id_doc_type_name` (`school_id`, `doc_type`, `name`),
  CHECK (`doc_type` IN ('tc', 'testimonial', 'character', 'bonafide', 'id_card', 'admit_card', 'report_card', 'payslip', 'receipt', 'donation_receipt', 'invoice', 'offer_letter', 'appointment_letter', 'experience_letter', 'certificate', 'marksheet', 'custom')),
  CHECK (`orientation` IN ('portrait', 'landscape'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Versioned templates per document type.';

CREATE TABLE `document_requests` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `doc_type` VARCHAR(40) NOT NULL,
  `person_type` VARCHAR(40) NOT NULL,
  `student_id` CHAR(26) NULL,
  `staff_id` CHAR(26) NULL,
  `requested_by` CHAR(26) NULL,
  `reason` VARCHAR(255) NULL,
  `fee_invoice_id` CHAR(26) NULL,
  `eligibility` JSON NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'requested',
  `approval_request_id` CHAR(26) NULL,
  `decided_by` CHAR(26) NULL,
  `decided_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_document_requests_school_id` (`school_id`),
  KEY `ix_document_requests_student_id` (`student_id`),
  KEY `ix_document_requests_staff_id` (`staff_id`),
  KEY `ix_document_requests_requested_by` (`requested_by`),
  KEY `ix_document_requests_fee_invoice_id` (`fee_invoice_id`),
  KEY `ix_document_requests_decided_by` (`decided_by`),
  CHECK (`person_type` IN ('student', 'staff', 'alumni')),
  CHECK (`status` IN ('requested', 'blocked', 'approved', 'issued', 'rejected'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Request with eligibility snapshot and fee.';

CREATE TABLE `issued_documents` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `template_id` CHAR(26) NULL,
  `request_id` CHAR(26) NULL,
  `doc_type` VARCHAR(40) NOT NULL,
  `document_no` VARCHAR(40) NOT NULL,
  `person_type` VARCHAR(40) NOT NULL,
  `student_id` CHAR(26) NULL,
  `staff_id` CHAR(26) NULL,
  `data_snapshot` JSON NULL,
  `file_id` CHAR(26) NULL,
  `verification_code` VARCHAR(32) NOT NULL,
  `signed_by` CHAR(26) NULL,
  `signature_hash` VARCHAR(128) NULL,
  `issued_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `valid_until` DATE NULL,
  `revoked_at` DATETIME NULL,
  `revoke_reason` VARCHAR(160) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_issued_documents_school_id` (`school_id`),
  KEY `ix_issued_documents_template_id` (`template_id`),
  KEY `ix_issued_documents_request_id` (`request_id`),
  KEY `ix_issued_documents_student_id` (`student_id`),
  KEY `ix_issued_documents_staff_id` (`staff_id`),
  KEY `ix_issued_documents_file_id` (`file_id`),
  UNIQUE KEY `uq_issued_documents_verification_code` (`verification_code`),
  KEY `ix_issued_documents_signed_by` (`signed_by`),
  UNIQUE KEY `uq_issued_documents_school_id_document_no` (`school_id`, `document_no`),
  KEY `ix_issued_documents_student_id_doc_type` (`student_id`, `doc_type`),
  CHECK (`person_type` IN ('student', 'staff', 'alumni', 'other'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Issued document with frozen data, file and verification code.';

CREATE TABLE `id_cards` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `person_type` VARCHAR(40) NOT NULL,
  `student_id` CHAR(26) NULL,
  `staff_id` CHAR(26) NULL,
  `guardian_id` CHAR(26) NULL,
  `card_no` VARCHAR(30) NOT NULL,
  `template_id` CHAR(26) NULL,
  `valid_from` DATE NOT NULL,
  `valid_to` DATE NOT NULL,
  `rfid_tag` VARCHAR(40) NULL,
  `file_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'pending_print',
  `printed_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_id_cards_school_id` (`school_id`),
  KEY `ix_id_cards_student_id` (`student_id`),
  KEY `ix_id_cards_staff_id` (`staff_id`),
  KEY `ix_id_cards_guardian_id` (`guardian_id`),
  KEY `ix_id_cards_template_id` (`template_id`),
  KEY `ix_id_cards_file_id` (`file_id`),
  UNIQUE KEY `uq_id_cards_school_id_card_no` (`school_id`, `card_no`),
  CHECK (`person_type` IN ('student', 'staff', 'guardian', 'visitor')),
  CHECK (`status` IN ('pending_print', 'active', 'lost', 'expired', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Cards with validity, RFID and print status.';

CREATE TABLE `print_jobs` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `kind` VARCHAR(40) NOT NULL,
  `items` JSON NULL,
  `file_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'queued',
  `created_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_print_jobs_school_id` (`school_id`),
  KEY `ix_print_jobs_file_id` (`file_id`),
  KEY `ix_print_jobs_created_by` (`created_by`),
  CHECK (`status` IN ('queued', 'rendering', 'ready', 'printed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Bulk print batches (ID cards, admit cards, report cards).';

CREATE TABLE `document_verifications` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `document_id` CHAR(26) NOT NULL,
  `verified_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `ip` VARCHAR(45) NULL,
  `user_agent` VARCHAR(255) NULL,
  PRIMARY KEY (`id`),
  KEY `ix_document_verifications_school_id` (`school_id`),
  KEY `ix_document_verifications_document_id` (`document_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Public verification hits (who checked what).';


-- ============ Alumni & career ============
CREATE TABLE `alumni` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NULL,
  `user_id` CHAR(26) NULL,
  `full_name` VARCHAR(160) NOT NULL,
  `graduation_year` SMALLINT NOT NULL,
  `last_class_id` CHAR(26) NULL,
  `phone` VARCHAR(20) NULL,
  `email` VARCHAR(160) NULL,
  `current_organisation` VARCHAR(160) NULL,
  `current_position` VARCHAR(120) NULL,
  `city` VARCHAR(80) NULL,
  `country` VARCHAR(60) NULL,
  `linkedin_url` VARCHAR(255) NULL,
  `bio` TEXT NULL,
  `photo_file_id` CHAR(26) NULL,
  `is_public` TINYINT(1) NOT NULL DEFAULT 0,
  `is_mentor` TINYINT(1) NOT NULL DEFAULT 0,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_alumni_school_id` (`school_id`),
  UNIQUE KEY `uq_alumni_student_id` (`student_id`),
  UNIQUE KEY `uq_alumni_user_id` (`user_id`),
  KEY `ix_alumni_last_class_id` (`last_class_id`),
  KEY `ix_alumni_photo_file_id` (`photo_file_id`),
  KEY `ix_alumni_school_id_graduation_year` (`school_id`, `graduation_year`),
  CHECK (`status` IN ('active', 'inactive'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Alumni profile.';

CREATE TABLE `alumni_batches` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `graduation_year` SMALLINT NOT NULL,
  `name` VARCHAR(80) NULL,
  `rep_alumni_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_alumni_batches_school_id` (`school_id`),
  KEY `ix_alumni_batches_rep_alumni_id` (`rep_alumni_id`),
  UNIQUE KEY `uq_alumni_batches_school_id_graduation_year` (`school_id`, `graduation_year`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Batch groups with reps.';

CREATE TABLE `mentorship_pairs` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `mentor_id` CHAR(26) NOT NULL,
  `student_id` CHAR(26) NOT NULL,
  `topic` VARCHAR(160) NULL,
  `started_on` DATE NOT NULL,
  `ended_on` DATE NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_mentorship_pairs_school_id` (`school_id`),
  KEY `ix_mentorship_pairs_mentor_id` (`mentor_id`),
  KEY `ix_mentorship_pairs_student_id` (`student_id`),
  CHECK (`status` IN ('active', 'ended'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Alumni mentor ↔ student.';

CREATE TABLE `job_board_posts` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `posted_by_alumni_id` CHAR(26) NULL,
  `title` VARCHAR(160) NOT NULL,
  `company` VARCHAR(160) NULL,
  `location` VARCHAR(120) NULL,
  `description` TEXT NULL,
  `apply_url` VARCHAR(500) NULL,
  `expires_at` DATE NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'open',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_job_board_posts_school_id` (`school_id`),
  KEY `ix_job_board_posts_posted_by_alumni_id` (`posted_by_alumni_id`),
  CHECK (`status` IN ('open', 'closed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Jobs/internships shared by alumni or partners.';


-- ============ Events & ticketing ============
CREATE TABLE `events` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `calendar_event_id` CHAR(26) NULL,
  `title` VARCHAR(200) NOT NULL,
  `description` LONGTEXT NULL,
  `event_type` VARCHAR(40) NOT NULL,
  `starts_at` DATETIME NOT NULL,
  `ends_at` DATETIME NULL,
  `venue` VARCHAR(160) NULL,
  `room_id` CHAR(26) NULL,
  `audience` JSON NULL,
  `rsvp_required` TINYINT(1) NOT NULL DEFAULT 0,
  `ticket_price` DECIMAL(14,2) NULL,
  `ticket_limit` INT NULL,
  `fee_head_id` CHAR(26) NULL,
  `banner_file_id` CHAR(26) NULL,
  `organiser_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'scheduled',
  `feedback_form_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_events_school_id` (`school_id`),
  KEY `ix_events_calendar_event_id` (`calendar_event_id`),
  KEY `ix_events_room_id` (`room_id`),
  KEY `ix_events_fee_head_id` (`fee_head_id`),
  KEY `ix_events_banner_file_id` (`banner_file_id`),
  KEY `ix_events_organiser_id` (`organiser_id`),
  KEY `ix_events_feedback_form_id` (`feedback_form_id`),
  CHECK (`event_type` IN ('sports', 'cultural', 'ptm', 'seminar', 'trip', 'ceremony', 'competition', 'workshop', 'other')),
  CHECK (`status` IN ('draft', 'scheduled', 'live', 'completed', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Event with venue, audience, RSVP and ticketing.';

CREATE TABLE `event_rsvps` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `event_id` CHAR(26) NOT NULL,
  `user_id` CHAR(26) NOT NULL,
  `student_id` CHAR(26) NULL,
  `response` VARCHAR(40) NOT NULL,
  `guests` SMALLINT NOT NULL DEFAULT 0,
  `responded_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_event_rsvps_school_id` (`school_id`),
  KEY `ix_event_rsvps_event_id` (`event_id`),
  KEY `ix_event_rsvps_user_id` (`user_id`),
  KEY `ix_event_rsvps_student_id` (`student_id`),
  UNIQUE KEY `uq_event_rsvps_event_id_user_id` (`event_id`, `user_id`),
  CHECK (`response` IN ('yes', 'no', 'maybe'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Responses.';

CREATE TABLE `event_tickets` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `event_id` CHAR(26) NOT NULL,
  `holder_user_id` CHAR(26) NULL,
  `holder_name` VARCHAR(160) NULL,
  `quantity` SMALLINT NOT NULL DEFAULT 1,
  `amount` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `payment_id` CHAR(26) NULL,
  `qr_code` VARCHAR(64) NOT NULL,
  `checked_in_at` DATETIME NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'reserved',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_event_tickets_school_id` (`school_id`),
  KEY `ix_event_tickets_event_id` (`event_id`),
  KEY `ix_event_tickets_holder_user_id` (`holder_user_id`),
  KEY `ix_event_tickets_payment_id` (`payment_id`),
  UNIQUE KEY `uq_event_tickets_qr_code` (`qr_code`),
  CHECK (`status` IN ('reserved', 'paid', 'cancelled', 'used'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Paid/free tickets with QR and check-in.';

CREATE TABLE `event_schedule_items` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `event_id` CHAR(26) NOT NULL,
  `starts_at` DATETIME NOT NULL,
  `title` VARCHAR(200) NOT NULL,
  `presenter` VARCHAR(160) NULL,
  `sequence` SMALLINT NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `ix_event_schedule_items_school_id` (`school_id`),
  KEY `ix_event_schedule_items_event_id` (`event_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Programme items inside an event.';

CREATE TABLE `event_volunteers` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `event_id` CHAR(26) NOT NULL,
  `user_id` CHAR(26) NOT NULL,
  `role` VARCHAR(80) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'applied',
  PRIMARY KEY (`id`),
  KEY `ix_event_volunteers_school_id` (`school_id`),
  KEY `ix_event_volunteers_event_id` (`event_id`),
  KEY `ix_event_volunteers_user_id` (`user_id`),
  UNIQUE KEY `uq_event_volunteers_event_id_user_id` (`event_id`, `user_id`),
  CHECK (`status` IN ('applied', 'confirmed', 'declined'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Volunteer sign-ups.';


-- ============ Governance · committee, meetings, policies ============
CREATE TABLE `committees` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(120) NOT NULL,
  `kind` VARCHAR(40) NOT NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_committees_school_id` (`school_id`),
  CHECK (`kind` IN ('managing', 'academic', 'pta', 'student_council', 'disciplinary', 'other')),
  CHECK (`status` IN ('active', 'dissolved'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Managing committee, academic council, PTA, student council.';

CREATE TABLE `committee_members` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `committee_id` CHAR(26) NOT NULL,
  `person_name` VARCHAR(160) NOT NULL,
  `user_id` CHAR(26) NULL,
  `role` VARCHAR(80) NOT NULL,
  `term_start` DATE NULL,
  `term_end` DATE NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_committee_members_school_id` (`school_id`),
  KEY `ix_committee_members_committee_id` (`committee_id`),
  KEY `ix_committee_members_user_id` (`user_id`),
  CHECK (`status` IN ('active', 'ended'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Members with role and term.';

CREATE TABLE `meetings` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `committee_id` CHAR(26) NULL,
  `title` VARCHAR(200) NOT NULL,
  `held_at` DATETIME NOT NULL,
  `venue` VARCHAR(160) NULL,
  `agenda` JSON NULL,
  `minutes` LONGTEXT NULL,
  `attendees` JSON NULL,
  `minutes_file_id` CHAR(26) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'scheduled',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_meetings_school_id` (`school_id`),
  KEY `ix_meetings_committee_id` (`committee_id`),
  KEY `ix_meetings_minutes_file_id` (`minutes_file_id`),
  CHECK (`status` IN ('scheduled', 'held', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Meeting with agenda, minutes and attendance.';

CREATE TABLE `resolutions` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `meeting_id` CHAR(26) NOT NULL,
  `number` VARCHAR(20) NULL,
  `text` TEXT NOT NULL,
  `owner_id` CHAR(26) NULL,
  `due_date` DATE NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'open',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_resolutions_school_id` (`school_id`),
  KEY `ix_resolutions_meeting_id` (`meeting_id`),
  KEY `ix_resolutions_owner_id` (`owner_id`),
  CHECK (`status` IN ('open', 'done', 'dropped'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Decisions with follow-up tasks.';

CREATE TABLE `policy_documents` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `title` VARCHAR(200) NOT NULL,
  `category` VARCHAR(60) NULL,
  `version` SMALLINT NOT NULL DEFAULT 1,
  `file_id` CHAR(26) NULL,
  `body` LONGTEXT NULL,
  `applies_to` JSON NULL,
  `effective_from` DATE NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'draft',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_policy_documents_school_id` (`school_id`),
  KEY `ix_policy_documents_file_id` (`file_id`),
  CHECK (`status` IN ('draft', 'active', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='School policies with versions and acknowledgement tracking.';

CREATE TABLE `policy_acknowledgements` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `policy_id` CHAR(26) NOT NULL,
  `user_id` CHAR(26) NOT NULL,
  `acked_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_policy_acknowledgements_school_id` (`school_id`),
  KEY `ix_policy_acknowledgements_policy_id` (`policy_id`),
  KEY `ix_policy_acknowledgements_user_id` (`user_id`),
  UNIQUE KEY `uq_policy_acknowledgements_policy_id_user_id` (`policy_id`, `user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Who acknowledged which policy.';

CREATE TABLE `elections` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `title` VARCHAR(200) NOT NULL,
  `scope` JSON NULL,
  `opens_at` DATETIME NOT NULL,
  `closes_at` DATETIME NOT NULL,
  `candidates` JSON NULL,
  `results` JSON NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'draft',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_elections_school_id` (`school_id`),
  CHECK (`status` IN ('draft', 'open', 'closed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Student council / class captain elections with online voting.';

CREATE TABLE `election_votes` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `election_id` CHAR(26) NOT NULL,
  `voter_hash` VARCHAR(64) NOT NULL,
  `candidate_id` VARCHAR(40) NOT NULL,
  `cast_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_election_votes_school_id` (`school_id`),
  KEY `ix_election_votes_election_id` (`election_id`),
  UNIQUE KEY `uq_election_votes_election_id_voter_hash` (`election_id`, `voter_hash`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Anonymous votes (voter hashed).';


-- ============ Compliance & government reporting ============
CREATE TABLE `govt_reports` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `report_type` VARCHAR(40) NOT NULL,
  `period` VARCHAR(20) NOT NULL,
  `data` JSON NULL,
  `file_id` CHAR(26) NULL,
  `submitted_at` DATETIME NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'draft',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_govt_reports_school_id` (`school_id`),
  KEY `ix_govt_reports_file_id` (`file_id`),
  CHECK (`report_type` IN ('banbeis_census', 'board_registration', 'mpo_salary_sheet', 'stipend_list', 'annual_return', 'custom')),
  CHECK (`status` IN ('draft', 'generated', 'submitted', 'accepted'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Generated regulatory reports with period and file.';

CREATE TABLE `stipend_programs` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(160) NOT NULL,
  `authority` VARCHAR(120) NULL,
  `criteria` JSON NULL,
  `amount` DECIMAL(14,2) NULL,
  `frequency` VARCHAR(40) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_stipend_programs_school_id` (`school_id`),
  CHECK (`frequency` IN ('monthly', 'quarterly', 'half_yearly', 'yearly')),
  CHECK (`status` IN ('active', 'closed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Govt stipend schemes (PESP, secondary stipend) and enrolled students.';

CREATE TABLE `stipend_enrollments` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `program_id` CHAR(26) NOT NULL,
  `student_id` CHAR(26) NOT NULL,
  `enrolled_on` DATE NOT NULL,
  `bank_or_mfs` JSON NULL,
  `disbursements` JSON NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_stipend_enrollments_school_id` (`school_id`),
  KEY `ix_stipend_enrollments_program_id` (`program_id`),
  KEY `ix_stipend_enrollments_student_id` (`student_id`),
  UNIQUE KEY `uq_stipend_enrollments_program_id_student_id` (`program_id`, `student_id`),
  CHECK (`status` IN ('active', 'suspended', 'ended'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Students in a stipend programme with disbursement history.';

CREATE TABLE `consent_records` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `user_id` CHAR(26) NOT NULL,
  `student_id` CHAR(26) NULL,
  `consent_type` VARCHAR(60) NOT NULL,
  `granted` TINYINT(1) NOT NULL,
  `granted_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `expires_at` DATETIME NULL,
  `evidence` JSON NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_consent_records_school_id` (`school_id`),
  KEY `ix_consent_records_user_id` (`user_id`),
  KEY `ix_consent_records_student_id` (`student_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Guardian/staff consents (photo use, data processing, trips).';

CREATE TABLE `data_requests` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `user_id` CHAR(26) NOT NULL,
  `kind` VARCHAR(40) NOT NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'requested',
  `file_id` CHAR(26) NULL,
  `processed_by` CHAR(26) NULL,
  `processed_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_data_requests_school_id` (`school_id`),
  KEY `ix_data_requests_user_id` (`user_id`),
  KEY `ix_data_requests_file_id` (`file_id`),
  KEY `ix_data_requests_processed_by` (`processed_by`),
  CHECK (`kind` IN ('export', 'delete', 'correct')),
  CHECK (`status` IN ('requested', 'processing', 'done', 'rejected'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Data export / deletion requests (privacy).';

CREATE TABLE `retention_policies` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `entity_type` VARCHAR(60) NOT NULL,
  `keep_years` SMALLINT NOT NULL,
  `action` VARCHAR(40) NOT NULL DEFAULT 'archive',
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_retention_policies_school_id` (`school_id`),
  UNIQUE KEY `uq_retention_policies_school_id_entity_type` (`school_id`, `entity_type`),
  CHECK (`action` IN ('archive', 'anonymise', 'delete'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='How long to keep each data class.';


-- ============ Analytics, BI & predictions ============
CREATE TABLE `dashboards` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(120) NOT NULL,
  `role_id` CHAR(26) NULL,
  `user_id` CHAR(26) NULL,
  `layout` JSON NULL,
  `is_default` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_dashboards_school_id` (`school_id`),
  KEY `ix_dashboards_role_id` (`role_id`),
  KEY `ix_dashboards_user_id` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Configurable dashboards per role/user.';

CREATE TABLE `metrics` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `key_name` VARCHAR(80) NOT NULL,
  `name` VARCHAR(160) NOT NULL,
  `definition` JSON NULL,
  `unit` VARCHAR(20) NULL,
  `warn_below` DECIMAL(12,2) NULL,
  `warn_above` DECIMAL(12,2) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_metrics_school_id` (`school_id`),
  UNIQUE KEY `uq_metrics_school_id_key_name` (`school_id`, `key_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Metric catalogue with query and thresholds.';

CREATE TABLE `metric_values` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `metric_id` CHAR(26) NOT NULL,
  `period` DATE NOT NULL,
  `dimension` VARCHAR(80) NULL,
  `value` DECIMAL(14,2) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_metric_values_school_id` (`school_id`),
  KEY `ix_metric_values_metric_id` (`metric_id`),
  UNIQUE KEY `uq_metric_values_metric_id_period_dimension` (`metric_id`, `period`, `dimension`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Time series per metric per dimension.';

CREATE TABLE `risk_scores` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `student_id` CHAR(26) NOT NULL,
  `risk_type` VARCHAR(40) NOT NULL,
  `score` DECIMAL(5,2) NOT NULL,
  `factors` JSON NULL,
  `computed_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `acknowledged_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_risk_scores_school_id` (`school_id`),
  KEY `ix_risk_scores_student_id` (`student_id`),
  KEY `ix_risk_scores_acknowledged_by` (`acknowledged_by`),
  UNIQUE KEY `uq_risk_scores_student_id_risk_type` (`student_id`, `risk_type`),
  CHECK (`risk_type` IN ('dropout', 'fee_default', 'result_decline', 'attendance', 'wellbeing'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Predicted risks per student with explanation, refreshed weekly.';

CREATE TABLE `anomaly_alerts` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `metric_key` VARCHAR(80) NOT NULL,
  `detected_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `expected` DECIMAL(14,2) NULL,
  `actual` DECIMAL(14,2) NULL,
  `severity` VARCHAR(40) NOT NULL DEFAULT 'warn',
  `status` VARCHAR(40) NOT NULL DEFAULT 'open',
  `details` JSON NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_anomaly_alerts_school_id` (`school_id`),
  CHECK (`severity` IN ('info', 'warn', 'critical')),
  CHECK (`status` IN ('open', 'acknowledged', 'resolved'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Detected anomalies (collection drop, attendance dip, SMS spike).';

CREATE TABLE `benchmark_snapshots` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `period` DATE NOT NULL,
  `cohort` VARCHAR(60) NOT NULL,
  `metric_key` VARCHAR(80) NOT NULL,
  `p25` DECIMAL(14,2) NULL,
  `p50` DECIMAL(14,2) NULL,
  `p75` DECIMAL(14,2) NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_benchmark_snapshots_period_cohort_metric_key` (`period`, `cohort`, `metric_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Anonymised cross-school benchmarks (platform level).';


-- ============ AI assistant & automation copilots ============
CREATE TABLE `ai_conversations` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `user_id` CHAR(26) NOT NULL,
  `channel` VARCHAR(40) NOT NULL DEFAULT 'web',
  `title` VARCHAR(200) NULL,
  `context` JSON NULL,
  `last_message_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_ai_conversations_school_id` (`school_id`),
  KEY `ix_ai_conversations_user_id` (`user_id`),
  CHECK (`channel` IN ('web', 'app', 'whatsapp', 'sms'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Assistant chat sessions per user with channel.';

CREATE TABLE `ai_messages` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `conversation_id` CHAR(26) NOT NULL,
  `role` VARCHAR(40) NOT NULL,
  `content` LONGTEXT NULL,
  `tool_calls` JSON NULL,
  `tokens_in` INT NOT NULL DEFAULT 0,
  `tokens_out` INT NOT NULL DEFAULT 0,
  `cost` DECIMAL(10,4) NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_ai_messages_school_id` (`school_id`),
  KEY `ix_ai_messages_conversation_id` (`conversation_id`),
  CHECK (`role` IN ('user', 'assistant', 'tool', 'system'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Messages with tool calls and token usage.';

CREATE TABLE `ai_generations` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `kind` VARCHAR(40) NOT NULL,
  `requested_by` CHAR(26) NULL,
  `input` JSON NULL,
  `output` JSON NULL,
  `model` VARCHAR(60) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'generated',
  `applied_to_type` VARCHAR(60) NULL,
  `applied_to_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_ai_generations_school_id` (`school_id`),
  KEY `ix_ai_generations_requested_by` (`requested_by`),
  CHECK (`kind` IN ('questions', 'remarks', 'lesson_plan', 'notice', 'summary', 'translation', 'report_narrative', 'other')),
  CHECK (`status` IN ('generated', 'reviewed', 'applied', 'discarded'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Generated artefacts (questions, remarks, lesson plans, notices, summaries) with review status.';

CREATE TABLE `ocr_jobs` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `file_id` CHAR(26) NOT NULL,
  `kind` VARCHAR(40) NOT NULL,
  `result` JSON NULL,
  `confidence` DECIMAL(5,2) NULL,
  `status` VARCHAR(40) NOT NULL DEFAULT 'queued',
  `applied_to_type` VARCHAR(60) NULL,
  `applied_to_id` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_ocr_jobs_school_id` (`school_id`),
  KEY `ix_ocr_jobs_file_id` (`file_id`),
  CHECK (`kind` IN ('marks_sheet', 'omr', 'document', 'id_card', 'receipt')),
  CHECK (`status` IN ('queued', 'done', 'needs_review', 'applied', 'failed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='OCR/OMR of uploaded images (marks sheets, documents) into structured data.';

CREATE TABLE `ai_policies` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `features` JSON NULL,
  `data_scope` JSON NULL,
  `monthly_budget` DECIMAL(14,2) NULL,
  `model` VARCHAR(60) NULL,
  `is_enabled` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_ai_policies_school_id` (`school_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Per-school AI settings: enabled features, data scope, monthly budget, model.';

CREATE TABLE `ai_usage_monthly` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `month` DATE NOT NULL,
  `tokens_in` BIGINT NOT NULL DEFAULT 0,
  `tokens_out` BIGINT NOT NULL DEFAULT 0,
  `cost` DECIMAL(14,2) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `ix_ai_usage_monthly_school_id` (`school_id`),
  UNIQUE KEY `uq_ai_usage_monthly_school_id_month` (`school_id`, `month`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Usage rollup for billing.';


-- ============ Marketplace, plugins & developer platform ============
CREATE TABLE `plugins` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `slug` VARCHAR(80) NOT NULL,
  `name` VARCHAR(160) NOT NULL,
  `vendor` VARCHAR(160) NULL,
  `description` TEXT NULL,
  `version` VARCHAR(20) NOT NULL,
  `hooks` JSON NULL,
  `settings_schema` JSON NULL,
  `price_monthly` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `status` VARCHAR(40) NOT NULL DEFAULT 'draft',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_plugins_slug` (`slug`),
  CHECK (`status` IN ('draft', 'published', 'suspended'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Registered plugins/apps.';

CREATE TABLE `plugin_installs` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `plugin_id` CHAR(26) NOT NULL,
  `settings` JSON NULL,
  `is_enabled` TINYINT(1) NOT NULL DEFAULT 1,
  `installed_by` CHAR(26) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_plugin_installs_school_id` (`school_id`),
  KEY `ix_plugin_installs_plugin_id` (`plugin_id`),
  KEY `ix_plugin_installs_installed_by` (`installed_by`),
  UNIQUE KEY `uq_plugin_installs_school_id_plugin_id` (`school_id`, `plugin_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Plugin enabled for a school with settings.';

CREATE TABLE `oauth_clients` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `name` VARCHAR(160) NOT NULL,
  `client_id` VARCHAR(64) NOT NULL,
  `client_secret_hash` VARCHAR(128) NOT NULL,
  `redirect_uris` JSON NULL,
  `scopes` JSON NULL,
  `is_confidential` TINYINT(1) NOT NULL DEFAULT 1,
  `revoked_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_oauth_clients_school_id` (`school_id`),
  UNIQUE KEY `uq_oauth_clients_client_id` (`client_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='OAuth2 clients for third-party apps and SSO.';

CREATE TABLE `oauth_tokens` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `school_id` CHAR(26) NOT NULL COMMENT 'Tenant',
  `client_id` CHAR(26) NOT NULL,
  `user_id` CHAR(26) NULL,
  `token_hash` VARCHAR(128) NOT NULL,
  `kind` VARCHAR(40) NOT NULL,
  `scopes` JSON NULL,
  `expires_at` DATETIME NOT NULL,
  `revoked_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_oauth_tokens_school_id` (`school_id`),
  KEY `ix_oauth_tokens_client_id` (`client_id`),
  KEY `ix_oauth_tokens_user_id` (`user_id`),
  UNIQUE KEY `uq_oauth_tokens_token_hash` (`token_hash`),
  CHECK (`kind` IN ('access', 'refresh', 'authorization_code'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Issued access/refresh tokens.';

CREATE TABLE `template_packs` (
  `id` CHAR(26) NOT NULL COMMENT 'ULID primary key',
  `slug` VARCHAR(80) NOT NULL,
  `name` VARCHAR(160) NOT NULL,
  `kind` VARCHAR(40) NOT NULL,
  `locale` VARCHAR(10) NULL,
  `content` JSON NULL,
  `version` VARCHAR(20) NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_template_packs_slug` (`slug`),
  CHECK (`kind` IN ('documents', 'notifications', 'accounting', 'grading', 'curriculum', 'forms'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Installable packs: document templates, notification templates, chart of accounts, grading scales per board/country.';


